    VALUES
      ('tryout-skd-2026-set-2', 'Tryout SKD 2026 Set 2', 'Tryout SKD lengkap 110 soal (30 TWK, 35 TIU, 45 TKP) dengan timer 100 menit, disusun mengikuti kisi-kisi SKD CPNS terbaru, lengkap dengan pembahasan setiap soal.', 110, 100, 30, 35, 45, 65, 80, 166, true, false, 2)
    RETURNING id INTO v_set_id;
  ELSIF EXISTS (SELECT 1 FROM public.tryout_attempts WHERE exam_set_id = v_set_id) THEN
