         r.explanation_detail, r.explanation_detail_at
  FROM jsonb_to_recordset($skdset2$[{"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C. Nasionalisme yang sesuai Pancasila berarti mendukung bangsa sendiri dengan sepenuh hati tanpa merendahkan bangsa lain, sehingga dukungan kepada atlet Indonesia harus tetap disertai sikap hormat dan sportif kepada atlet negara lain.", "concept": "Soal menguji perbedaan nasionalisme Pancasila dengan chauvinisme. Nasionalisme Pancasila adalah cinta tanah air yang dijiwai sila kedua, Kemanusiaan yang adil dan beradab, sehingga tetap menghormati martabat bangsa lain, sedangkan chauvinisme adalah cinta bangsa yang berlebihan sampai merendahkan bangsa lain.", "steps": ["Kenali masalah utamanya: dukungan kepada atlet tuan rumah berubah menjadi ejekan yang merendahkan atlet negara lain.", "Ingat bahwa nasionalisme Pancasila tidak boleh bertentangan dengan sila kedua yang menuntut sikap adil dan beradab kepada sesama manusia, termasuk bangsa lain.", "Cari opsi yang tetap mempertahankan dukungan kepada atlet Indonesia sekaligus menolak sikap merendahkan pihak lain.", "Opsi C memenuhi kedua syarat itu: mendukung penuh atlet sendiri sambil menjunjung sportivitas dan menghormati lawan."], "options": {"A": "Salah. Membenarkan ejekan yang merendahkan atlet asing merupakan bentuk chauvinisme, bukan nasionalisme Pancasila, dan justru merusak citra Indonesia sebagai tuan rumah.", "B": "Salah. Menghindar dari pertandingan bersifat pasif; masalah sikap penonton tidak terselesaikan dan dukungan kepada atlet bangsa sendiri pun hilang.", "C": "Benar. Dukungan penuh kepada atlet Indonesia yang disertai penghormatan kepada atlet lain dan sikap sportif mencerminkan cinta tanah air yang adil dan beradab.", "D": "Salah. Nasionalisme tidak menuntut tuan rumah mendukung atlet negara lain; yang diminta adalah menghormati lawan, bukan berpindah dukungan.", "E": "Salah. Melarang penonton bersorak berlebihan karena sorakan dukungan yang wajar dan santun justru bagian sah dari suasana pertandingan."}, "tips": "Dalam soal nasionalisme, pilih opsi yang memadukan cinta tanah air dengan penghormatan kepada bangsa lain; waspadai opsi yang terlalu fanatik (chauvinis) maupun yang terlalu pasif atau melarang.", "reference": "Pancasila sila kedua: Kemanusiaan yang adil dan beradab", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 1, "question_text": "Dalam sebuah turnamen bulu tangkis internasional yang digelar di Indonesia, sebagian penonton meneriakkan ejekan bernada merendahkan kepada atlet negara lain setiap kali atlet tersebut melakukan kesalahan. Sejumlah pengguna media sosial menganggap tindakan itu wajar sebagai bentuk dukungan kepada atlet tuan rumah. Di sisi lain, panitia khawatir citra Indonesia sebagai tuan rumah menjadi buruk di mata dunia. Sikap yang paling mencerminkan nasionalisme yang sesuai dengan nilai Pancasila dalam situasi tersebut adalah ....", "options": [{"key": "A", "text": "Mendukung tindakan penonton karena membela atlet sendiri merupakan wujud cinta tanah air yang tidak boleh dibatasi"}, {"key": "B", "text": "Tidak ikut menonton pertandingan agar terhindar dari suasana yang tidak kondusif"}, {"key": "C", "text": "Memberikan dukungan penuh kepada atlet Indonesia sambil tetap menghormati atlet negara lain dan menjunjung sportivitas"}, {"key": "D", "text": "Mendukung atlet negara lain agar Indonesia dipandang sebagai tuan rumah yang netral"}, {"key": "E", "text": "Meminta panitia melarang penonton bersorak selama pertandingan berlangsung"}], "correct_answer": "C", "scores": null, "explanation": "Nasionalisme Pancasila menempatkan cinta tanah air berdampingan dengan penghormatan terhadap bangsa lain sesuai sila kedua, Kemanusiaan yang adil dan beradab. Mendukung atlet sendiri sambil menjaga sportivitas adalah wujud nasionalisme yang sehat. Opsi A mencerminkan chauvinisme, yaitu cinta bangsa yang merendahkan bangsa lain, sedangkan opsi E berlebihan karena menghilangkan bentuk dukungan yang wajar.", "category": "Nasionalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A. Pasal 1 ayat (3) UUD NRI Tahun 1945, yang ditambahkan melalui amandemen ketiga, menyatakan bahwa Negara Indonesia adalah negara hukum.", "concept": "Soal menguji hafalan isi Pasal 1 UUD NRI Tahun 1945. Ayat (1) mengatur bentuk negara (kesatuan) dan bentuk pemerintahan (republik), ayat (2) mengatur kedaulatan rakyat yang dilaksanakan menurut UUD, dan ayat (3) menegaskan prinsip negara hukum.", "steps": ["Perhatikan bahwa soal menanyakan Pasal 1 secara spesifik pada ayat (3).", "Urutkan isi Pasal 1: ayat (1) negara kesatuan berbentuk republik, ayat (2) kedaulatan di tangan rakyat, ayat (3) negara hukum.", "Dengan demikian, rumusan yang sesuai untuk ayat (3) adalah negara hukum."], "options": {"A": "Benar. Pasal 1 ayat (3) berbunyi bahwa Negara Indonesia adalah negara hukum.", "B": "Salah. Negara kesatuan yang berbentuk republik adalah isi Pasal 1 ayat (1), bukan ayat (3).", "C": "Salah. Ciri negara kepulauan yang berciri Nusantara diatur dalam Pasal 25A tentang wilayah negara.", "D": "Salah. Frasa demokrasi berdasarkan Pancasila tidak tercantum dalam Pasal 1; prinsip kedaulatan rakyat ada pada Pasal 1 ayat (2).", "E": "Salah. Kesejahteraan umum merupakan salah satu tujuan negara dalam Pembukaan UUD alinea keempat, bukan isi Pasal 1 ayat (3)."}, "tips": "Hafalkan urutan Pasal 1: ayat (1) bentuk negara, ayat (2) kedaulatan rakyat, ayat (3) negara hukum.", "reference": "UUD NRI Tahun 1945 Pasal 1 ayat (1), (2), dan (3)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 2, "question_text": "Berdasarkan Pasal 1 ayat (3) UUD NRI Tahun 1945, Negara Indonesia adalah negara ....", "options": [{"key": "A", "text": "hukum"}, {"key": "B", "text": "kesatuan yang berbentuk republik"}, {"key": "C", "text": "kepulauan yang berciri Nusantara"}, {"key": "D", "text": "demokrasi berdasarkan Pancasila"}, {"key": "E", "text": "kesejahteraan"}], "correct_answer": "A", "scores": null, "explanation": "Pasal 1 ayat (3) UUD NRI Tahun 1945 hasil amandemen menegaskan bahwa Negara Indonesia adalah negara hukum. Opsi B merupakan isi Pasal 1 ayat (1), yaitu Negara Indonesia ialah negara kesatuan yang berbentuk republik, sedangkan opsi C merupakan isi Pasal 25A tentang wilayah negara.", "category": "Pilar Negara", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E. Pemberian dari rekanan kepada ASN yang berkaitan dengan jabatannya merupakan gratifikasi yang dianggap suap, sehingga harus ditolak dengan sopan, dan bila tidak dapat ditolak wajib dilaporkan kepada KPK paling lambat 30 hari kerja.", "concept": "Soal menguji pemahaman gratifikasi. Menurut UU Pemberantasan Tindak Pidana Korupsi, gratifikasi kepada pegawai negeri yang berhubungan dengan jabatan dan berlawanan dengan kewajibannya dianggap suap, kecuali dilaporkan kepada KPK dalam batas waktu 30 hari kerja sejak diterima.", "steps": ["Identifikasi pemberi dan penerima: perusahaan pemenang tender memberi hadiah kepada pejabat pengadaan yang menangani tender tersebut.", "Hubungan pemberian dengan jabatan Raka jelas, sehingga pemberian itu tergolong gratifikasi meskipun diberikan setelah tender selesai.", "Sikap yang benar adalah menolak secara santun; bila keadaan membuatnya tidak dapat ditolak, penerimaan wajib dilaporkan agar tidak dianggap suap.", "Opsi E memuat penolakan yang sopan sekaligus mekanisme pelaporan resmi, sehingga paling tepat."], "options": {"A": "Salah. Waktu pemberian setelah tender selesai tidak menghapus kaitannya dengan jabatan Raka sebagai pejabat pengadaan, sehingga tetap tergolong gratifikasi.", "B": "Salah. Membagikan hadiah kepada rekan kerja tidak mengubah status gratifikasi; justru melibatkan lebih banyak pegawai dalam penerimaan yang dilarang.", "C": "Salah. Mengembalikan diam-diam beberapa bulan kemudian tidak sesuai mekanisme pelaporan dan melewati batas 30 hari kerja.", "D": "Salah. Menolak sudah benar, tetapi menegur keras di depan umum tidak santun dan tidak diperlukan untuk menegakkan aturan.", "E": "Benar. Menolak dengan sopan dan, bila tidak dapat ditolak, melaporkan ke KPK melalui unit pengendali gratifikasi paling lambat 30 hari kerja sesuai ketentuan."}, "tips": "Kata kunci gratifikasi adalah hubungan dengan jabatan, bukan waktu pemberian; ingat angka batas pelaporan 30 hari kerja.", "reference": "UU No. 31 Tahun 1999 jo. UU No. 20 Tahun 2001 tentang Pemberantasan Tindak Pidana Korupsi Pasal 12B dan Pasal 12C", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 3, "question_text": "Raka adalah ASN yang bertugas di bagian pengadaan barang dan jasa sebuah dinas. Setelah proses tender selesai dan pemenang ditetapkan, perwakilan perusahaan pemenang datang ke kantornya membawa bingkisan berisi telepon genggam keluaran terbaru sebagai tanda terima kasih. Perwakilan itu menegaskan bahwa pemberian tersebut tidak terkait dengan apa pun karena tender sudah selesai. Tindakan yang paling tepat dilakukan Raka adalah ....", "options": [{"key": "A", "text": "Menerima bingkisan tersebut karena diberikan setelah tender selesai sehingga tidak memengaruhi keputusan"}, {"key": "B", "text": "Menerima bingkisan lalu membagikannya kepada rekan satu tim agar adil"}, {"key": "C", "text": "Menerima bingkisan, tetapi mengembalikannya secara diam-diam beberapa bulan kemudian"}, {"key": "D", "text": "Menolak bingkisan dan menegur keras perwakilan perusahaan di depan pegawai lain sebagai pelajaran"}, {"key": "E", "text": "Menolak pemberian tersebut dengan sopan dan, apabila tidak dapat ditolak, melaporkannya kepada KPK melalui unit pengendali gratifikasi paling lambat 30 hari kerja"}], "correct_answer": "E", "scores": null, "explanation": "Pemberian kepada pegawai negeri yang berhubungan dengan jabatannya termasuk gratifikasi yang dianggap suap menurut Pasal 12B UU No. 31 Tahun 1999 jo. UU No. 20 Tahun 2001, dan Pasal 12C mewajibkan penerimaan gratifikasi dilaporkan kepada KPK paling lambat 30 hari kerja. Waktu pemberian setelah tender selesai tidak menghapus kaitannya dengan jabatan, sehingga opsi A keliru. Opsi D menolak dengan cara yang tidak santun dan tidak menyelesaikan kewajiban pelaporan.", "category": "Integritas", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B. Pasal 27 ayat (3) UUD NRI Tahun 1945 menyatakan bahwa setiap warga negara berhak dan wajib ikut serta dalam upaya pembelaan negara.", "concept": "Soal menguji letak ketentuan bela negara dalam UUD. Pasal 27 ayat (3) mengatur hak dan kewajiban ikut serta dalam upaya pembelaan negara, sedangkan Pasal 30 mengatur pertahanan dan keamanan negara beserta sistem pertahanan dan keamanan rakyat semesta.", "steps": ["Perhatikan kata kunci soal: berhak dan wajib ikut serta dalam upaya pembelaan negara.", "Rumusan pembelaan negara terdapat pada Pasal 27 ayat (3), hasil amandemen kedua.", "Bedakan dengan Pasal 30 yang memakai istilah usaha pertahanan dan keamanan negara, sehingga jawaban yang tepat adalah Pasal 27 ayat (3)."], "options": {"A": "Salah. Pasal 26 ayat (1) mengatur siapa yang menjadi warga negara, yaitu orang bangsa Indonesia asli dan orang bangsa lain yang disahkan dengan undang-undang.", "B": "Benar. Pasal 27 ayat (3) memuat hak dan kewajiban setiap warga negara untuk ikut serta dalam upaya pembelaan negara.", "C": "Salah. Pasal 28D ayat (3) mengatur hak setiap warga negara memperoleh kesempatan yang sama dalam pemerintahan.", "D": "Salah. Pasal 30 ayat (2) mengatur pelaksanaan usaha pertahanan dan keamanan melalui sistem pertahanan dan keamanan rakyat semesta oleh TNI, Polri, dan rakyat.", "E": "Salah. Pasal 31 ayat (1) mengatur hak setiap warga negara untuk mendapat pendidikan."}, "tips": "Bedakan istilahnya: pembelaan negara ada di Pasal 27 ayat (3), sedangkan pertahanan dan keamanan negara ada di Pasal 30.", "reference": "UUD NRI Tahun 1945 Pasal 27 ayat (3)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 4, "question_text": "Ketentuan bahwa setiap warga negara berhak dan wajib ikut serta dalam upaya pembelaan negara tercantum dalam UUD NRI Tahun 1945 Pasal ....", "options": [{"key": "A", "text": "26 ayat (1)"}, {"key": "B", "text": "27 ayat (3)"}, {"key": "C", "text": "28D ayat (3)"}, {"key": "D", "text": "30 ayat (2)"}, {"key": "E", "text": "31 ayat (1)"}], "correct_answer": "B", "scores": null, "explanation": "Pasal 27 ayat (3) UUD NRI Tahun 1945 menyatakan bahwa setiap warga negara berhak dan wajib ikut serta dalam upaya pembelaan negara. Pasal 30 ayat (2) mengatur pelaksanaan usaha pertahanan dan keamanan melalui sistem pertahanan dan keamanan rakyat semesta, sedangkan Pasal 28D ayat (3) mengatur hak memperoleh kesempatan yang sama dalam pemerintahan.", "category": "Bela Negara", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D. Butir ketiga Sumpah Pemuda berisi ikrar menjunjung bahasa persatuan, bahasa Indonesia, bukan mengaku berbahasa satu.", "concept": "Soal menguji isi tiga butir Sumpah Pemuda 28 Oktober 1928: bertumpah darah yang satu, tanah Indonesia; berbangsa yang satu, bangsa Indonesia; dan menjunjung bahasa persatuan, bahasa Indonesia. Pilihan kata menjunjung menunjukkan bahwa bahasa daerah tidak dihapuskan.", "steps": ["Ingat urutan ikrar: butir pertama tentang tanah air, butir kedua tentang bangsa, butir ketiga tentang bahasa.", "Butir ketiga tidak memakai kata mengaku, tetapi menjunjung, dan menyebut bahasa persatuan, bukan bahasa negara.", "Karena itu, rumusan yang sesuai adalah menjunjung bahasa persatuan, bahasa Indonesia."], "options": {"A": "Salah. Rumusan mengaku berbahasa satu adalah pengecoh populer; ikrar aslinya memakai kata menjunjung agar bahasa daerah tetap dihargai.", "B": "Salah. Bertumpah darah yang satu, tanah Indonesia adalah butir pertama Sumpah Pemuda.", "C": "Salah. Berbangsa yang satu, bangsa Indonesia adalah butir kedua Sumpah Pemuda.", "D": "Benar. Butir ketiga berbunyi menjunjung bahasa persatuan, bahasa Indonesia.", "E": "Salah. Istilah bahasa negara baru muncul dalam Pasal 36 UUD 1945 yang disahkan pada 18 Agustus 1945, bukan dalam Sumpah Pemuda 1928."}, "tips": "Butir pertama dan kedua memakai kata mengaku, sedangkan butir ketiga memakai menjunjung dan bahasa persatuan; jangan terkecoh opsi berbahasa satu.", "reference": "Ikrar Sumpah Pemuda, Kongres Pemuda II, 28 Oktober 1928; UUD NRI Tahun 1945 Pasal 36", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 5, "question_text": "Butir ketiga ikrar Sumpah Pemuda 28 Oktober 1928 menyatakan bahwa putra dan putri Indonesia ....", "options": [{"key": "A", "text": "mengaku berbahasa satu, bahasa Indonesia"}, {"key": "B", "text": "mengaku bertumpah darah yang satu, tanah Indonesia"}, {"key": "C", "text": "mengaku berbangsa yang satu, bangsa Indonesia"}, {"key": "D", "text": "menjunjung bahasa persatuan, bahasa Indonesia"}, {"key": "E", "text": "menjunjung bahasa negara, bahasa Indonesia"}], "correct_answer": "D", "scores": null, "explanation": "Butir ketiga Sumpah Pemuda berisi ikrar menjunjung bahasa persatuan, bahasa Indonesia. Kata menjunjung, bukan mengaku berbahasa satu, menunjukkan bahwa bahasa daerah tetap dihargai. Kedudukan bahasa Indonesia sebagai bahasa negara baru ditetapkan kemudian dalam Pasal 36 UUD 1945, sehingga opsi E tidak tepat.", "category": "Bahasa Negara", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E. Menguji peraturan perundang-undangan di bawah undang-undang terhadap undang-undang adalah kewenangan Mahkamah Agung, bukan Mahkamah Konstitusi.", "concept": "Soal menguji pembagian kewenangan kekuasaan kehakiman. Pasal 24C ayat (1) memberi MK empat kewenangan: menguji UU terhadap UUD, memutus sengketa kewenangan lembaga negara, memutus pembubaran partai politik, dan memutus perselisihan hasil pemilu. Pasal 24A ayat (1) memberi MA kewenangan mengadili tingkat kasasi dan menguji peraturan di bawah UU terhadap UU.", "steps": ["Perhatikan kata BUKAN: cari kewenangan yang tidak dimiliki MK.", "Cocokkan opsi A sampai D dengan empat kewenangan MK dalam Pasal 24C ayat (1); semuanya sesuai.", "Opsi E menggunakan batu uji undang-undang, bukan UUD, sehingga merupakan kewenangan MA menurut Pasal 24A ayat (1)."], "options": {"A": "Salah sebagai jawaban. Menguji undang-undang terhadap UUD adalah kewenangan MK menurut Pasal 24C ayat (1).", "B": "Salah sebagai jawaban. Memutus sengketa kewenangan lembaga negara yang kewenangannya diberikan UUD termasuk kewenangan MK.", "C": "Salah sebagai jawaban. Memutus pembubaran partai politik merupakan kewenangan MK.", "D": "Salah sebagai jawaban. Memutus perselisihan tentang hasil pemilihan umum merupakan kewenangan MK.", "E": "Benar sebagai jawaban. Menguji peraturan di bawah undang-undang terhadap undang-undang adalah kewenangan Mahkamah Agung, bukan MK."}, "tips": "Lihat batu ujinya: diuji terhadap UUD berarti MK, diuji terhadap undang-undang berarti MA.", "reference": "UUD NRI Tahun 1945 Pasal 24A ayat (1) dan Pasal 24C ayat (1)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 6, "question_text": "Berdasarkan UUD NRI Tahun 1945, kewenangan berikut yang BUKAN merupakan kewenangan Mahkamah Konstitusi adalah ....", "options": [{"key": "A", "text": "Menguji undang-undang terhadap Undang-Undang Dasar"}, {"key": "B", "text": "Memutus sengketa kewenangan lembaga negara yang kewenangannya diberikan oleh Undang-Undang Dasar"}, {"key": "C", "text": "Memutus pembubaran partai politik"}, {"key": "D", "text": "Memutus perselisihan tentang hasil pemilihan umum"}, {"key": "E", "text": "Menguji peraturan perundang-undangan di bawah undang-undang terhadap undang-undang"}], "correct_answer": "E", "scores": null, "explanation": "Menguji peraturan perundang-undangan di bawah undang-undang terhadap undang-undang adalah kewenangan Mahkamah Agung berdasarkan Pasal 24A ayat (1). Opsi A sampai D seluruhnya merupakan kewenangan Mahkamah Konstitusi menurut Pasal 24C ayat (1). Pengecoh A sering tertukar dengan E, padahal batu ujinya berbeda: MK menguji terhadap UUD, sedangkan MA menguji terhadap undang-undang.", "category": "Pilar Negara", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A. Perubahan sila pertama Piagam Jakarta pada sidang PPKI 18 Agustus 1945 menunjukkan kesediaan para pendiri bangsa, khususnya tokoh Islam, berlapang dada demi persatuan dan keutuhan negara yang baru merdeka.", "concept": "Soal menguji nilai historis perumusan Pancasila. Rumusan sila pertama dalam Piagam Jakarta (22 Juni 1945) memuat tujuh kata tentang kewajiban menjalankan syariat Islam bagi pemeluknya; tujuh kata itu dihapus PPKI menjadi Ketuhanan Yang Maha Esa sebagai wujud mengutamakan persatuan di atas kepentingan golongan.", "steps": ["Pahami konteksnya: ada keberatan dari wakil Indonesia bagian timur, lalu para tokoh Islam bersedia menerima perubahan.", "Kesediaan itu merupakan pengorbanan kepentingan golongan agar seluruh wilayah dan rakyat tetap bersatu dalam satu negara.", "Nilai yang paling relevan untuk masa kini adalah mendahulukan persatuan dan kesatuan bangsa, sebagaimana tercermin dalam opsi A."], "options": {"A": "Benar. Penghapusan tujuh kata merupakan bukti para pendiri bangsa mengutamakan persatuan dan kesatuan di atas kepentingan golongan.", "B": "Salah. Peristiwa itu adalah hasil musyawarah dan kesepakatan, bukan kemenangan satu golongan atas golongan lain.", "C": "Salah. Indonesia bukan negara sekuler; Pasal 29 ayat (1) UUD menyatakan negara berdasar atas Ketuhanan Yang Maha Esa.", "D": "Salah. Perubahan itu dicapai melalui musyawarah mufakat, dan tidak ada nilai yang mengharuskan semua keputusan diambil melalui pemungutan suara.", "E": "Salah. Piagam Jakarta tetap bernilai sejarah karena menjadi rancangan Pembukaan UUD yang sebagian besar isinya dipertahankan."}, "tips": "Untuk soal nilai sejarah perumusan Pancasila, jawaban biasanya bertumpu pada persatuan, musyawarah, dan sikap saling menghargai; hindari opsi yang menonjolkan kemenangan satu pihak.", "reference": "UUD NRI Tahun 1945 Pasal 29 ayat (1)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 7, "question_text": "Pada sidang PPKI tanggal 18 Agustus 1945, rumusan sila pertama dalam Piagam Jakarta diubah sehingga menjadi Ketuhanan Yang Maha Esa. Perubahan itu dilakukan setelah ada keberatan dari wakil-wakil Indonesia bagian timur, dan para tokoh Islam bersedia menerimanya. Nilai yang paling menonjol dari peristiwa tersebut bagi kehidupan berbangsa saat ini adalah ....", "options": [{"key": "A", "text": "Kesediaan para pendiri bangsa mendahulukan persatuan dan kesatuan di atas kepentingan golongan"}, {"key": "B", "text": "Kemenangan golongan nasionalis atas golongan agama dalam perumusan dasar negara"}, {"key": "C", "text": "Penegasan bahwa Indonesia adalah negara sekuler yang memisahkan agama dari negara"}, {"key": "D", "text": "Keharusan agar setiap keputusan negara diambil melalui pemungutan suara"}, {"key": "E", "text": "Pengakuan bahwa Piagam Jakarta tidak memiliki nilai sejarah dalam pembentukan negara"}], "correct_answer": "A", "scores": null, "explanation": "Penghapusan tujuh kata dalam sila pertama Piagam Jakarta menunjukkan sikap berlapang dada para tokoh bangsa demi menjaga persatuan dan keutuhan negara yang baru diproklamasikan. Opsi C keliru karena Indonesia bukan negara sekuler; Pasal 29 ayat (1) UUD menyatakan negara berdasar atas Ketuhanan Yang Maha Esa. Opsi B juga keliru karena peristiwa itu merupakan kesepakatan, bukan kemenangan satu golongan.", "category": "Nasionalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C. Hubungan keluarga dengan peserta seleksi adalah konflik kepentingan, sehingga Sinta wajib mengungkapkannya kepada atasan dan tidak ikut menilai adiknya agar seleksi tetap objektif.", "concept": "Soal menguji pengelolaan konflik kepentingan. Konflik kepentingan terjadi ketika kepentingan pribadi, termasuk hubungan keluarga, berpotensi memengaruhi netralitas keputusan pejabat; cara mengelolanya adalah mengungkapkan secara terbuka dan menarik diri dari keputusan yang bersangkutan.", "steps": ["Kenali situasinya: Sinta adalah penilai, sedangkan adiknya peserta, sehingga ada potensi keberpihakan.", "Niat untuk tetap objektif tidak menghapus konflik kepentingan; yang penting adalah keterbukaan dan pemisahan peran.", "Langkah yang benar adalah melapor kepada atasan dan meminta tidak dilibatkan dalam penilaian adiknya, sementara adiknya tetap berhak ikut seleksi.", "Opsi C memenuhi prinsip keterbukaan dan objektivitas tersebut."], "options": {"A": "Salah. Janji pribadi untuk objektif tidak menghilangkan konflik kepentingan dan tidak dapat diawasi oleh pihak lain.", "B": "Salah. Meminta adiknya mundur merugikan hak sah adiknya untuk bersaing; yang perlu mundur dari penilaian adalah Sinta, bukan pesertanya.", "C": "Benar. Mengungkapkan hubungan keluarga kepada atasan dan tidak terlibat menilai adiknya menjaga objektivitas seleksi dan hak adiknya.", "D": "Salah. Sengaja memberi nilai lebih rendah sama tidak objektifnya dengan memberi nilai lebih tinggi dan merugikan adiknya.", "E": "Salah. Merahasiakan hubungan keluarga justru menyembunyikan konflik kepentingan dan berpotensi merusak kepercayaan pada hasil seleksi."}, "tips": "Dalam soal konflik kepentingan, jawaban terbaik hampir selalu memuat dua unsur: mengungkapkan secara terbuka dan tidak ikut mengambil keputusan.", "reference": "UU No. 30 Tahun 2014 tentang Administrasi Pemerintahan (ketentuan konflik kepentingan)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 8, "question_text": "Sinta, seorang ASN, ditunjuk menjadi anggota panitia seleksi penerimaan tenaga pendukung di instansinya. Saat memeriksa daftar pelamar, ia mendapati adik kandungnya termasuk salah satu peserta. Adiknya meminta Sinta tidak perlu memberi tahu siapa pun karena ia yakin dapat lulus dengan kemampuannya sendiri. Sikap yang paling tepat dilakukan Sinta adalah ....", "options": [{"key": "A", "text": "Tetap menjadi penilai dan berjanji pada diri sendiri untuk bersikap objektif"}, {"key": "B", "text": "Meminta adiknya mengundurkan diri dari seleksi agar tidak menimbulkan prasangka"}, {"key": "C", "text": "Melaporkan adanya hubungan keluarga tersebut kepada atasan dan meminta tidak dilibatkan dalam penilaian adiknya"}, {"key": "D", "text": "Tetap menjadi panitia, tetapi memberi nilai lebih rendah kepada adiknya agar terlihat tidak memihak"}, {"key": "E", "text": "Merahasiakan hubungan keluarga itu karena adiknya memang memiliki kemampuan yang baik"}], "correct_answer": "C", "scores": null, "explanation": "Hubungan keluarga dengan peserta seleksi merupakan konflik kepentingan yang wajib diungkapkan, dan pejabat yang bersangkutan sepatutnya tidak terlibat dalam penilaian. Dengan begitu, objektivitas seleksi terjaga dan hak adiknya untuk bersaing tetap terlindungi. Opsi A tetap menyimpan konflik kepentingan meskipun niatnya baik, sedangkan opsi B merugikan hak adiknya yang sah untuk mengikuti seleksi.", "category": "Integritas", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D. Dokter yang mengabdikan keahliannya di pulau terluar untuk meningkatkan kesehatan masyarakat termasuk bentuk bela negara melalui pengabdian sesuai dengan profesi.", "concept": "Soal menguji bentuk keikutsertaan warga negara dalam bela negara menurut UU No. 3 Tahun 2002 tentang Pertahanan Negara, yaitu pendidikan kewarganegaraan, pelatihan dasar kemiliteran secara wajib, pengabdian sebagai prajurit TNI secara sukarela atau wajib, dan pengabdian sesuai dengan profesi.", "steps": ["Identifikasi peran tokoh: ia adalah dokter yang bekerja sesuai keahliannya, bukan prajurit atau peserta pelatihan militer.", "Kegiatannya melayani kesehatan dan memberi penyuluhan di wilayah terluar, yang memperkuat ketahanan masyarakat.", "Bentuk bela negara yang sesuai dengan penggunaan keahlian profesi adalah pengabdian sesuai dengan profesi."], "options": {"A": "Salah. Pendidikan kewarganegaraan adalah pembinaan kesadaran berbangsa melalui jalur pendidikan, bukan pelayanan kesehatan oleh dokter.", "B": "Salah. Pelatihan dasar kemiliteran secara wajib berkaitan dengan latihan militer, sedangkan dokter dalam soal tidak mengikuti pelatihan semacam itu.", "C": "Salah. Dokter tersebut bukan prajurit TNI, sehingga tidak termasuk pengabdian sebagai prajurit TNI secara sukarela.", "D": "Benar. Mengabdikan keahlian kedokteran untuk masyarakat di wilayah terluar merupakan pengabdian sesuai dengan profesi.", "E": "Salah. Komponen Cadangan diatur dalam UU No. 23 Tahun 2019 dan memerlukan pendaftaran serta pelatihan; tidak ada keterangan dokter tersebut menjadi anggotanya."}, "tips": "Jika tokoh dalam soal bela negara bekerja menggunakan keahliannya (dokter, guru, insinyur), jawabannya biasanya pengabdian sesuai dengan profesi.", "reference": "UU No. 3 Tahun 2002 tentang Pertahanan Negara Pasal 9 ayat (2)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 9, "question_text": "Seorang dokter memilih bertugas di puskesmas di sebuah pulau terluar Indonesia. Selain melayani kesehatan warga, ia aktif memberikan penyuluhan tentang kesehatan dan kebersihan lingkungan sehingga derajat kesehatan masyarakat setempat meningkat. Berdasarkan UU No. 3 Tahun 2002 tentang Pertahanan Negara, keikutsertaan dokter tersebut dalam upaya bela negara termasuk bentuk ....", "options": [{"key": "A", "text": "pendidikan kewarganegaraan"}, {"key": "B", "text": "pelatihan dasar kemiliteran secara wajib"}, {"key": "C", "text": "pengabdian sebagai prajurit TNI secara sukarela"}, {"key": "D", "text": "pengabdian sesuai dengan profesi"}, {"key": "E", "text": "keanggotaan Komponen Cadangan"}], "correct_answer": "D", "scores": null, "explanation": "Pasal 9 ayat (2) UU No. 3 Tahun 2002 menyebutkan bahwa keikutsertaan warga negara dalam upaya bela negara diselenggarakan melalui pendidikan kewarganegaraan, pelatihan dasar kemiliteran secara wajib, pengabdian sebagai prajurit TNI secara sukarela atau wajib, serta pengabdian sesuai dengan profesi. Dokter yang mengabdikan keahliannya di wilayah terluar termasuk pengabdian sesuai profesi. Ia bukan prajurit TNI dan tidak disebutkan terdaftar sebagai anggota Komponen Cadangan, sehingga opsi C dan E tidak tepat.", "category": "Bela Negara", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B. Pasal 18B ayat (2) UUD NRI Tahun 1945 menyatakan negara mengakui dan menghormati kesatuan-kesatuan masyarakat hukum adat beserta hak-hak tradisionalnya sepanjang masih hidup dan sesuai prinsip NKRI.", "concept": "Soal menguji ketentuan konstitusi tentang pengakuan masyarakat hukum adat. Pasal 18B ayat (2) menjadi dasar langsung pengakuan tersebut dengan syarat masih hidup, sesuai perkembangan masyarakat dan prinsip NKRI, serta diatur dengan undang-undang.", "steps": ["Tentukan kata kunci soal: pengakuan negara terhadap kesatuan masyarakat hukum adat dan hak tradisionalnya.", "Ketentuan yang memuat rumusan tersebut secara langsung adalah Pasal 18B ayat (2).", "Bandingkan dengan opsi lain yang mengatur otonomi daerah, wilayah negara, perekonomian, dan perubahan UUD, yang tidak secara langsung membahas masyarakat hukum adat."], "options": {"A": "Salah. Pasal 18 ayat (5) mengatur otonomi seluas-luasnya bagi pemerintahan daerah, kecuali urusan yang ditentukan undang-undang sebagai urusan Pemerintah Pusat.", "B": "Benar. Pasal 18B ayat (2) secara langsung mengatur pengakuan dan penghormatan negara terhadap kesatuan masyarakat hukum adat beserta hak tradisionalnya.", "C": "Salah. Pasal 25A mengatur Indonesia sebagai negara kepulauan berciri Nusantara dengan wilayah yang batas dan haknya ditetapkan undang-undang.", "D": "Salah. Pasal 33 ayat (4) mengatur prinsip penyelenggaraan perekonomian nasional, seperti kebersamaan, efisiensi berkeadilan, dan berkelanjutan.", "E": "Salah. Pasal 37 ayat (5) menegaskan bahwa bentuk NKRI tidak dapat diubah."}, "tips": "Ingat pasangan pasal 18B: ayat (1) tentang satuan pemerintahan daerah yang bersifat khusus atau istimewa, ayat (2) tentang masyarakat hukum adat.", "reference": "UUD NRI Tahun 1945 Pasal 18B ayat (2)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 10, "question_text": "Masyarakat adat di sebuah kabupaten secara turun-temurun mengelola hutan ulayat berdasarkan aturan adat yang masih ditaati hingga kini. Ketika pemerintah daerah menyusun rencana tata ruang, para tokoh adat meminta agar keberadaan dan hak tradisional mereka diakui dalam kebijakan tersebut. Ketentuan UUD NRI Tahun 1945 yang secara langsung menjadi dasar pengakuan negara terhadap kesatuan masyarakat hukum adat beserta hak-hak tradisionalnya adalah ....", "options": [{"key": "A", "text": "Pasal 18 ayat (5)"}, {"key": "B", "text": "Pasal 18B ayat (2)"}, {"key": "C", "text": "Pasal 25A"}, {"key": "D", "text": "Pasal 33 ayat (4)"}, {"key": "E", "text": "Pasal 37 ayat (5)"}], "correct_answer": "B", "scores": null, "explanation": "Pasal 18B ayat (2) menyatakan bahwa negara mengakui dan menghormati kesatuan-kesatuan masyarakat hukum adat beserta hak-hak tradisionalnya sepanjang masih hidup dan sesuai dengan perkembangan masyarakat dan prinsip Negara Kesatuan Republik Indonesia, yang diatur dalam undang-undang. Pasal 18 ayat (5) mengatur otonomi daerah seluas-luasnya, sedangkan Pasal 33 ayat (4) mengatur prinsip penyelenggaraan perekonomian nasional.", "category": "Pilar Negara", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A. Nota kesepahaman yang melibatkan instansi pemerintah wajib menggunakan bahasa Indonesia, dan karena melibatkan pihak asing, dokumen itu juga ditulis dalam bahasa nasional pihak asing dan/atau bahasa Inggris.", "concept": "Soal menguji kewajiban penggunaan bahasa Indonesia dalam dokumen perjanjian menurut UU No. 24 Tahun 2009. Bahasa Indonesia wajib digunakan dalam nota kesepahaman atau perjanjian yang melibatkan lembaga negara atau instansi pemerintah, sementara versi bahasa asing ditambahkan bila ada pihak asing.", "steps": ["Identifikasi pihak yang terlibat: pemerintah provinsi (instansi pemerintah RI) dan universitas dari Jepang (pihak asing).", "Pasal 31 ayat (1) mewajibkan bahasa Indonesia untuk nota kesepahaman yang melibatkan instansi pemerintah.", "Pasal 31 ayat (2) menambahkan bahwa perjanjian dengan pihak asing ditulis juga dalam bahasa nasional pihak asing dan/atau bahasa Inggris.", "Gabungan kedua ketentuan itu sesuai dengan opsi A."], "options": {"A": "Benar. Bahasa Indonesia wajib digunakan, dan dokumen juga ditulis dalam bahasa Jepang dan/atau bahasa Inggris karena melibatkan pihak asing.", "B": "Salah. Status bahasa Inggris sebagai bahasa internasional tidak menghapus kewajiban penggunaan bahasa Indonesia dalam perjanjian instansi pemerintah.", "C": "Salah. Bahasa mitra asing hanya menjadi versi tambahan, bukan pengganti bahasa Indonesia.", "D": "Salah. Undang-undang tidak memberi kebebasan memilih satu bahasa saja; bahasa Indonesia bersifat wajib.", "E": "Salah. Undang-undang justru mengatur agar perjanjian dengan pihak asing ditulis juga dalam bahasa pihak asing dan/atau bahasa Inggris."}, "tips": "Untuk perjanjian dengan pihak asing, rumusnya: bahasa Indonesia wajib, ditambah bahasa pihak asing dan/atau bahasa Inggris.", "reference": "UU No. 24 Tahun 2009 Pasal 31 ayat (1) dan ayat (2)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 11, "question_text": "Sebuah pemerintah provinsi akan menandatangani nota kesepahaman kerja sama pendidikan dengan sebuah universitas dari Jepang. Staf bagian hukum mengusulkan agar dokumen hanya dibuat dalam bahasa Inggris supaya praktis karena kedua pihak sama-sama memahami bahasa tersebut. Berdasarkan UU No. 24 Tahun 2009, ketentuan yang tepat mengenai bahasa dalam nota kesepahaman itu adalah ....", "options": [{"key": "A", "text": "Wajib menggunakan bahasa Indonesia, dan juga ditulis dalam bahasa nasional pihak asing tersebut dan/atau bahasa Inggris"}, {"key": "B", "text": "Cukup menggunakan bahasa Inggris karena merupakan bahasa internasional"}, {"key": "C", "text": "Cukup menggunakan bahasa Jepang karena mengikuti bahasa pihak mitra"}, {"key": "D", "text": "Boleh menggunakan satu bahasa apa saja yang disepakati kedua pihak"}, {"key": "E", "text": "Wajib menggunakan bahasa Indonesia saja tanpa versi dalam bahasa lain"}], "correct_answer": "A", "scores": null, "explanation": "Pasal 31 ayat (1) UU No. 24 Tahun 2009 mewajibkan penggunaan bahasa Indonesia dalam nota kesepahaman atau perjanjian yang melibatkan lembaga negara atau instansi pemerintah Republik Indonesia. Pasal 31 ayat (2) menambahkan bahwa perjanjian yang melibatkan pihak asing ditulis juga dalam bahasa nasional pihak asing tersebut dan/atau bahasa Inggris. Opsi B dan D keliru karena meniadakan bahasa Indonesia, sedangkan opsi E keliru karena justru menolak versi bahasa asing yang diatur undang-undang.", "category": "Bahasa Negara", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E. Soekarno memperkenalkan istilah Pancasila sebagai nama dasar negara dalam pidatonya pada 1 Juni 1945 di sidang pertama BPUPKI.", "concept": "Soal menguji sejarah perumusan dasar negara pada sidang pertama BPUPKI (29 Mei sampai 1 Juni 1945). Tiga tokoh menyampaikan usulan dasar negara, yaitu Mohammad Yamin, Soepomo, dan Soekarno, tetapi hanya Soekarno yang menamai usulannya Pancasila; tanggal pidatonya kini diperingati sebagai Hari Lahir Pancasila.", "steps": ["Ingat urutan penyampaian usulan dasar negara: Mohammad Yamin (29 Mei), Soepomo (31 Mei), dan Soekarno (1 Juni 1945).", "Dari ketiganya, hanya Soekarno yang menggunakan istilah Pancasila untuk menyebut rumusan lima dasar negara.", "Tanggal 1 Juni kemudian ditetapkan sebagai Hari Lahir Pancasila, sehingga jawabannya Soekarno."], "options": {"A": "Salah. Mohammad Yamin menyampaikan gagasan dasar negara pada 29 Mei 1945, tetapi tidak menamainya Pancasila.", "B": "Salah. Soepomo menyampaikan gagasan negara integralistik pada 31 Mei 1945 dan tidak menggunakan istilah Pancasila.", "C": "Salah. Mohammad Hatta tidak menyampaikan usulan bernama Pancasila dalam sidang pertama BPUPKI; ia berperan antara lain dalam Panitia Sembilan dan PPKI.", "D": "Salah. Radjiman Wedyodiningrat adalah ketua BPUPKI yang memimpin sidang, bukan pengusul istilah Pancasila.", "E": "Benar. Soekarno memperkenalkan istilah Pancasila dalam pidato 1 Juni 1945, yang ditetapkan sebagai Hari Lahir Pancasila."}, "tips": "Pasangkan tokoh dengan tanggal: Yamin 29 Mei, Soepomo 31 Mei, Soekarno 1 Juni; hanya Soekarno yang memakai nama Pancasila.", "reference": "Keputusan Presiden No. 24 Tahun 2016 tentang Hari Lahir Pancasila", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 12, "question_text": "Istilah Pancasila sebagai nama dasar negara pertama kali dikemukakan dalam sidang pertama BPUPKI oleh ....", "options": [{"key": "A", "text": "Mohammad Yamin"}, {"key": "B", "text": "Soepomo"}, {"key": "C", "text": "Mohammad Hatta"}, {"key": "D", "text": "Radjiman Wedyodiningrat"}, {"key": "E", "text": "Soekarno"}], "correct_answer": "E", "scores": null, "explanation": "Soekarno memperkenalkan istilah Pancasila dalam pidatonya pada 1 Juni 1945 di sidang pertama BPUPKI, dan tanggal itu ditetapkan sebagai Hari Lahir Pancasila melalui Keputusan Presiden No. 24 Tahun 2016. Mohammad Yamin dan Soepomo juga menyampaikan gagasan tentang dasar negara dalam sidang tersebut, tetapi tidak menamainya Pancasila. Radjiman Wedyodiningrat adalah ketua BPUPKI.", "category": "Nasionalisme", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B. Huruf terakhir dalam akronim BerAKHLAK adalah K untuk Kolaboratif, sehingga nilai dasar ASN lengkapnya adalah Berorientasi Pelayanan, Akuntabel, Kompeten, Harmonis, Loyal, Adaptif, dan Kolaboratif.", "concept": "Soal menguji hafalan nilai dasar (core values) ASN BerAKHLAK yang diluncurkan pemerintah pada 2021 dan kemudian dimuat dalam UU No. 20 Tahun 2023 tentang ASN. Setiap huruf mewakili satu nilai yang menjadi pedoman perilaku ASN.", "steps": ["Uraikan akronim BerAKHLAK huruf demi huruf: Ber (Berorientasi Pelayanan), A (Akuntabel), K (Kompeten), H (Harmonis), L (Loyal), A (Adaptif), K (Kolaboratif).", "Enam nilai pertama sudah disebutkan dalam soal, sehingga yang tersisa adalah huruf K terakhir.", "Nilai yang diwakili huruf K terakhir adalah Kolaboratif."], "options": {"A": "Salah. Kreatif adalah sikap positif, tetapi tidak termasuk unsur BerAKHLAK; kreativitas tercakup dalam nilai Adaptif.", "B": "Benar. Kolaboratif adalah nilai ketujuh BerAKHLAK, yaitu membangun kerja sama yang sinergis.", "C": "Salah. Konsisten tidak termasuk unsur BerAKHLAK meskipun berawalan huruf K.", "D": "Salah. Komunikatif tidak termasuk dalam akronim BerAKHLAK.", "E": "Salah. Komitmen bukan unsur BerAKHLAK; pengecoh ini memanfaatkan huruf awal K."}, "tips": "Semua pengecoh berawalan K; ingat bahwa BerAKHLAK hanya memiliki dua nilai berhuruf K, yaitu Kompeten dan Kolaboratif.", "reference": "UU No. 20 Tahun 2023 tentang Aparatur Sipil Negara; Surat Edaran Menteri PANRB No. 20 Tahun 2021", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 13, "question_text": "Nilai dasar ASN yang dikenal dengan akronim BerAKHLAK terdiri atas Berorientasi Pelayanan, Akuntabel, Kompeten, Harmonis, Loyal, Adaptif, dan ....", "options": [{"key": "A", "text": "Kreatif"}, {"key": "B", "text": "Kolaboratif"}, {"key": "C", "text": "Konsisten"}, {"key": "D", "text": "Komunikatif"}, {"key": "E", "text": "Komitmen"}], "correct_answer": "B", "scores": null, "explanation": "BerAKHLAK merupakan akronim dari Berorientasi Pelayanan, Akuntabel, Kompeten, Harmonis, Loyal, Adaptif, dan Kolaboratif; nilai-nilai dasar ini juga dimuat dalam UU No. 20 Tahun 2023 tentang Aparatur Sipil Negara. Kreatif, konsisten, dan komunikatif memang sikap yang baik, tetapi tidak termasuk unsur akronim tersebut.", "category": "Integritas", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C. Menurut UU No. 23 Tahun 2019, Komponen Cadangan disiapkan untuk dikerahkan melalui mobilisasi guna memperbesar dan memperkuat kekuatan dan kemampuan Komponen Utama, dan keikutsertaan warga negara di dalamnya bersifat sukarela.", "concept": "Soal menguji komponen pertahanan negara menurut UU No. 23 Tahun 2019. Komponen Utama adalah TNI; Komponen Cadangan memperbesar dan memperkuat Komponen Utama; Komponen Pendukung meningkatkan kekuatan kedua komponen tersebut. Komponen Cadangan terdiri atas warga negara, sumber daya alam, sumber daya buatan, serta sarana dan prasarana nasional.", "steps": ["Ingat pembagian tiga komponen pertahanan: Komponen Utama (TNI), Komponen Cadangan, dan Komponen Pendukung.", "Fungsi Komponen Cadangan adalah memperbesar dan memperkuat Komponen Utama melalui mobilisasi.", "Warga negara menjadi anggota Komponen Cadangan melalui pendaftaran sukarela dan seleksi, bukan kewajiban bagi semua warga.", "Pernyataan yang memuat kedua unsur tersebut adalah opsi C."], "options": {"A": "Salah. Komponen Utama adalah TNI; Komponen Cadangan hanya memperbesar dan memperkuat Komponen Utama.", "B": "Salah. Keanggotaan Komponen Cadangan bersifat sukarela melalui pendaftaran dan seleksi, bukan kewajiban bagi setiap warga berusia 18 tahun.", "C": "Benar. Komponen Cadangan memperbesar dan memperkuat Komponen Utama, dan keikutsertaan warga negara di dalamnya bersifat sukarela.", "D": "Salah. Komponen Cadangan juga mencakup warga negara, bukan hanya sumber daya alam serta sarana dan prasarana nasional.", "E": "Salah. Komponen Cadangan dibina oleh Kementerian Pertahanan dan saat mobilisasi berada di bawah Panglima TNI, bukan di bawah Polri."}, "tips": "Ingat kata kunci Komponen Cadangan: memperbesar dan memperkuat Komponen Utama, serta sukarela; opsi yang menyebut wajib bagi semua warga hampir pasti salah.", "reference": "UU No. 23 Tahun 2019 tentang Pengelolaan Sumber Daya Nasional untuk Pertahanan Negara", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 14, "question_text": "Menurut UU No. 23 Tahun 2019 tentang Pengelolaan Sumber Daya Nasional untuk Pertahanan Negara, pernyataan yang tepat mengenai Komponen Cadangan adalah ....", "options": [{"key": "A", "text": "Komponen Cadangan merupakan komponen utama dalam menghadapi ancaman militer"}, {"key": "B", "text": "Setiap warga negara yang telah berusia 18 tahun wajib menjadi anggota Komponen Cadangan"}, {"key": "C", "text": "Komponen Cadangan disiapkan untuk memperbesar dan memperkuat kekuatan dan kemampuan Komponen Utama, dan keikutsertaan warga negara di dalamnya bersifat sukarela"}, {"key": "D", "text": "Komponen Cadangan hanya terdiri atas sumber daya alam serta sarana dan prasarana nasional"}, {"key": "E", "text": "Komponen Cadangan berada di bawah kendali Kepolisian Negara Republik Indonesia"}], "correct_answer": "C", "scores": null, "explanation": "UU No. 23 Tahun 2019 mendefinisikan Komponen Cadangan sebagai sumber daya nasional yang disiapkan untuk dikerahkan melalui mobilisasi guna memperbesar dan memperkuat kekuatan dan kemampuan Komponen Utama, yaitu TNI. Warga negara menjadi calon anggota Komponen Cadangan melalui pendaftaran secara sukarela, sehingga opsi B keliru. Opsi D keliru karena Komponen Cadangan juga mencakup warga negara, bukan hanya sumber daya alam dan sarana prasarana, sedangkan opsi A keliru karena komponen utama adalah TNI.", "category": "Bela Negara", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D. Pasal 28J ayat (2) menyatakan bahwa dalam menjalankan hak dan kebebasannya, setiap orang wajib tunduk pada pembatasan yang ditetapkan dengan undang-undang, termasuk demi keamanan dan ketertiban umum, sehingga larangan aksi di lingkungan rumah sakit sah secara konstitusional.", "concept": "Soal menguji dasar konstitusional pembatasan hak asasi manusia. Hak menyampaikan pendapat dijamin UUD, tetapi bukan hak mutlak; Pasal 28J ayat (2) membolehkan pembatasan melalui undang-undang untuk menghormati hak orang lain dan memenuhi tuntutan yang adil, seperti pertimbangan moral, nilai agama, keamanan, dan ketertiban umum.", "steps": ["Pahami kasusnya: hak berunjuk rasa dibatasi di lingkungan rumah sakit berdasarkan undang-undang tentang kemerdekaan menyampaikan pendapat.", "Soal menanyakan pasal yang menjadi dasar dibolehkannya pembatasan hak, bukan pasal yang memuat hak itu sendiri.", "Pasal yang mengatur pembatasan hak melalui undang-undang adalah Pasal 28J ayat (2).", "Pembatasan ini bertujuan melindungi hak pasien atas ketenangan dan pelayanan kesehatan."], "options": {"A": "Salah. Pasal 28E ayat (3) memuat hak berserikat, berkumpul, dan mengeluarkan pendapat, yaitu hak yang sedang dibatasi, bukan dasar pembatasannya.", "B": "Salah. Pasal 28I ayat (1) memuat hak yang tidak dapat dikurangi dalam keadaan apa pun, seperti hak hidup dan hak untuk tidak disiksa.", "C": "Salah. Pasal 28D ayat (1) memuat hak atas pengakuan, jaminan, perlindungan, dan kepastian hukum yang adil serta perlakuan yang sama di hadapan hukum.", "D": "Benar. Pasal 28J ayat (2) menjadi dasar pembatasan hak dan kebebasan melalui undang-undang demi hak orang lain serta keamanan dan ketertiban umum.", "E": "Salah. Pasal 28J ayat (1) hanya mewajibkan setiap orang menghormati hak asasi orang lain, tanpa mengatur pembatasan melalui undang-undang."}, "tips": "Ingat: Pasal 28J ayat (1) berisi kewajiban menghormati HAM orang lain, sedangkan ayat (2) berisi pembatasan HAM melalui undang-undang.", "reference": "UUD NRI Tahun 1945 Pasal 28J ayat (2); UU No. 9 Tahun 1998 tentang Kemerdekaan Menyampaikan Pendapat di Muka Umum", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 15, "question_text": "Sekelompok warga berencana menggelar unjuk rasa di halaman sebuah rumah sakit umum daerah. Aparat kemudian meminta mereka memindahkan aksi ke lokasi lain karena undang-undang tentang kemerdekaan menyampaikan pendapat di muka umum mengecualikan lingkungan rumah sakit sebagai tempat aksi. Sebagian peserta menilai tindakan itu melanggar hak konstitusional mereka. Ketentuan UUD NRI Tahun 1945 yang menjadi dasar dibolehkannya pembatasan hak dan kebebasan seseorang melalui undang-undang seperti dalam kasus tersebut adalah ....", "options": [{"key": "A", "text": "Pasal 28E ayat (3)"}, {"key": "B", "text": "Pasal 28I ayat (1)"}, {"key": "C", "text": "Pasal 28D ayat (1)"}, {"key": "D", "text": "Pasal 28J ayat (2)"}, {"key": "E", "text": "Pasal 28J ayat (1)"}], "correct_answer": "D", "scores": null, "explanation": "Pasal 28J ayat (2) menyatakan bahwa dalam menjalankan hak dan kebebasannya, setiap orang wajib tunduk pada pembatasan yang ditetapkan dengan undang-undang untuk menjamin penghormatan atas hak dan kebebasan orang lain serta memenuhi tuntutan yang adil, termasuk pertimbangan keamanan dan ketertiban umum. Pasal 28E ayat (3) justru memuat hak berserikat, berkumpul, dan mengeluarkan pendapat yang sedang dibatasi. Pasal 28J ayat (1) hanya memuat kewajiban menghormati hak asasi orang lain, tanpa mengatur pembatasan melalui undang-undang.", "category": "Pilar Negara", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C. Menurut KBBI, bentuk baku keempat kata tersebut adalah analisis, risiko, praktik, dan kuitansi, dan hanya opsi C yang seluruhnya memuat bentuk baku.", "concept": "Soal menguji penguasaan kata baku sesuai KBBI. Banyak kata serapan sering ditulis dalam bentuk tidak baku karena kebiasaan lisan, misalnya analisa, resiko, praktek, dan kwitansi.", "steps": ["Tentukan bentuk baku setiap kata: analisis (bukan analisa), risiko (bukan resiko), praktik (bukan praktek), kuitansi (bukan kwitansi).", "Periksa setiap opsi dan coret yang memuat sedikitnya satu bentuk tidak baku.", "Hanya opsi C yang keempat katanya baku."], "options": {"A": "Salah. Kata analisa tidak baku; bentuk bakunya analisis.", "B": "Salah. Kata resiko tidak baku; bentuk bakunya risiko.", "C": "Benar. Analisis, risiko, praktik, dan kuitansi seluruhnya merupakan bentuk baku menurut KBBI.", "D": "Salah. Kata praktek dan kwitansi tidak baku; bentuk bakunya praktik dan kuitansi.", "E": "Salah. Tiga kata pertama sudah baku, tetapi kwitansi tidak baku; bentuk bakunya kuitansi."}, "tips": "Untuk soal kata baku berbentuk kelompok, cukup temukan satu kata tidak baku untuk menggugurkan opsi; waspadai opsi yang hampir benar seperti E.", "reference": "Kamus Besar Bahasa Indonesia (KBBI), Badan Pengembangan dan Pembinaan Bahasa", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 16, "question_text": "Kelompok kata berikut yang seluruhnya merupakan bentuk baku sesuai KBBI adalah ....", "options": [{"key": "A", "text": "analisa, risiko, praktik, kuitansi"}, {"key": "B", "text": "analisis, resiko, praktik, kuitansi"}, {"key": "C", "text": "analisis, risiko, praktik, kuitansi"}, {"key": "D", "text": "analisis, risiko, praktek, kwitansi"}, {"key": "E", "text": "analisis, risiko, praktik, kwitansi"}], "correct_answer": "C", "scores": null, "explanation": "Menurut KBBI, bentuk baku yang benar adalah analisis, risiko, praktik, dan kuitansi. Bentuk analisa, resiko, praktek, dan kwitansi merupakan bentuk tidak baku. Opsi E tampak hampir benar, tetapi masih memuat kata kwitansi yang tidak baku.", "category": "Bahasa Negara", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E. UU No. 24 Tahun 2009 melarang setiap orang memakai Bendera Negara untuk reklame atau iklan komersial serta mencetak huruf, gambar, atau tanda lain pada Bendera Negara, sehingga tindakan toko itu tidak dibenarkan meskipun berniat memeriahkan kemerdekaan.", "concept": "Soal menguji larangan terkait Bendera Negara dalam UU No. 24 Tahun 2009. Larangan itu antara lain merusak atau menodai bendera, memakainya untuk reklame atau iklan komersial, mengibarkan bendera yang rusak atau luntur, mencetak atau menulis tanda apa pun pada bendera, serta memakainya untuk atap atau pembungkus barang.", "steps": ["Identifikasi tindakan toko: mencetak logo dan nama toko di tengah bendera dan memakainya sebagai materi promosi.", "Tindakan itu memenuhi dua larangan sekaligus, yaitu mencetak tanda lain pada Bendera Negara dan memakai bendera untuk iklan komersial.", "Niat baik memeriahkan Hari Kemerdekaan tidak menghapus larangan undang-undang, sehingga penilaian yang tepat adalah opsi E."], "options": {"A": "Salah. Niat memeriahkan Hari Kemerdekaan tidak membenarkan pemakaian bendera untuk iklan dan pencetakan logo di atasnya.", "B": "Salah. Ukuran lebar dua pertiga dari panjang memang ketentuan bendera, tetapi kesesuaian ukuran tidak menghapus larangan mencetak tanda dan beriklan.", "C": "Salah. Tiang yang layak hanya menyangkut tata cara pengibaran, sedangkan pelanggaran utamanya ada pada pencetakan logo dan tujuan komersial.", "D": "Salah. Larangan mengibarkan bendera rusak atau luntur hanya salah satu larangan; mencetak tanda dan memakai bendera untuk reklame juga dilarang.", "E": "Benar. UU No. 24 Tahun 2009 melarang mencetak tanda apa pun pada Bendera Negara dan memakainya untuk reklame atau iklan komersial."}, "tips": "Bendera Negara tidak boleh ditambahi tulisan, logo, atau gambar apa pun dan tidak boleh dijadikan alat iklan, apa pun niatnya.", "reference": "UU No. 24 Tahun 2009 tentang Bendera, Bahasa, dan Lambang Negara, serta Lagu Kebangsaan Pasal 24", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 17, "question_text": "Menjelang peringatan Hari Kemerdekaan, sebuah toko memasang Bendera Merah Putih yang dicetak logo dan nama toko di bagian tengahnya sebagai materi promosi diskon kemerdekaan. Pemilik toko beralasan bahwa hal itu justru menunjukkan semangat nasionalisme dan ikut memeriahkan suasana. Penilaian yang paling tepat terhadap tindakan tersebut adalah ....", "options": [{"key": "A", "text": "Dibenarkan karena dilakukan dalam rangka memeriahkan Hari Kemerdekaan"}, {"key": "B", "text": "Dibenarkan selama ukuran bendera sesuai ketentuan, yaitu lebar dua pertiga dari panjang"}, {"key": "C", "text": "Dibenarkan asalkan bendera dikibarkan pada tiang yang layak"}, {"key": "D", "text": "Tidak dibenarkan hanya apabila bendera dalam keadaan rusak atau luntur"}, {"key": "E", "text": "Tidak dibenarkan karena UU No. 24 Tahun 2009 melarang mencetak tanda apa pun pada Bendera Negara dan memakainya untuk reklame atau iklan komersial"}], "correct_answer": "E", "scores": null, "explanation": "Pasal 24 UU No. 24 Tahun 2009 melarang setiap orang memakai Bendera Negara untuk reklame atau iklan komersial serta mencetak huruf, angka, gambar, atau tanda lain pada Bendera Negara. Niat memeriahkan kemerdekaan tidak menghapus larangan tersebut, sehingga opsi A keliru. Opsi D keliru karena larangan mengibarkan bendera yang rusak atau luntur hanyalah salah satu dari beberapa larangan.", "category": "Nasionalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A. Menandatangani daftar hadir rapat yang tidak diikuti berarti ikut membuat pertanggungjawaban fiktif, sehingga Dimas harus menolak dengan sopan, menjelaskan alasannya, dan melapor melalui saluran resmi bila praktik itu berlanjut.", "concept": "Soal menguji integritas ASN dalam menghadapi tekanan untuk memalsukan dokumen pertanggungjawaban keuangan. Integritas berarti konsisten bertindak jujur meski ada tekanan senior atau alasan kebiasaan, serta menggunakan jalur pengaduan resmi untuk menghentikan pelanggaran.", "steps": ["Kenali pelanggarannya: daftar hadir palsu dipakai untuk mencairkan anggaran perjalanan dinas yang tidak pernah dilaksanakan.", "Alasan bahwa dana dipakai untuk kantor dan sudah menjadi kebiasaan tidak mengubah sifat pemalsuan yang merugikan keuangan negara.", "Sikap berintegritas adalah menolak secara santun, menjelaskan alasannya, dan menempuh pelaporan resmi bila praktik itu terus terjadi.", "Opsi A memuat seluruh unsur tersebut."], "options": {"A": "Benar. Menolak dengan sopan, menjelaskan bahwa itu pertanggungjawaban fiktif, dan melapor ke pengawasan internal bila berlanjut adalah sikap berintegritas.", "B": "Salah. Penggunaan dana untuk kantor tidak membenarkan dokumen palsu; pertanggungjawaban fiktif tetap merugikan keuangan negara.", "C": "Salah. Tidak mengambil uang tidak menghapus keterlibatan Dimas, karena tanda tangannya tetap menjadi bagian dari pemalsuan.", "D": "Salah. Menolak sudah tepat, tetapi langsung mengunggah ke media sosial melewati saluran pengaduan resmi dan berisiko menimbulkan masalah baru.", "E": "Salah. Menunda dan berharap senior lupa adalah sikap menghindar yang tidak menyelesaikan masalah dan membiarkan pelanggaran terus terjadi."}, "tips": "Alasan seperti sudah biasa atau untuk kepentingan kantor adalah jebakan; dokumen palsu tetap pelanggaran, dan pelaporan sebaiknya lewat saluran resmi, bukan media sosial.", "reference": "PP No. 94 Tahun 2021 tentang Disiplin Pegawai Negeri Sipil", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 18, "question_text": "Dimas baru tiga bulan bekerja sebagai ASN. Seorang seniornya meminta Dimas menandatangani daftar hadir rapat di luar kota yang tidak pernah ia ikuti agar anggaran perjalanan dinas dapat dicairkan. Senior itu mengatakan bahwa praktik tersebut sudah biasa dan uangnya akan dipakai untuk kegiatan kantor yang dananya kurang. Sikap Dimas yang paling mencerminkan integritas adalah ....", "options": [{"key": "A", "text": "Menolak menandatangani dengan sopan, menjelaskan bahwa hal itu merupakan pertanggungjawaban fiktif, dan melaporkannya melalui saluran pengaduan atau pengawasan internal bila praktik itu berlanjut"}, {"key": "B", "text": "Menandatangani karena dana tersebut digunakan untuk kepentingan kantor, bukan kepentingan pribadi"}, {"key": "C", "text": "Menandatangani, tetapi tidak mengambil bagian sedikit pun dari uang yang dicairkan"}, {"key": "D", "text": "Menolak menandatangani, lalu langsung mengunggah kejadian itu ke media sosial agar mendapat perhatian publik"}, {"key": "E", "text": "Meminta waktu untuk berpikir dan menunggu sampai senior tersebut melupakan permintaannya"}], "correct_answer": "A", "scores": null, "explanation": "Menandatangani daftar hadir kegiatan yang tidak diikuti berarti ikut membuat pertanggungjawaban fiktif yang merugikan keuangan negara, apa pun alasan penggunaan dananya. Integritas menuntut keberanian menolak secara santun dan menempuh jalur pelaporan resmi bila pelanggaran berlanjut. Opsi B dan C tetap menjadikan Dimas bagian dari pemalsuan, sedangkan opsi D tidak menggunakan saluran pelaporan yang semestinya.", "category": "Integritas", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B. Dalam konsep ATHG, hambatan adalah usaha yang berasal dari dalam diri sendiri yang bersifat melemahkan atau menghalangi secara tidak konsepsional.", "concept": "Soal menguji konsep ATHG (ancaman, tantangan, hambatan, gangguan) dalam ketahanan nasional. Ancaman bersifat mengubah atau merombak kebijaksanaan secara konsepsional; tantangan bersifat menggugah kemampuan; hambatan melemahkan secara tidak konsepsional dari dalam; gangguan melemahkan secara tidak konsepsional dari luar.", "steps": ["Cari dua kata kunci dalam soal: berasal dari dalam diri sendiri dan melemahkan secara tidak konsepsional.", "Sifat melemahkan atau menghalangi secara tidak konsepsional dimiliki oleh hambatan dan gangguan.", "Pembedanya adalah asalnya: hambatan dari dalam, gangguan dari luar, sehingga jawabannya hambatan."], "options": {"A": "Salah. Ancaman adalah usaha yang bersifat mengubah atau merombak kebijaksanaan dan dilakukan secara konsepsional.", "B": "Benar. Hambatan adalah usaha dari dalam diri sendiri yang bersifat melemahkan atau menghalangi secara tidak konsepsional.", "C": "Salah. Tantangan adalah usaha yang bersifat menggugah kemampuan, bukan melemahkan.", "D": "Salah. Gangguan memang melemahkan secara tidak konsepsional, tetapi berasal dari luar, bukan dari dalam diri sendiri.", "E": "Salah. Kerawanan bukan bagian dari empat unsur ATHG dalam konsep ketahanan nasional."}, "tips": "Hambatan dan gangguan sama-sama tidak konsepsional; ingat hambatan dari dalam, gangguan dari luar.", "reference": "Konsepsi Ketahanan Nasional, Lembaga Ketahanan Nasional Republik Indonesia (Lemhannas RI)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 19, "question_text": "Dalam konsep ketahanan nasional, usaha yang berasal dari dalam diri sendiri yang bersifat atau bertujuan melemahkan atau menghalangi secara tidak konsepsional disebut ....", "options": [{"key": "A", "text": "ancaman"}, {"key": "B", "text": "hambatan"}, {"key": "C", "text": "tantangan"}, {"key": "D", "text": "gangguan"}, {"key": "E", "text": "kerawanan"}], "correct_answer": "B", "scores": null, "explanation": "Dalam konsep ATHG, hambatan adalah usaha yang berasal dari dalam diri sendiri yang bersifat melemahkan atau menghalangi secara tidak konsepsional. Gangguan memiliki sifat yang sama tetapi berasal dari luar, sedangkan ancaman merupakan usaha yang bersifat mengubah atau merombak kebijaksanaan dan dilakukan secara konsepsional. Tantangan adalah usaha yang bersifat menggugah kemampuan.", "category": "Bela Negara", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D. Pasal 7C UUD NRI Tahun 1945 menegaskan bahwa Presiden tidak dapat membekukan dan/atau membubarkan DPR, yang memperkuat kedudukan sejajar antara eksekutif dan legislatif sebagai ciri sistem presidensial.", "concept": "Soal menguji ciri sistem pemerintahan presidensial dan penguatannya melalui amandemen UUD. Dalam sistem presidensial, presiden adalah kepala negara sekaligus kepala pemerintahan, dipilih langsung oleh rakyat, dan tidak bertanggung jawab kepada parlemen; sebaliknya, presiden juga tidak dapat membubarkan parlemen.", "steps": ["Pisahkan ciri sistem presidensial dari ciri sistem parlementer.", "Ciri parlementer antara lain menteri bertanggung jawab kepada parlemen, kepala pemerintahan berupa perdana menteri, dan kepala negara dapat membubarkan parlemen.", "Ketentuan hasil amandemen yang mempertegas presidensial dan tercantum dalam opsi adalah larangan Presiden membekukan atau membubarkan DPR dalam Pasal 7C."], "options": {"A": "Salah. Pemilihan Presiden oleh MPR adalah ketentuan sebelum amandemen; kini Presiden dipilih langsung oleh rakyat menurut Pasal 6A ayat (1).", "B": "Salah. Menteri yang bertanggung jawab kepada DPR adalah ciri sistem parlementer; dalam UUD, menteri diangkat dan diberhentikan oleh Presiden.", "C": "Salah. Kewenangan membubarkan parlemen adalah ciri sistem parlementer dan justru dilarang oleh Pasal 7C.", "D": "Benar. Pasal 7C menyatakan Presiden tidak dapat membekukan dan/atau membubarkan DPR, sehingga mempertegas sistem presidensial.", "E": "Salah. Pemerintahan yang dipimpin perdana menteri adalah ciri sistem parlementer; di Indonesia Presiden memegang kekuasaan pemerintahan."}, "tips": "Opsi yang menyebut perdana menteri, menteri bertanggung jawab kepada parlemen, atau pembubaran parlemen hampir selalu ciri sistem parlementer.", "reference": "UUD NRI Tahun 1945 Pasal 6A ayat (1) dan Pasal 7C", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 20, "question_text": "Salah satu ketentuan dalam UUD NRI Tahun 1945 hasil amandemen yang mempertegas sistem pemerintahan presidensial adalah ....", "options": [{"key": "A", "text": "Presiden dipilih oleh MPR dan bertanggung jawab kepada MPR"}, {"key": "B", "text": "Menteri-menteri negara bertanggung jawab kepada DPR"}, {"key": "C", "text": "Presiden dapat membubarkan DPR apabila terjadi kebuntuan politik"}, {"key": "D", "text": "Presiden tidak dapat membekukan dan/atau membubarkan DPR"}, {"key": "E", "text": "Pemerintahan sehari-hari dipimpin oleh perdana menteri dari partai pemenang pemilu"}], "correct_answer": "D", "scores": null, "explanation": "Pasal 7C UUD NRI Tahun 1945 menegaskan bahwa Presiden tidak dapat membekukan dan/atau membubarkan DPR, yang memperkuat kedudukan sejajar antara eksekutif dan legislatif dalam sistem presidensial. Opsi A merupakan ketentuan sebelum amandemen; kini Presiden dipilih langsung oleh rakyat menurut Pasal 6A ayat (1). Opsi B, C, dan E merupakan ciri sistem parlementer.", "category": "Pilar Negara", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B. Kongres Pemuda II menunjukkan bahwa organisasi pemuda berbasis daerah dapat bersatu sebagai satu bangsa tanpa harus menghapus identitas kedaerahannya, sejalan dengan semboyan Bhinneka Tunggal Ika.", "concept": "Soal menguji nilai persatuan dalam keberagaman dari peristiwa Sumpah Pemuda 1928. Persatuan Indonesia tidak berarti penyeragaman; identitas daerah, suku, dan bahasa daerah tetap dihargai dalam bingkai komitmen bersama sebagai satu bangsa.", "steps": ["Perhatikan latar peristiwa: peserta kongres berasal dari organisasi kedaerahan seperti Jong Java, Jong Sumatranen Bond, dan Jong Ambon.", "Mereka mengikrarkan satu tanah air dan satu bangsa, serta menjunjung bahasa persatuan, tanpa membubarkan identitas asalnya.", "Pelajaran yang relevan adalah menempatkan identitas kedaerahan dalam komitmen kebangsaan, sebagaimana dinyatakan opsi B."], "options": {"A": "Salah. Penyeragaman bertentangan dengan Bhinneka Tunggal Ika; Sumpah Pemuda justru menyatukan tanpa menghapus keberagaman.", "B": "Benar. Identitas kedaerahan tetap dihargai, tetapi ditempatkan dalam komitmen bersama sebagai satu bangsa Indonesia.", "C": "Salah. Organisasi kedaerahan pada Kongres Pemuda II justru menjadi bagian dari lahirnya ikrar persatuan, bukan penghambat.", "D": "Salah. Ikrar ketiga berbunyi menjunjung bahasa persatuan, bukan meninggalkan bahasa daerah dalam kehidupan sehari-hari.", "E": "Salah. Gagasan kepemimpinan oleh suku terbesar bertentangan dengan prinsip kesetaraan dan persatuan seluruh suku bangsa."}, "tips": "Dalam soal persatuan, waspadai opsi bernada penyeragaman, penghapusan identitas daerah, atau dominasi kelompok tertentu.", "reference": "Ikrar Sumpah Pemuda, Kongres Pemuda II, 28 Oktober 1928", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 21, "question_text": "Kongres Pemuda II tahun 1928 dihadiri oleh wakil berbagai organisasi pemuda, antara lain Jong Java, Jong Sumatranen Bond, Jong Ambon, Jong Celebes, dan Jong Batak, yang sebelumnya bergerak dengan basis kedaerahan masing-masing. Kongres tersebut menghasilkan ikrar tentang satu tanah air, satu bangsa, dan menjunjung bahasa persatuan. Pelajaran paling relevan dari peristiwa tersebut bagi upaya menjaga persatuan bangsa saat ini adalah ....", "options": [{"key": "A", "text": "Keberagaman daerah sebaiknya diseragamkan agar tidak menimbulkan perpecahan"}, {"key": "B", "text": "Identitas kedaerahan tidak harus dihilangkan, tetapi ditempatkan dalam komitmen bersama sebagai satu bangsa"}, {"key": "C", "text": "Organisasi kedaerahan merupakan penghambat persatuan sehingga perlu dibatasi"}, {"key": "D", "text": "Persatuan hanya dapat terwujud bila seluruh warga meninggalkan bahasa daerah dalam kehidupan sehari-hari"}, {"key": "E", "text": "Perjuangan bangsa sebaiknya dipimpin oleh suku yang jumlah penduduknya paling besar"}], "correct_answer": "B", "scores": null, "explanation": "Sumpah Pemuda menunjukkan bahwa para pemuda dari berbagai organisasi kedaerahan bersedia mengikatkan diri sebagai satu bangsa tanpa harus menghapus asal-usulnya, sejalan dengan semboyan Bhinneka Tunggal Ika. Opsi D keliru karena ikrar ketiga berbunyi menjunjung bahasa persatuan, bukan meninggalkan bahasa daerah. Opsi A dan C bertentangan dengan prinsip persatuan dalam keberagaman.", "category": "Nasionalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D. Kendaraan dinas adalah fasilitas negara untuk kepentingan kedinasan, sehingga Bu Ratna tidak boleh memakainya untuk mudik dan harus mencari kendaraan lain.", "concept": "Soal menguji integritas ASN dalam penggunaan barang milik negara. Fasilitas dinas hanya boleh dipakai untuk kepentingan kedinasan; penggunaannya untuk keperluan pribadi bertentangan dengan nilai akuntabel dalam BerAKHLAK dan aturan disiplin PNS.", "steps": ["Identifikasi tujuan penggunaan: mudik bersama keluarga adalah kepentingan pribadi, bukan kedinasan.", "Membayar bahan bakar sendiri tidak mengubah status penyalahgunaan aset, karena penyusutan, risiko kerusakan, dan kecelakaan tetap ditanggung negara.", "Sikap yang sesuai integritas adalah tidak memakai mobil dinas dan mencari alternatif kendaraan lain, sebagaimana opsi D."], "options": {"A": "Salah. Membayar bahan bakar sendiri tidak membuat penggunaan pribadi menjadi sah, karena aset negara tetap terpakai dan berisiko rusak.", "B": "Salah. Memberi tahu rekan sekantor bukan izin yang sah dan tidak mengubah sifat penggunaan pribadi atas fasilitas negara.", "C": "Salah. Mengganti pelat nomor justru menambah pelanggaran karena menyamarkan identitas kendaraan dinas.", "D": "Benar. Tidak memakai mobil dinas untuk kepentingan pribadi dan mencari kendaraan lain adalah wujud akuntabilitas dan integritas ASN.", "E": "Salah. Memakai mobil dinas meskipun hanya untuk perjalanan berangkat tetap merupakan penggunaan fasilitas negara untuk kepentingan pribadi."}, "tips": "Fasilitas dinas tetap tidak boleh dipakai untuk urusan pribadi meskipun biaya operasionalnya ditanggung sendiri atau hanya sebagian perjalanan.", "reference": "PP No. 94 Tahun 2021 tentang Disiplin Pegawai Negeri Sipil", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 22, "question_text": "Menjelang libur Lebaran, Bu Ratna, seorang kepala seksi, berencana mudik bersama keluarga menggunakan mobil dinas yang dipegangnya karena mobil pribadinya sedang diperbaiki. Ia berpikir tidak ada pihak yang dirugikan karena kantor sedang libur dan ia akan membayar sendiri bahan bakarnya. Tindakan yang paling tepat sesuai integritas ASN adalah ....", "options": [{"key": "A", "text": "Menggunakan mobil dinas karena bahan bakar dibayar sendiri sehingga tidak merugikan negara"}, {"key": "B", "text": "Menggunakan mobil dinas asalkan sudah memberi tahu rekan sekantor"}, {"key": "C", "text": "Menggunakan mobil dinas, tetapi menggantinya dengan pelat nomor pribadi agar tidak menarik perhatian"}, {"key": "D", "text": "Tidak menggunakan mobil dinas untuk kepentingan pribadi dan mencari alternatif kendaraan lain"}, {"key": "E", "text": "Menggunakan mobil dinas hanya untuk perjalanan berangkat, sedangkan perjalanan pulang memakai kendaraan umum"}], "correct_answer": "D", "scores": null, "explanation": "Fasilitas negara, termasuk kendaraan dinas, diperuntukkan bagi kepentingan kedinasan sehingga penggunaannya untuk keperluan pribadi bertentangan dengan nilai akuntabel dalam BerAKHLAK. Membayar bahan bakar sendiri tidak mengubah sifat penyalahgunaan aset negara, karena penyusutan dan risiko kerusakan tetap ditanggung negara, sehingga opsi A keliru. Opsi C bahkan menambah pelanggaran dengan menyamarkan identitas kendaraan.", "category": "Integritas", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E. Menjaga kebugaran fisik dan membekali diri dengan keterampilan kepemimpinan, pertolongan pertama, serta tanggap bencana adalah wujud kemampuan awal bela negara.", "concept": "Soal menguji lima nilai dasar bela negara menurut UU No. 23 Tahun 2019, yaitu cinta tanah air, sadar berbangsa dan bernegara, setia pada Pancasila sebagai ideologi negara, rela berkorban untuk bangsa dan negara, serta kemampuan awal bela negara. Kemampuan awal bela negara menekankan kesiapan psikis dan fisik warga negara.", "steps": ["Perhatikan inti perilaku mahasiswa: menyiapkan kemampuan fisik dan keterampilan agar siap membantu saat negara menghadapi keadaan darurat.", "Di antara lima nilai dasar bela negara, nilai yang menekankan kesiapan kemampuan fisik dan mental adalah kemampuan awal bela negara.", "Nilai lain lebih menekankan rasa cinta, kesadaran, kesetiaan ideologi, atau pengorbanan, sehingga jawabannya opsi E."], "options": {"A": "Kurang tepat. Cinta tanah air menekankan rasa bangga dan menjaga tanah air, sedangkan kasus ini menekankan persiapan kemampuan diri.", "B": "Kurang tepat. Sadar berbangsa dan bernegara menekankan kesadaran akan hak dan kewajiban sebagai warga negara, bukan latihan keterampilan.", "C": "Kurang tepat. Setia pada Pancasila menekankan keyakinan dan pengamalan ideologi negara, tidak sesuai dengan fokus kasus.", "D": "Kurang tepat. Rela berkorban menekankan kesediaan mengorbankan waktu, tenaga, atau harta, sedangkan kasus ini berfokus pada persiapan kemampuan.", "E": "Benar. Menjaga kebugaran dan menguasai keterampilan yang berguna saat darurat adalah wujud kemampuan awal bela negara."}, "tips": "Kata kunci seperti menjaga kebugaran, berlatih, dan menyiapkan keterampilan menunjuk pada kemampuan awal bela negara.", "reference": "UU No. 23 Tahun 2019 tentang Pengelolaan Sumber Daya Nasional untuk Pertahanan Negara", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 23, "question_text": "Seorang mahasiswa rutin menjaga kebugaran fisik, mengikuti latihan dasar kepemimpinan, serta mempelajari keterampilan pertolongan pertama dan tanggap bencana agar siap berkontribusi ketika negara menghadapi keadaan darurat. Perilaku tersebut paling mencerminkan nilai dasar bela negara menurut UU No. 23 Tahun 2019 berupa ....", "options": [{"key": "A", "text": "cinta tanah air"}, {"key": "B", "text": "sadar berbangsa dan bernegara"}, {"key": "C", "text": "setia pada Pancasila sebagai ideologi negara"}, {"key": "D", "text": "rela berkorban untuk bangsa dan negara"}, {"key": "E", "text": "kemampuan awal bela negara"}], "correct_answer": "E", "scores": null, "explanation": "UU No. 23 Tahun 2019 menetapkan lima nilai dasar bela negara, yaitu cinta tanah air, sadar berbangsa dan bernegara, setia pada Pancasila sebagai ideologi negara, rela berkorban untuk bangsa dan negara, serta kemampuan awal bela negara. Menjaga kesehatan jasmani dan membekali diri dengan keterampilan yang dapat digunakan saat negara membutuhkan merupakan wujud kemampuan awal bela negara. Opsi D kurang tepat karena kasus ini menekankan persiapan kemampuan, bukan pengorbanan kepentingan pribadi.", "category": "Bela Negara", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A. Menurut EYD Edisi V, kerja sama ditulis terpisah, antarlembaga ditulis serangkai karena antar adalah unsur terikat, dan mempertanggungjawabkan ditulis serangkai karena gabungan kata mendapat awalan dan akhiran sekaligus.", "concept": "Soal menguji kaidah penulisan gabungan kata dan unsur terikat dalam EYD Edisi V. Gabungan kata ditulis terpisah; jika hanya mendapat awalan atau akhiran tetap terpisah, tetapi jika mendapat awalan dan akhiran sekaligus ditulis serangkai. Unsur terikat seperti antar, pasca, dan pra ditulis serangkai dengan kata dasarnya.", "steps": ["Periksa kerja sama: gabungan kata tanpa imbuhan ditulis terpisah, sehingga kerjasama salah.", "Periksa antarlembaga: antar adalah unsur terikat sehingga ditulis serangkai tanpa spasi atau tanda hubung.", "Periksa mempertanggungjawabkan: gabungan kata tanggung jawab mendapat awalan memper- dan akhiran -kan sekaligus, sehingga ditulis serangkai.", "Hanya opsi A yang benar pada ketiga bagian tersebut."], "options": {"A": "Benar. Kerja sama, antarlembaga, dan mempertanggungjawabkan semuanya ditulis sesuai kaidah EYD Edisi V.", "B": "Salah. Kerjasama seharusnya ditulis terpisah dan antar lembaga seharusnya ditulis serangkai.", "C": "Salah. Antar-lembaga tidak memerlukan tanda hubung, dan mempertanggung jawabkan seharusnya ditulis serangkai.", "D": "Salah. Kerjasama seharusnya terpisah, dan mempertanggung-jawabkan tidak memakai tanda hubung tetapi ditulis serangkai.", "E": "Salah. Kerja sama dan antarlembaga sudah benar, tetapi mempertanggung jawabkan seharusnya ditulis serangkai."}, "tips": "Bandingkan bertanggung jawab (hanya awalan, tetap terpisah) dengan mempertanggungjawabkan (awalan dan akhiran, serangkai).", "reference": "Pedoman Ejaan Bahasa Indonesia yang Disempurnakan Edisi Kelima (EYD V), Badan Pengembangan dan Pembinaan Bahasa, 2022", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 24, "question_text": "Kalimat berikut yang penulisannya sesuai dengan kaidah EYD Edisi V adalah ....", "options": [{"key": "A", "text": "Kedua instansi itu sepakat menjalin kerja sama antarlembaga untuk mempertanggungjawabkan penggunaan anggaran."}, {"key": "B", "text": "Kedua instansi itu sepakat menjalin kerjasama antar lembaga untuk mempertanggungjawabkan penggunaan anggaran."}, {"key": "C", "text": "Kedua instansi itu sepakat menjalin kerja sama antar-lembaga untuk mempertanggung jawabkan penggunaan anggaran."}, {"key": "D", "text": "Kedua instansi itu sepakat menjalin kerjasama antarlembaga untuk mempertanggung-jawabkan penggunaan anggaran."}, {"key": "E", "text": "Kedua instansi itu sepakat menjalin kerja sama antarlembaga untuk mempertanggung jawabkan penggunaan anggaran."}], "correct_answer": "A", "scores": null, "explanation": "Gabungan kata kerja sama ditulis terpisah, unsur terikat antar ditulis serangkai dengan kata yang mengikutinya sehingga menjadi antarlembaga, dan gabungan kata yang mendapat awalan sekaligus akhiran ditulis serangkai sehingga menjadi mempertanggungjawabkan. Opsi E sudah benar pada dua bagian pertama, tetapi salah karena memisahkan mempertanggung jawabkan. Opsi B dan D salah karena merangkaikan kerjasama.", "category": "Bahasa Negara", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C. Pasal 37 ayat (5) UUD NRI Tahun 1945 menyatakan bahwa khusus mengenai bentuk Negara Kesatuan Republik Indonesia tidak dapat dilakukan perubahan, sehingga usulan negara federal tidak dapat diwujudkan.", "concept": "Soal menguji tata cara perubahan UUD dalam Pasal 37 beserta batasannya. Usul perubahan pasal diajukan sekurang-kurangnya sepertiga anggota MPR, sidang dihadiri sekurang-kurangnya dua pertiga anggota, dan putusan disetujui lima puluh persen ditambah satu anggota, tetapi bentuk NKRI dikecualikan dari perubahan.", "steps": ["Kenali isi usulan: mengubah bentuk negara kesatuan menjadi negara federal melalui perubahan UUD.", "Prosedur perubahan UUD diatur Pasal 37 ayat (1) sampai (4), tetapi ayat (5) secara khusus mengecualikan bentuk NKRI.", "Karena bentuk negara kesatuan tidak dapat diubah melalui mekanisme apa pun, tanggapan yang tepat adalah opsi C."], "options": {"A": "Salah. Syarat sepertiga anggota MPR adalah prosedur pengajuan usul perubahan pasal, tetapi tidak berlaku untuk bentuk NKRI.", "B": "Salah. UUD NRI Tahun 1945 tidak mengenal referendum sebagai mekanisme perubahan UUD, dan bentuk NKRI tetap tidak dapat diubah.", "C": "Benar. Pasal 37 ayat (5) menegaskan bentuk Negara Kesatuan Republik Indonesia tidak dapat dilakukan perubahan.", "D": "Salah. Undang-undang kedudukannya di bawah UUD sehingga tidak dapat mengubah ketentuan konstitusi tentang bentuk negara.", "E": "Salah. DPD tidak berwenang mengubah UUD; perubahan UUD adalah kewenangan MPR, dan bentuk NKRI tetap dikecualikan."}, "tips": "Ingat Pasal 37 ayat (5): bentuk NKRI adalah satu-satunya hal yang secara tegas tidak boleh diubah dalam UUD.", "reference": "UUD NRI Tahun 1945 Pasal 37 ayat (1) dan ayat (5)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 25, "question_text": "Dalam sebuah diskusi publik, seorang peserta mengusulkan agar bentuk negara Indonesia diubah menjadi negara federal melalui perubahan UUD NRI Tahun 1945 dengan alasan untuk mempercepat pemerataan pembangunan. Tanggapan yang paling tepat berdasarkan konstitusi terhadap usulan tersebut adalah ....", "options": [{"key": "A", "text": "Usulan dapat diproses apabila diajukan oleh sekurang-kurangnya sepertiga dari jumlah anggota MPR"}, {"key": "B", "text": "Usulan dapat diwujudkan melalui referendum yang diikuti seluruh rakyat"}, {"key": "C", "text": "Usulan tidak dapat diwujudkan karena UUD menegaskan bahwa khusus mengenai bentuk Negara Kesatuan Republik Indonesia tidak dapat dilakukan perubahan"}, {"key": "D", "text": "Usulan dapat diwujudkan melalui undang-undang yang disetujui bersama oleh DPR dan Presiden"}, {"key": "E", "text": "Usulan dapat diwujudkan apabila disetujui oleh DPD sebagai wakil daerah"}], "correct_answer": "C", "scores": null, "explanation": "Pasal 37 ayat (5) UUD NRI Tahun 1945 menyatakan bahwa khusus mengenai bentuk Negara Kesatuan Republik Indonesia tidak dapat dilakukan perubahan. Opsi A merujuk pada mekanisme pengajuan usul perubahan pasal dalam Pasal 37 ayat (1), tetapi mekanisme itu tidak berlaku untuk bentuk negara kesatuan. Undang-undang dan persetujuan DPD juga tidak dapat mengubah ketentuan konstitusi.", "category": "Pilar Negara", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D. Menjaga persatuan menuntut sikap aktif menangkal ujaran kebencian bermuatan SARA dengan mengingatkan secara santun, membagikan klarifikasi dari sumber tepercaya, dan melapor melalui kanal resmi bila perlu.", "concept": "Soal menguji sikap nasionalisme dalam menghadapi hoaks dan ujaran kebencian bermuatan SARA. Pesan yang menyudutkan suku tertentu dapat memecah belah bangsa, sehingga warga perlu memutus penyebarannya dan meluruskan informasi secara bijak.", "steps": ["Kenali bahayanya: pesan berantai yang menyudutkan satu suku dan belum terverifikasi berpotensi memicu konflik, apalagi menjelang pilkada.", "Sikap pasif membuat pesan terus beredar, sedangkan membalas dengan menyudutkan pihak lain memperburuk keadaan.", "Tindakan terbaik adalah mengingatkan, meluruskan dengan sumber tepercaya, dan melapor bila diperlukan, sebagaimana opsi D."], "options": {"A": "Salah. Keluar dari grup bersifat pasif dan membiarkan pesan pemecah belah terus beredar di antara anggota lain.", "B": "Salah. Membalas dengan menyudutkan suku lain justru menambah ujaran kebencian dan memperuncing konflik.", "C": "Salah. Kebebasan berpendapat tidak mencakup menyebarkan kebencian berbasis SARA; diam berarti membiarkan pelanggaran.", "D": "Benar. Mengingatkan, meluruskan dengan sumber tepercaya, dan melapor bila perlu adalah cara aktif dan santun menjaga persatuan.", "E": "Salah. Meneruskan pesan yang belum terverifikasi justru memperluas penyebaran hoaks dan kebencian."}, "tips": "Dalam soal hoaks atau SARA, pilih opsi yang aktif dan santun: menghentikan penyebaran, meluruskan informasi, dan melapor lewat kanal resmi.", "reference": "UU No. 40 Tahun 2008 tentang Penghapusan Diskriminasi Ras dan Etnis; UU Informasi dan Transaksi Elektronik Pasal 28 ayat (2)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 26, "question_text": "Menjelang pemilihan kepala daerah, sebuah grup percakapan warga dibanjiri pesan berantai yang menyudutkan satu suku tertentu dan menuduhnya sebagai penyebab masalah ekonomi di daerah itu. Beberapa anggota grup mulai ikut meneruskan pesan tersebut tanpa memeriksa kebenarannya. Sebagai anggota grup yang memahami nilai kebangsaan, tindakan yang paling tepat adalah ....", "options": [{"key": "A", "text": "Keluar dari grup agar tidak terlibat dalam perdebatan"}, {"key": "B", "text": "Membalas dengan pesan yang menyudutkan suku lain agar pembahasan seimbang"}, {"key": "C", "text": "Diam saja karena menyampaikan pendapat di grup adalah hak setiap anggota"}, {"key": "D", "text": "Mengingatkan anggota grup agar tidak menyebarkan pesan bermuatan SARA yang belum terverifikasi, membagikan klarifikasi dari sumber tepercaya, dan melaporkan konten tersebut bila perlu"}, {"key": "E", "text": "Meneruskan pesan itu kepada keluarga dan kerabat agar semua pihak waspada"}], "correct_answer": "D", "scores": null, "explanation": "Menjaga persatuan menuntut sikap aktif menangkal ujaran kebencian bermuatan SARA, misalnya dengan mengingatkan secara santun, meluruskan informasi dengan sumber tepercaya, dan melapor melalui kanal resmi bila diperlukan. Opsi A dan C bersifat pasif sehingga membiarkan pesan pemecah belah terus beredar. Opsi E justru memperluas penyebaran informasi yang belum terverifikasi.", "category": "Nasionalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C. Laporan kinerja harus disajikan sesuai data sebenarnya, disertai penjelasan kendala dan rencana perbaikan, karena laporan itu menjadi dasar pengambilan keputusan dan wujud akuntabilitas.", "concept": "Soal menguji integritas dan akuntabilitas dalam pelaporan kinerja instansi pemerintah. Data kinerja yang dimanipulasi, sekecil apa pun, menyesatkan pengambil keputusan; sikap profesional adalah melaporkan apa adanya sambil menunjukkan analisis dan langkah perbaikan.", "steps": ["Kenali tekanannya: ada usulan anggota tim dan isyarat atasan agar angka capaian dipercantik.", "Menyesuaikan angka berarti membuat laporan resmi yang tidak benar, apa pun besar selisihnya.", "Sebagai ketua tim, Arif bertanggung jawab memastikan laporan jujur sekaligus menunjukkan upaya perbaikan.", "Opsi C memenuhi tuntutan kejujuran dan profesionalisme tersebut."], "options": {"A": "Salah. Selisih kecil tetap merupakan manipulasi data yang menyesatkan penilaian kinerja dan pengambilan keputusan.", "B": "Salah. Menyerahkan sepenuhnya kepada atasan adalah sikap menghindari tanggung jawab sebagai ketua tim.", "C": "Benar. Melaporkan data sebenarnya disertai penjelasan kendala dan rencana perbaikan mencerminkan integritas dan akuntabilitas.", "D": "Salah. Menunda laporan sampai target tercapai melanggar kewajiban pelaporan tepat waktu dan menyembunyikan kondisi sebenarnya.", "E": "Salah. Kejujuran secara lisan tidak berarti jika dokumen resmi tetap memuat angka yang tidak benar."}, "tips": "Waspadai opsi yang tampak kompromistis, seperti jujur secara lisan tetapi tidak dalam dokumen resmi; yang dinilai adalah kebenaran laporan resmi.", "reference": "Peraturan Presiden No. 29 Tahun 2014 tentang Sistem Akuntabilitas Kinerja Instansi Pemerintah", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 27, "question_text": "Tim yang dipimpin Arif harus melaporkan capaian kinerja triwulan. Hasil pendataan menunjukkan target belum tercapai karena sejumlah kendala di lapangan. Seorang anggota tim mengusulkan agar angka capaian disesuaikan sedikit karena laporan akan dipakai untuk penilaian kinerja unit dan selisihnya dianggap kecil. Atasan Arif juga mengisyaratkan agar laporan terlihat baik. Sikap Arif yang paling tepat adalah ....", "options": [{"key": "A", "text": "Menyesuaikan angka sesuai usulan karena selisihnya kecil dan tidak merugikan siapa pun"}, {"key": "B", "text": "Menyerahkan keputusan sepenuhnya kepada atasan agar tanggung jawab tidak berada pada dirinya"}, {"key": "C", "text": "Melaporkan capaian sesuai data sebenarnya disertai penjelasan kendala dan rencana perbaikan untuk triwulan berikutnya"}, {"key": "D", "text": "Menunda penyampaian laporan sampai target benar-benar tercapai"}, {"key": "E", "text": "Menyampaikan angka sebenarnya kepada atasan secara lisan, tetapi mencantumkan angka yang telah disesuaikan dalam laporan resmi"}], "correct_answer": "C", "scores": null, "explanation": "Laporan kinerja harus jujur dan akuntabel karena menjadi dasar pengambilan keputusan; menyajikan data apa adanya disertai analisis kendala dan rencana perbaikan adalah wujud integritas sekaligus profesionalisme. Opsi B tampak aman, tetapi merupakan sikap menghindari tanggung jawab sebagai ketua tim. Opsi E tetap menghasilkan dokumen resmi yang tidak benar.", "category": "Integritas", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A. Pasal 30 ayat (2) UUD NRI Tahun 1945 menyatakan bahwa usaha pertahanan dan keamanan negara dilaksanakan melalui sistem pertahanan dan keamanan rakyat semesta oleh TNI dan Polri sebagai kekuatan utama, dan rakyat sebagai kekuatan pendukung.", "concept": "Soal menguji rumusan sistem pertahanan dan keamanan rakyat semesta (sishankamrata) dalam Pasal 30 ayat (2). Konstitusi menempatkan TNI dan Polri bersama-sama sebagai kekuatan utama, sedangkan rakyat sebagai kekuatan pendukung.", "steps": ["Perhatikan bahwa soal secara tegas menanyakan rumusan Pasal 30 ayat (2) UUD, bukan undang-undang pertahanan.", "Pasal 30 ayat (2) menyebut dua lembaga sebagai kekuatan utama, yaitu TNI dan Polri, serta rakyat sebagai kekuatan pendukung.", "Rumusan yang sesuai persis dengan konstitusi adalah opsi A."], "options": {"A": "Benar. Pasal 30 ayat (2) menempatkan TNI dan Polri sebagai kekuatan utama dan rakyat sebagai kekuatan pendukung.", "B": "Salah. Menempatkan TNI sendiri sebagai kekuatan utama mirip pengaturan komponen pertahanan dalam undang-undang menghadapi ancaman militer, bukan rumusan Pasal 30 ayat (2).", "C": "Salah. Rakyat dalam Pasal 30 ayat (2) adalah kekuatan pendukung, bukan kekuatan utama.", "D": "Salah. Konstitusi tidak menempatkan TNI, Polri, dan rakyat secara setara sebagai kekuatan utama.", "E": "Salah. UUD tidak menyebut Polri sebagai kekuatan cadangan; Polri bersama TNI adalah kekuatan utama."}, "tips": "Hafalkan rumusan konstitusinya: TNI dan Polri kekuatan utama, rakyat kekuatan pendukung; jangan tertukar dengan istilah komponen dalam undang-undang pertahanan.", "reference": "UUD NRI Tahun 1945 Pasal 30 ayat (2)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 28, "question_text": "Berdasarkan Pasal 30 ayat (2) UUD NRI Tahun 1945, usaha pertahanan dan keamanan negara dilaksanakan melalui sistem pertahanan dan keamanan rakyat semesta dengan ....", "options": [{"key": "A", "text": "TNI dan Polri sebagai kekuatan utama, rakyat sebagai kekuatan pendukung"}, {"key": "B", "text": "TNI sebagai kekuatan utama, Polri dan rakyat sebagai kekuatan pendukung"}, {"key": "C", "text": "rakyat sebagai kekuatan utama, TNI dan Polri sebagai kekuatan pendukung"}, {"key": "D", "text": "TNI, Polri, dan rakyat sebagai kekuatan utama yang setara"}, {"key": "E", "text": "TNI sebagai kekuatan utama, Polri sebagai kekuatan cadangan, dan rakyat sebagai kekuatan pendukung"}], "correct_answer": "A", "scores": null, "explanation": "Pasal 30 ayat (2) UUD NRI Tahun 1945 menyatakan bahwa usaha pertahanan dan keamanan negara dilaksanakan melalui sistem pertahanan dan keamanan rakyat semesta oleh TNI dan Polri sebagai kekuatan utama, dan rakyat sebagai kekuatan pendukung. Opsi B sering tertukar dengan pengaturan dalam UU Pertahanan Negara tentang komponen pertahanan menghadapi ancaman militer, padahal soal ini menanyakan rumusan konstitusi.", "category": "Bela Negara", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E. Terhadap RUU APBN, DPD hanya memberikan pertimbangan kepada DPR sebagaimana diatur Pasal 22D ayat (2), bukan mengajukan RUU berdasarkan Pasal 22D ayat (1).", "concept": "Soal menguji kewenangan DPD dalam Pasal 22D. Ayat (1) memberi DPD hak mengajukan RUU tentang otonomi daerah, hubungan pusat dan daerah, pembentukan, pemekaran, dan penggabungan daerah, pengelolaan sumber daya alam dan sumber daya ekonomi lainnya, serta perimbangan keuangan pusat dan daerah. Ayat (2) mengatur keikutsertaan membahas RUU tersebut dan pemberian pertimbangan atas RUU APBN, pajak, pendidikan, dan agama.", "steps": ["Perhatikan kata KECUALI: cari bidang yang tidak termasuk RUU yang dapat diajukan DPD menurut Pasal 22D ayat (1).", "Cocokkan opsi A sampai D dengan daftar Pasal 22D ayat (1); semuanya tercantum.", "RUU APBN tidak diajukan DPD; DPD hanya memberi pertimbangan atasnya menurut Pasal 22D ayat (2), sehingga jawabannya E."], "options": {"A": "Salah sebagai jawaban. RUU yang berkaitan dengan otonomi daerah termasuk RUU yang dapat diajukan DPD menurut Pasal 22D ayat (1).", "B": "Salah sebagai jawaban. Hubungan pusat dan daerah tercantum dalam Pasal 22D ayat (1).", "C": "Salah sebagai jawaban. Pembentukan dan pemekaran serta penggabungan daerah tercantum dalam Pasal 22D ayat (1).", "D": "Salah sebagai jawaban. Perimbangan keuangan pusat dan daerah tercantum dalam Pasal 22D ayat (1), meskipun sering dikira terkait APBN.", "E": "Benar sebagai jawaban. Atas RUU APBN, DPD hanya memberikan pertimbangan kepada DPR menurut Pasal 22D ayat (2), bukan mengajukan RUU."}, "tips": "Bedakan peran DPD: mengajukan RUU bidang kedaerahan (ayat 1), sedangkan untuk RUU APBN, pajak, pendidikan, dan agama hanya memberi pertimbangan (ayat 2).", "reference": "UUD NRI Tahun 1945 Pasal 22D ayat (1) dan ayat (2)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 29, "question_text": "Berdasarkan Pasal 22D ayat (1) UUD NRI Tahun 1945, Dewan Perwakilan Daerah dapat mengajukan kepada DPR rancangan undang-undang yang berkaitan dengan hal-hal berikut, KECUALI ....", "options": [{"key": "A", "text": "otonomi daerah"}, {"key": "B", "text": "hubungan pusat dan daerah"}, {"key": "C", "text": "pembentukan dan pemekaran serta penggabungan daerah"}, {"key": "D", "text": "perimbangan keuangan pusat dan daerah"}, {"key": "E", "text": "anggaran pendapatan dan belanja negara"}], "correct_answer": "E", "scores": null, "explanation": "Pasal 22D ayat (1) memberi DPD kewenangan mengajukan RUU yang berkaitan dengan otonomi daerah, hubungan pusat dan daerah, pembentukan dan pemekaran serta penggabungan daerah, pengelolaan sumber daya alam dan sumber daya ekonomi lainnya, serta perimbangan keuangan pusat dan daerah. Terhadap RUU APBN, DPD hanya memberikan pertimbangan kepada DPR sebagaimana diatur dalam Pasal 22D ayat (2), bukan mengajukan RUU. Opsi D sering dikira terkait APBN, padahal perimbangan keuangan pusat dan daerah memang termasuk dalam ayat (1).", "category": "Pilar Negara", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B. Peserta dari berbagai provinsi dengan bahasa daerah berbeda dapat bekerja sama berkat bahasa Indonesia, yang menunjukkan fungsi bahasa Indonesia sebagai sarana pemersatu berbagai suku bangsa.", "concept": "Soal menguji fungsi bahasa Indonesia menurut UU No. 24 Tahun 2009. Sebagai bahasa nasional (Pasal 25 ayat (2)), bahasa Indonesia berfungsi sebagai jati diri bangsa, kebanggaan nasional, sarana pemersatu berbagai suku bangsa, dan sarana komunikasi antardaerah dan antarbudaya daerah; sebagai bahasa resmi negara (Pasal 25 ayat (3)), fungsinya meliputi bahasa resmi kenegaraan, pengantar pendidikan, transaksi niaga, dan pengembangan iptek.", "steps": ["Perhatikan konteksnya: kegiatan perkemahan nonformal yang mempertemukan peserta dari berbagai suku dengan bahasa daerah berbeda.", "Bahasa Indonesia membuat mereka dapat berdiskusi dan bekerja sama, sehingga perannya adalah menyatukan.", "Fungsi yang paling sesuai adalah sarana pemersatu berbagai suku bangsa sebagai bagian dari fungsi bahasa nasional."], "options": {"A": "Salah. Fungsi bahasa resmi kenegaraan berkaitan dengan urusan dan dokumen kenegaraan, bukan interaksi peserta perkemahan.", "B": "Benar. Bahasa Indonesia menyatukan peserta dari berbagai suku sehingga dapat bekerja sama, sesuai fungsi sarana pemersatu berbagai suku bangsa.", "C": "Salah. Fungsi bahasa pengantar pendidikan berlaku dalam proses belajar mengajar di lembaga pendidikan, bukan dalam konteks perkemahan ini.", "D": "Salah. Fungsi pengembangan ilmu pengetahuan dan teknologi berkaitan dengan kegiatan keilmuan, bukan komunikasi antarpeserta dari berbagai daerah.", "E": "Salah. Fungsi transaksi dan dokumentasi niaga berkaitan dengan kegiatan perdagangan, bukan kegiatan perkemahan."}, "tips": "Jika konteks soal menonjolkan pertemuan berbagai suku atau daerah yang dapat bersatu berkat bahasa Indonesia, pilih fungsi sebagai sarana pemersatu.", "reference": "UU No. 24 Tahun 2009 Pasal 25 ayat (2) dan ayat (3)", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "twk", "question_number": 30, "question_text": "Dalam sebuah perkemahan tingkat nasional, peserta dari berbagai provinsi dengan bahasa daerah yang berbeda-beda dapat berdiskusi, bekerja sama, dan menyusun kegiatan bersama karena semuanya menggunakan bahasa Indonesia. Situasi tersebut paling tepat menggambarkan fungsi bahasa Indonesia sebagai ....", "options": [{"key": "A", "text": "bahasa resmi kenegaraan"}, {"key": "B", "text": "sarana pemersatu berbagai suku bangsa"}, {"key": "C", "text": "bahasa pengantar pendidikan"}, {"key": "D", "text": "sarana pengembangan ilmu pengetahuan dan teknologi"}, {"key": "E", "text": "bahasa transaksi dan dokumentasi niaga"}], "correct_answer": "B", "scores": null, "explanation": "Pasal 25 ayat (2) UU No. 24 Tahun 2009 menyebutkan bahwa bahasa Indonesia berfungsi sebagai jati diri bangsa, kebanggaan nasional, sarana pemersatu berbagai suku bangsa, serta sarana komunikasi antardaerah dan antarbudaya daerah. Peserta dari berbagai suku dapat bersatu dalam kegiatan bersama berkat bahasa Indonesia. Opsi A, C, D, dan E merupakan fungsi bahasa Indonesia sebagai bahasa resmi negara menurut Pasal 25 ayat (3), yang tidak sesuai dengan konteks perkemahan tersebut.", "category": "Bahasa Negara", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C (Kelembapan). Termometer adalah alat untuk mengukur suhu, sedangkan higrometer adalah alat untuk mengukur kelembapan udara, sehingga relasi kedua pasangan sama.", "concept": "Soal ini menguji analogi relasi alat ukur dan besaran yang diukurnya. Kunci keberhasilannya adalah mengenali fungsi masing-masing alat ukur cuaca.", "steps": ["Rumuskan relasi pasangan pertama dalam satu kalimat: termometer adalah alat untuk mengukur suhu.", "Terapkan kalimat yang sama pada pasangan kedua: higrometer adalah alat untuk mengukur ... .", "Higrometer (dari kata Yunani hygros, basah) digunakan untuk mengukur kelembapan udara, sehingga jawabannya Kelembapan."], "options": {"A": "Salah. Angin (kecepatannya) diukur dengan anemometer, bukan higrometer.", "B": "Salah. Tekanan udara diukur dengan barometer.", "C": "Benar. Higrometer adalah alat ukur kelembapan udara, sejajar dengan termometer yang mengukur suhu.", "D": "Salah. Curah hujan diukur dengan ombrometer (penakar hujan).", "E": "Salah. Ketinggian diukur dengan altimeter."}, "tips": "Hafalkan pasangan alat ukur cuaca: termometer–suhu, higrometer–kelembapan, barometer–tekanan udara, anemometer–kecepatan angin, ombrometer–curah hujan.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 31, "question_text": "TERMOMETER : SUHU = HIGROMETER : ...", "options": [{"key": "A", "text": "Angin"}, {"key": "B", "text": "Tekanan udara"}, {"key": "C", "text": "Kelembapan"}, {"key": "D", "text": "Curah hujan"}, {"key": "E", "text": "Ketinggian"}], "correct_answer": "C", "scores": null, "explanation": "Relasinya adalah alat ukur : besaran yang diukur. Termometer mengukur suhu, sedangkan higrometer mengukur kelembapan udara. Pengecoh lain merupakan besaran yang diukur alat berbeda: angin (anemometer), tekanan udara (barometer), curah hujan (ombrometer), dan ketinggian (altimeter).", "category": "Verbal - Analogi", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E (Senar : Gitar). Lensa adalah komponen fungsional yang terpasang pada kamera, dan senar juga merupakan komponen fungsional yang terpasang pada gitar.", "concept": "Soal ini menguji analogi relasi bagian dan keseluruhan (komponen : benda utuh). Pasangan jawaban harus menunjukkan benda pertama sebagai bagian yang terpasang dan berfungsi di dalam benda kedua.", "steps": ["Rumuskan relasi: lensa adalah bagian (komponen) dari kamera yang membuat kamera dapat berfungsi.", "Uji setiap pilihan dengan kalimat 'X adalah komponen dari Y'.", "Hanya 'senar adalah komponen dari gitar' yang tepat; pilihan lain berupa relasi tempat, keanggotaan koleksi, pemimpin, atau bahan bakar."], "options": {"A": "Salah. Roda adalah komponen kendaraan, bukan bagian dari jalan; relasinya hanya 'roda melintas di jalan'.", "B": "Salah. Buku adalah anggota koleksi yang disimpan di perpustakaan, bukan komponen fungsional sebuah benda.", "C": "Salah. Kapten adalah orang yang memimpin kapal, bukan bagian fisik kapal.", "D": "Salah. Bensin adalah bahan bakar yang dikonsumsi mobil, bukan komponen yang terpasang permanen.", "E": "Benar. Senar adalah komponen yang terpasang pada gitar, sama seperti lensa pada kamera."}, "tips": "Waspadai pengecoh 'bahan bakar' dan 'tempat': komponen adalah bagian yang terpasang tetap, bukan sesuatu yang dihabiskan atau sekadar berada di lokasi yang sama.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 32, "question_text": "LENSA : KAMERA = ... : ...", "options": [{"key": "A", "text": "Roda : Jalan"}, {"key": "B", "text": "Buku : Perpustakaan"}, {"key": "C", "text": "Kapten : Kapal"}, {"key": "D", "text": "Bensin : Mobil"}, {"key": "E", "text": "Senar : Gitar"}], "correct_answer": "E", "scores": null, "explanation": "Lensa adalah komponen (bagian fungsional) yang terpasang pada kamera. Hubungan yang sama terdapat pada senar sebagai komponen gitar. Roda tidak merupakan bagian dari jalan, buku adalah anggota koleksi perpustakaan, kapten adalah orang yang memimpin kapal, dan bensin adalah bahan bakar mobil, bukan komponennya.", "category": "Verbal - Analogi", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A (Dingin). Hangat adalah tingkat yang lebih rendah dari panas, sedangkan sejuk adalah tingkat yang lebih rendah dari dingin.", "concept": "Soal ini menguji analogi tingkatan (gradasi) makna dalam satu skala yang sama, yaitu sensasi suhu dari yang ringan ke yang kuat.", "steps": ["Rumuskan relasi: hangat berarti agak panas, jadi hangat adalah tingkat ringan dari panas.", "Cari kata yang tingkat ringannya adalah sejuk: sejuk berarti agak dingin.", "Maka SEJUK : DINGIN sejajar dengan HANGAT : PANAS, yaitu pilihan A."], "options": {"A": "Benar. Sejuk adalah tingkat ringan dari dingin, sejajar dengan hangat sebagai tingkat ringan dari panas.", "B": "Salah. Segar menggambarkan kondisi atau rasa nyaman, bukan tingkatan suhu.", "C": "Salah. Lembap berkaitan dengan kadar air, bukan tingkatan suhu.", "D": "Salah. Teduh berarti terlindung dari panas matahari, bukan tingkat suhu yang lebih kuat dari sejuk.", "E": "Salah. Basah berkaitan dengan air, bukan tingkatan suhu."}, "tips": "Untuk analogi tingkatan, pastikan kata jawaban berada pada skala yang sama dengan kata soal (di sini skala suhu) dan arah tingkatnya sama (ringan ke kuat).", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 33, "question_text": "HANGAT : PANAS = SEJUK : ...", "options": [{"key": "A", "text": "Dingin"}, {"key": "B", "text": "Segar"}, {"key": "C", "text": "Lembap"}, {"key": "D", "text": "Teduh"}, {"key": "E", "text": "Basah"}], "correct_answer": "A", "scores": null, "explanation": "Hangat berarti agak panas, sehingga relasinya adalah tingkat rendah : tingkat tinggi dari sensasi suhu yang sama. Sejuk berarti agak dingin, maka pasangannya adalah dingin. Segar, lembap, teduh, dan basah bukan tingkatan suhu.", "category": "Verbal - Analogi", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D (Cangkul : Penulis). Pena adalah alat kerja yang digunakan penulis, sehingga kata pertama harus alat kerja petani, yaitu cangkul: CANGKUL : PETANI = PENA : PENULIS.", "concept": "Soal ini menguji analogi relasi alat kerja dan pelaku (profesi) yang menggunakannya. Karena dua kata dihilangkan, kedua pasangan harus diuji sekaligus dengan pola yang sama.", "steps": ["Isi rumpang membentuk pola X : PETANI = PENA : Y. Pena adalah alat, sehingga relasinya kemungkinan alat : pengguna.", "Uji tiap pilihan dengan kalimat 'X digunakan oleh petani' dan 'pena digunakan oleh Y'.", "Pilihan D: cangkul digunakan oleh petani, dan pena digunakan oleh penulis. Kedua kalimat benar dengan relasi yang sama.", "Pilihan lain gagal di salah satu sisi, misalnya sawah adalah tempat kerja atau kertas bukan pelaku."], "options": {"A": "Salah. Sawah adalah tempat kerja petani dan sekolah bukan pengguna pena, sehingga relasinya tidak sejajar.", "B": "Salah. Padi adalah hasil kerja petani, sedangkan buku bukan pengguna pena.", "C": "Salah. Ladang adalah tempat kerja, bukan alat; relasi ladang–petani tidak sama dengan pena–wartawan (alat–pengguna).", "D": "Benar. Cangkul adalah alat kerja petani dan pena adalah alat kerja penulis; relasinya identik.", "E": "Salah. Traktor memang alat petani, tetapi kertas bukan pelaku yang menggunakan pena; kertas adalah media tulis."}, "tips": "Pada analogi dua rumpang, jangan berhenti di kata pertama yang cocok; selalu uji kedua sisi dengan kalimat relasi yang sama.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 34, "question_text": "... : PETANI = PENA : ...", "options": [{"key": "A", "text": "Sawah : Sekolah"}, {"key": "B", "text": "Padi : Buku"}, {"key": "C", "text": "Ladang : Wartawan"}, {"key": "D", "text": "Cangkul : Penulis"}, {"key": "E", "text": "Traktor : Kertas"}], "correct_answer": "D", "scores": null, "explanation": "Pena adalah alat kerja yang digunakan oleh penulis; maka kata pertama harus berupa alat kerja petani, yaitu cangkul (CANGKUL : PETANI = PENA : PENULIS). Sawah dan ladang adalah tempat kerja, padi adalah hasil kerja, sedangkan pada pilihan traktor : kertas, kata kedua bukan pelaku (orang). Trik: uji kedua pasangan sekaligus dengan kalimat 'X digunakan oleh Y'.", "category": "Verbal - Analogi", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B (Fana : Baka). Boros dan hemat adalah pasangan antonim, dan fana (tidak kekal) juga berlawanan makna dengan baka (kekal).", "concept": "Soal ini menguji analogi relasi antonim (lawan kata). Pengecoh disusun dari pasangan sinonim sehingga perlu memastikan arah relasinya berlawanan, bukan sepadan.", "steps": ["Tentukan relasi pasangan soal: boros berlawanan makna dengan hemat (antonim).", "Periksa setiap pilihan: rajin–tekun, cerdas–pandai, kikir–pelit, dan lapuk–usang adalah sinonim.", "Fana berarti tidak kekal, baka berarti kekal; keduanya berlawanan, jadi jawabannya B."], "options": {"A": "Salah. Rajin dan tekun bermakna mirip (sinonim), bukan berlawanan.", "B": "Benar. Fana (tidak kekal) dan baka (kekal) adalah antonim, sejajar dengan boros dan hemat.", "C": "Salah. Cerdas dan pandai adalah sinonim.", "D": "Salah. Kikir dan pelit adalah sinonim; keduanya justru antonim dari boros.", "E": "Salah. Lapuk dan usang sama-sama menggambarkan sesuatu yang sudah tua atau rusak (sinonim)."}, "tips": "Jika empat pilihan sejenis (semuanya sinonim), pilihan yang berbeda sendiri biasanya adalah jawabannya; pastikan juga Anda tahu arti kata serapan seperti fana dan baka.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 35, "question_text": "BOROS : HEMAT = ... : ...", "options": [{"key": "A", "text": "Rajin : Tekun"}, {"key": "B", "text": "Fana : Baka"}, {"key": "C", "text": "Cerdas : Pandai"}, {"key": "D", "text": "Kikir : Pelit"}, {"key": "E", "text": "Lapuk : Usang"}], "correct_answer": "B", "scores": null, "explanation": "Boros dan hemat berlawanan makna (antonim). Fana (tidak kekal) berlawanan dengan baka (kekal). Pasangan lain adalah sinonim: rajin–tekun, cerdas–pandai, kikir–pelit, lapuk–usang.", "category": "Verbal - Analogi", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D. Semua peserta pelatihan wajib apel pagi dan sebagian pegawai baru adalah peserta pelatihan, sehingga sebagian pegawai baru (yaitu yang menjadi peserta) wajib mengikuti apel pagi.", "concept": "Soal ini menguji silogisme kategoris pola 'Semua A adalah B; Sebagian C adalah A; maka Sebagian C adalah B'. Kesimpulan mengikuti kuantor yang lebih lemah, yaitu 'sebagian'.", "steps": ["Tetapkan istilah: A = peserta pelatihan, B = wajib mengikuti apel pagi, C = pegawai baru.", "Premis 1: Semua A adalah B. Premis 2: Sebagian C adalah A.", "Sebagian C yang termasuk A otomatis termasuk B, sehingga Sebagian C adalah B.", "Terjemahkan kembali: sebagian pegawai baru wajib mengikuti apel pagi (pilihan D)."], "options": {"A": "Salah. Premis kedua hanya menyebut sebagian pegawai baru, sehingga kesimpulan 'semua' terlalu luas.", "B": "Salah. Premis tidak memberi informasi tentang peserta pelatihan yang bukan pegawai baru; pernyataan ini tidak dapat dipastikan.", "C": "Salah. Ini membalik premis pertama (konversi 'semua' yang tidak sah); bisa saja ada orang lain yang wajib apel tetapi bukan peserta pelatihan.", "D": "Benar. Sesuai pola Semua A adalah B dan Sebagian C adalah A, maka Sebagian C adalah B.", "E": "Salah. Bertentangan langsung dengan kedua premis, karena pegawai baru yang menjadi peserta pelatihan pasti wajib apel."}, "tips": "Jika salah satu premis memakai 'sebagian', kesimpulan yang sah juga memakai 'sebagian', bukan 'semua'.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 36, "question_text": "Semua peserta pelatihan wajib mengikuti apel pagi.\nSebagian pegawai baru adalah peserta pelatihan.\n\nKesimpulan yang tepat adalah ...", "options": [{"key": "A", "text": "Semua pegawai baru wajib mengikuti apel pagi."}, {"key": "B", "text": "Sebagian peserta pelatihan bukan pegawai baru."}, {"key": "C", "text": "Semua yang wajib mengikuti apel pagi adalah peserta pelatihan."}, {"key": "D", "text": "Sebagian pegawai baru wajib mengikuti apel pagi."}, {"key": "E", "text": "Tidak ada pegawai baru yang wajib mengikuti apel pagi."}], "correct_answer": "D", "scores": null, "explanation": "Pola: Semua A adalah B; Sebagian C adalah A; maka Sebagian C adalah B. A = peserta pelatihan, B = wajib apel pagi, C = pegawai baru. Jadi, sebagian pegawai baru wajib mengikuti apel pagi. Pilihan 'semua' terlalu luas karena premis kedua hanya 'sebagian', sedangkan pilihan C membalik premis pertama (konversi yang tidak sah).", "category": "Verbal - Silogisme", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A. Ingkaran 'semua' adalah 'ada', dan ingkaran 'p dan q' adalah 'bukan p atau bukan q', sehingga ingkarannya: ada pelamar yang tidak melengkapi berkas atau tidak lulus seleksi administrasi.", "concept": "Soal ini menguji ingkaran pernyataan berkuantor sekaligus ingkaran konjungsi. Kuantor universal diingkar menjadi eksistensial, dan konjungsi diingkar dengan hukum De Morgan menjadi disjungsi dari ingkaran masing-masing.", "steps": ["Tulis bentuk logikanya: Semua x (p ∧ q), dengan p = melengkapi berkas dan q = lulus seleksi administrasi.", "Ingkaran kuantor: ~(Semua x ...) ≡ Ada x yang ~(...).", "Ingkaran konjungsi (De Morgan): ~(p ∧ q) ≡ ~p ∨ ~q.", "Gabungkan: Ada x (~p ∨ ~q), yaitu 'Ada pelamar yang tidak melengkapi berkas atau tidak lulus seleksi administrasi' (pilihan A)."], "options": {"A": "Benar. Kuantor 'semua' berubah menjadi 'ada' dan 'dan' berubah menjadi 'atau' dengan kedua komponen dinegasikan.", "B": "Salah. Kata hubung 'dan' tetap dipertahankan; menurut De Morgan seharusnya berubah menjadi 'atau'.", "C": "Salah. Kuantor 'semua' tidak diingkar menjadi 'ada'.", "D": "Salah. 'Tidak ada' setara dengan 'semua ... tidak', yang terlalu kuat; ingkaran cukup menyatakan ada minimal satu pengecualian.", "E": "Salah. Kuantor tetap 'semua' dan kata hubung tetap 'dan'; keduanya keliru."}, "tips": "Ingat dua perubahan sekaligus: 'semua' menjadi 'ada', dan 'dan' menjadi 'atau'; pilihan yang hanya mengubah salah satunya adalah jebakan.", "reference": "Hukum De Morgan: ~(p ∧ q) ≡ ~p ∨ ~q dan ~(p ∨ q) ≡ ~p ∧ ~q. Ingkaran kuantor: ~(∀x P(x)) ≡ ∃x ~P(x).", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 37, "question_text": "Ingkaran dari pernyataan \"Semua pelamar melengkapi berkas dan lulus seleksi administrasi\" adalah ...", "options": [{"key": "A", "text": "Ada pelamar yang tidak melengkapi berkas atau tidak lulus seleksi administrasi."}, {"key": "B", "text": "Ada pelamar yang tidak melengkapi berkas dan tidak lulus seleksi administrasi."}, {"key": "C", "text": "Semua pelamar tidak melengkapi berkas atau tidak lulus seleksi administrasi."}, {"key": "D", "text": "Tidak ada pelamar yang melengkapi berkas dan lulus seleksi administrasi."}, {"key": "E", "text": "Semua pelamar tidak melengkapi berkas dan tidak lulus seleksi administrasi."}], "correct_answer": "A", "scores": null, "explanation": "Ingkaran 'semua' adalah 'ada/beberapa', dan ingkaran konjungsi (p dan q) adalah (bukan p atau bukan q) menurut hukum De Morgan. Jadi ~[Semua x (p ∧ q)] ≡ Ada x (~p ∨ ~q): 'Ada pelamar yang tidak melengkapi berkas atau tidak lulus seleksi administrasi.' Kesalahan umum adalah tetap memakai 'dan' (pilihan B) atau tetap memakai 'semua'.", "category": "Verbal - Silogisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E (Hari ini hujan tidak turun deras). Premis 1 dan 2 menghasilkan 'jika hujan deras, bus terlambat', lalu karena bus tidak terlambat, dengan modus tollens disimpulkan hujan tidak turun deras.", "concept": "Soal ini menguji gabungan silogisme hipotetis (p → q, q → r, maka p → r) dan modus tollens (p → r, ~r, maka ~p).", "steps": ["Lambangkan: p = hujan turun deras, q = jalan protokol tergenang, r = bus kota terlambat.", "Silogisme hipotetis: p → q dan q → r, sehingga p → r.", "Premis 3: ~r (bus tidak terlambat). Dari q → r dan ~r diperoleh ~q (jalan tidak tergenang).", "Modus tollens pada p → r dengan ~r menghasilkan ~p: hari ini hujan tidak turun deras (pilihan E)."], "options": {"A": "Salah. Justru bertentangan dengan hasil modus tollens (~p).", "B": "Salah. Dari q → r dan ~r diperoleh ~q, jadi jalan protokol tidak tergenang.", "C": "Salah. Ini konvers r → p dari p → r, yang tidak setara dengan pernyataan asal.", "D": "Salah. Bagian 'jalan protokol tergenang' bertentangan dengan ~q yang dapat disimpulkan.", "E": "Benar. Dari p → r dan ~r, modus tollens menghasilkan ~p."}, "tips": "Jika premis terakhir menyangkal ujung rantai implikasi, mundurlah ke awal rantai: semua anteseden ikut tersangkal.", "reference": "Modus tollens: p → q, ~q, maka ~p. Silogisme hipotetis: p → q, q → r, maka p → r.", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 38, "question_text": "Jika hujan turun deras, jalan protokol tergenang.\nJika jalan protokol tergenang, bus kota terlambat.\nHari ini bus kota tidak terlambat.\n\nKesimpulan yang tepat adalah ...", "options": [{"key": "A", "text": "Hari ini hujan turun deras."}, {"key": "B", "text": "Hari ini jalan protokol tergenang."}, {"key": "C", "text": "Jika bus kota terlambat, hujan turun deras."}, {"key": "D", "text": "Hari ini jalan protokol tergenang, tetapi hujan tidak deras."}, {"key": "E", "text": "Hari ini hujan tidak turun deras."}], "correct_answer": "E", "scores": null, "explanation": "Premis 1 dan 2 membentuk silogisme hipotetis: p → q, q → r, sehingga p → r (jika hujan deras, bus terlambat). Premis 3 menyatakan ~r. Dengan modus tollens: p → r, ~r, maka ~p, yaitu hari ini hujan tidak turun deras. Pilihan C adalah konvers (r → p) yang tidak sah.", "category": "Verbal - Silogisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B. Tidak ada pegawai berintegritas yang menerima gratifikasi, dan sebagian pegawai pengadaan berintegritas, sehingga sebagian pegawai pengadaan (yang berintegritas itu) tidak menerima gratifikasi.", "concept": "Soal ini menguji silogisme kategoris pola 'Tidak ada A yang B; Sebagian C adalah A; maka Sebagian C bukan B'. Kesimpulan hanya berlaku untuk bagian C yang beririsan dengan A.", "steps": ["Tetapkan istilah: A = pegawai berintegritas, B = menerima gratifikasi, C = pegawai bagian pengadaan.", "Premis 1: Tidak ada A yang B. Premis 2: Sebagian C adalah A.", "Bagian C yang termasuk A pasti tidak termasuk B, sehingga Sebagian C bukan B.", "Untuk pegawai pengadaan yang tidak berintegritas, premis tidak memberi informasi, jadi kesimpulan tidak boleh diperluas. Jawaban: B."], "options": {"A": "Salah. Premis hanya menjamin sebagian pegawai pengadaan; pegawai pengadaan yang tidak berintegritas tidak diketahui.", "B": "Benar. Sesuai pola Tidak ada A yang B dan Sebagian C adalah A, maka Sebagian C bukan B.", "C": "Salah. Tidak ada premis yang menyatakan ada pegawai pengadaan yang menerima gratifikasi; ini tidak dapat dipastikan.", "D": "Salah. Sama dengan pilihan A (berlaku untuk semua), terlalu luas karena premis kedua hanya 'sebagian'.", "E": "Salah. Ini membalik premis pertama secara tidak sah; tidak menerima gratifikasi tidak menjamin seseorang berintegritas."}, "tips": "Jangan mencampurkan pengetahuan umum atau penilaian moral; simpulkan hanya dari premis, dan pertahankan kuantor 'sebagian'.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 39, "question_text": "Tidak ada pegawai berintegritas yang menerima gratifikasi.\nSebagian pegawai bagian pengadaan adalah pegawai berintegritas.\n\nKesimpulan yang tepat adalah ...", "options": [{"key": "A", "text": "Semua pegawai bagian pengadaan tidak menerima gratifikasi."}, {"key": "B", "text": "Sebagian pegawai bagian pengadaan tidak menerima gratifikasi."}, {"key": "C", "text": "Sebagian pegawai bagian pengadaan menerima gratifikasi."}, {"key": "D", "text": "Tidak ada pegawai bagian pengadaan yang menerima gratifikasi."}, {"key": "E", "text": "Semua pegawai yang tidak menerima gratifikasi adalah pegawai berintegritas."}], "correct_answer": "B", "scores": null, "explanation": "Pola: Tidak ada A yang B; Sebagian C adalah A; maka Sebagian C bukan B. A = pegawai berintegritas, B = menerima gratifikasi, C = pegawai bagian pengadaan. Kesimpulan: sebagian pegawai bagian pengadaan tidak menerima gratifikasi. Tentang pegawai pengadaan yang tidak berintegritas tidak ada informasi, sehingga pilihan A, C, dan D tidak dapat dipastikan.", "category": "Verbal - Silogisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C (Dana hibah dicairkan). Dari premis 1 dan 2 dengan modus tollens diperoleh anggaran tidak disetujui; lalu dari premis 3 dengan silogisme disjungtif, dana hibah pasti dicairkan.", "concept": "Soal ini menguji penarikan kesimpulan dua langkah: modus tollens (p → q, ~q, maka ~p) dilanjutkan silogisme disjungtif (p ∨ r, ~p, maka r).", "steps": ["Lambangkan: p = anggaran disetujui, q = proyek dimulai bulan Mei, r = dana hibah dicairkan.", "Premis 1 dan 2: p → q dan ~q. Dengan modus tollens diperoleh ~p (anggaran tidak disetujui).", "Premis 3: p ∨ r. Karena ~p, maka r harus benar (silogisme disjungtif).", "Kesimpulan: dana hibah dicairkan (pilihan C)."], "options": {"A": "Salah. Modus tollens dari premis 1 dan 2 justru menghasilkan anggaran tidak disetujui.", "B": "Salah. Jika dana hibah tidak dicairkan dan anggaran tidak disetujui, premis 3 (p ∨ r) menjadi salah.", "C": "Benar. Hasil gabungan modus tollens (~p) dan silogisme disjungtif (r).", "D": "Salah. Bagian 'anggaran disetujui' bertentangan dengan ~p.", "E": "Salah. Kesimpulan dapat ditarik secara pasti melalui dua langkah penalaran."}, "tips": "Pada soal tiga premis, kerjakan dulu pasangan premis yang langsung menghasilkan fakta tunggal (di sini ~p), lalu gunakan fakta itu pada premis sisanya.", "reference": "Silogisme disjungtif: p ∨ q, ~p, maka q. Modus tollens: p → q, ~q, maka ~p.", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 40, "question_text": "Jika anggaran disetujui, proyek dimulai bulan Mei.\nProyek tidak dimulai bulan Mei.\nAnggaran disetujui atau dana hibah dicairkan.\n\nKesimpulan yang tepat adalah ...", "options": [{"key": "A", "text": "Anggaran disetujui."}, {"key": "B", "text": "Dana hibah tidak dicairkan."}, {"key": "C", "text": "Dana hibah dicairkan."}, {"key": "D", "text": "Anggaran disetujui dan dana hibah dicairkan."}, {"key": "E", "text": "Tidak dapat ditarik kesimpulan."}], "correct_answer": "C", "scores": null, "explanation": "Langkah 1 (modus tollens): p → q dan ~q, maka ~p, yaitu anggaran tidak disetujui. Langkah 2 (silogisme disjungtif): p ∨ r dan ~p, maka r. Jadi, dana hibah dicairkan.", "category": "Verbal - Silogisme", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B (T). Satu-satunya susunan yang memenuhi semua syarat adalah S, R, Q, U, T, P (kursi 1–6), sehingga kursi nomor 5 ditempati T.", "concept": "Soal ini menguji penalaran analitis susunan linear: tempatkan dulu posisi yang pasti, lalu uji kemungkinan blok berurutan (R–Q) dan syarat larangan bersebelahan.", "steps": ["Posisi pasti: U di kursi 4. P di kursi 1 atau 6. Blok R–Q (Q tepat di kanan R) dengan R tidak di ujung.", "Uji P di kursi 1: kursi sisa 2, 3, 5, 6. Blok R–Q hanya muat di 2–3 atau 5–6. Jika R–Q di 2–3, S dan T mengisi 5–6 (bersebelahan); jika R–Q di 5–6, S dan T mengisi 2–3 (bersebelahan). Keduanya melanggar syarat 4.", "Jadi P di kursi 6. Kursi sisa 1, 2, 3, 5. Blok R–Q muat di 1–2 atau 2–3; karena R tidak boleh di kursi 1 (ujung), R–Q di kursi 2–3.", "S dan T mengisi kursi 1 dan 5 (tidak bersebelahan). Karena nomor S lebih kecil, S di kursi 1 dan T di kursi 5.", "Susunan akhir (1–6): S, R, Q, U, T, P. Kursi nomor 5 adalah T."], "options": {"A": "Salah. S harus bernomor lebih kecil daripada T, sehingga S di kursi 1, bukan kursi 5.", "B": "Benar. Pada satu-satunya susunan yang sah (S, R, Q, U, T, P), T duduk di kursi 5.", "C": "Salah. R duduk di kursi 2; jika R di kursi 5, Q harus di kursi 6 yang sudah ditempati P.", "D": "Salah. Q duduk di kursi 3, tepat di kanan R di kursi 2.", "E": "Salah. P harus di kursi 6, karena P di kursi 1 memaksa S dan T bersebelahan."}, "tips": "Mulailah dari syarat yang paling membatasi (posisi tetap dan blok berurutan), lalu uji dua kemungkinan ujung untuk P; satu kemungkinan akan gugur cepat.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 41, "question_text": "Enam orang, yaitu P, Q, R, S, T, dan U, duduk berjajar menghadap ke depan pada kursi bernomor 1 sampai 6 dari kiri ke kanan. Ketentuannya:\n1. U duduk di kursi nomor 4.\n2. P duduk di salah satu kursi paling ujung.\n3. Q duduk tepat di sebelah kanan R.\n4. S tidak duduk bersebelahan dengan T.\n5. R tidak duduk di kursi paling ujung.\n6. S duduk di kursi bernomor lebih kecil daripada T.\n\nSiapakah yang duduk di kursi nomor 5?", "options": [{"key": "A", "text": "S"}, {"key": "B", "text": "T"}, {"key": "C", "text": "R"}, {"key": "D", "text": "Q"}, {"key": "E", "text": "P"}], "correct_answer": "B", "scores": null, "explanation": "Jika P di kursi 1, pasangan R–Q (R tidak di ujung) hanya dapat menempati kursi 2–3 atau 5–6. Jika R–Q di kursi 2–3, S dan T terpaksa menempati kursi 5–6; jika R–Q di kursi 5–6, S dan T terpaksa menempati kursi 2–3. Keduanya membuat S dan T bersebelahan, jadi P harus di kursi 6. Kursi tersisa 1, 2, 3, dan 5; karena R tidak di kursi 1, pasangan R–Q menempati kursi 2–3. S dan T mengisi kursi 1 dan 5, dengan nomor S lebih kecil, sehingga S di kursi 1 dan T di kursi 5. Susunan akhir (1–6): S, R, Q, U, T, P. Kursi nomor 5 ditempati T.", "category": "Verbal - Analitis", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E (Citra). Satu-satunya jadwal yang sah adalah Senin Dedi, Selasa Ana, Rabu Citra, Kamis Budi, Jumat Eko, sehingga yang piket hari Rabu adalah Citra.", "concept": "Soal ini menguji penalaran analitis penjadwalan: pasangan berurutan (Ana lalu Citra), larangan hari tertentu, urutan relatif (Dedi sebelum Eko), dan larangan posisi tepat sebelum.", "steps": ["Blok Ana–Citra (berurutan). Ana bukan Senin dan Citra bukan Jumat, sehingga blok hanya bisa Selasa–Rabu atau Rabu–Kamis.", "Uji Ana Rabu–Citra Kamis: Budi tidak boleh Senin atau Jumat, sehingga Budi harus Selasa. Padahal Selasa tepat sehari sebelum Ana (Rabu), melanggar syarat 6. Kemungkinan ini gugur.", "Jadi Ana Selasa dan Citra Rabu. Budi tidak boleh Senin atau Jumat, sehingga Budi Kamis (Kamis bukan sehari sebelum Selasa, jadi aman).", "Dedi dan Eko mengisi Senin dan Jumat; karena Dedi lebih awal, Dedi Senin dan Eko Jumat.", "Susunan akhir: Senin Dedi, Selasa Ana, Rabu Citra, Kamis Budi, Jumat Eko. Piket Rabu adalah Citra."], "options": {"A": "Salah. Ana piket hari Selasa; jika Ana Rabu, Budi terpaksa Selasa tepat sebelum Ana.", "B": "Salah. Budi piket hari Kamis, satu-satunya hari tersisa yang bukan Senin atau Jumat.", "C": "Salah. Dedi piket hari Senin karena harus lebih awal daripada Eko.", "D": "Salah. Eko piket hari Jumat, setelah Dedi.", "E": "Benar. Citra piket hari Rabu, tepat sehari setelah Ana yang piket hari Selasa."}, "tips": "Daftar dulu semua posisi yang mungkin untuk blok berurutan; biasanya hanya ada dua, dan salah satunya gugur oleh syarat larangan.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 42, "question_text": "Lima pegawai, yaitu Ana, Budi, Citra, Dedi, dan Eko, mendapat jadwal piket dari Senin sampai Jumat; setiap hari hanya satu orang dan setiap orang piket satu kali. Ketentuannya:\n1. Citra piket tepat sehari setelah Ana.\n2. Budi tidak piket pada hari Senin maupun Jumat.\n3. Dedi piket lebih awal daripada Eko.\n4. Ana tidak piket pada hari Senin.\n5. Citra tidak piket pada hari Jumat.\n6. Budi tidak piket tepat sehari sebelum Ana.\n\nSiapakah yang piket pada hari Rabu?", "options": [{"key": "A", "text": "Ana"}, {"key": "B", "text": "Budi"}, {"key": "C", "text": "Dedi"}, {"key": "D", "text": "Eko"}, {"key": "E", "text": "Citra"}], "correct_answer": "E", "scores": null, "explanation": "Pasangan Ana–Citra (berurutan) hanya dapat menempati Selasa–Rabu atau Rabu–Kamis (Ana bukan Senin, Citra bukan Jumat). Jika Ana Rabu–Citra Kamis, Budi harus Selasa (bukan Senin/Jumat), padahal Budi tidak boleh tepat sehari sebelum Ana. Jadi, Ana Selasa dan Citra Rabu; Budi mengisi Kamis; Dedi dan Eko mengisi Senin dan Jumat dengan Dedi lebih awal. Susunan akhir: Senin Dedi, Selasa Ana, Rabu Citra, Kamis Budi, Jumat Eko. Piket hari Rabu adalah Citra.", "category": "Verbal - Analitis", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D (J). Dengan H di peringkat 4, satu-satunya susunan yang sah adalah K, G, J, H, F, L (peringkat 1–6), sehingga peringkat 3 ditempati J.", "concept": "Soal ini menguji penalaran analitis peringkat dengan syarat tambahan (H di peringkat 4): urutan relatif K > G > H, blok F–L berurutan, serta larangan peringkat 1 dan larangan berurutan langsung.", "steps": ["Syarat tambahan: H di peringkat 4. Karena K lebih tinggi daripada G dan G lebih tinggi daripada H, K dan G berada di peringkat 1–3 dengan K di atas G.", "Peringkat 1–3 tinggal satu tempat setelah K dan G, sehingga blok F–L (L tepat di bawah F) tidak muat di sana; F–L harus di peringkat 5–6.", "Peringkat 1–3 diisi K, G, dan J. J tidak boleh di peringkat 1, sehingga J di peringkat 2 atau 3.", "Jika J di peringkat 2, K harus di peringkat 1 (di atas G) dan J berurutan langsung dengan K, melanggar syarat 4. Jadi J di peringkat 3, K di 1, G di 2.", "Susunan akhir: K (1), G (2), J (3), H (4), F (5), L (6). Peringkat 3 adalah J."], "options": {"A": "Salah. F berada di peringkat 5 karena blok F–L tidak muat di atas H.", "B": "Salah. G berada di peringkat 2; jika G di peringkat 3, J harus di peringkat 2 dan bersebelahan dengan K di peringkat 1.", "C": "Salah. K berada di peringkat 1; K tidak mungkin di peringkat 3 karena harus lebih tinggi daripada G yang juga di atas H.", "D": "Benar. J satu-satunya yang dapat menempati peringkat 3 tanpa melanggar syarat 3 dan 4.", "E": "Salah. L berada di peringkat 6, tepat di bawah F."}, "tips": "Pada soal bersyarat 'jika ...', gunakan syarat tambahan itu lebih dulu untuk mengunci posisi; blok dua orang yang berurutan sering hanya muat di satu tempat.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 43, "question_text": "Enam peserta seleksi, yaitu F, G, H, J, K, dan L, memperoleh peringkat 1 sampai 6 (peringkat 1 tertinggi) tanpa ada peringkat yang sama. Ketentuannya:\n1. Peringkat K lebih tinggi daripada G, dan peringkat G lebih tinggi daripada H.\n2. L berada tepat satu peringkat di bawah F.\n3. J tidak berada di peringkat 1.\n4. Peringkat J dan K tidak berurutan langsung.\n5. H tidak berada di peringkat terakhir.\n\nJika H berada di peringkat 4, peserta yang berada di peringkat 3 adalah ...", "options": [{"key": "A", "text": "F"}, {"key": "B", "text": "G"}, {"key": "C", "text": "K"}, {"key": "D", "text": "J"}, {"key": "E", "text": "L"}], "correct_answer": "D", "scores": null, "explanation": "Dengan H di peringkat 4, K dan G harus di atasnya dengan urutan K lalu G, sedangkan pasangan F–L yang berurutan tidak dapat diselipkan di atas H karena hanya tersisa satu tempat. Maka F–L menempati peringkat 5–6, sehingga peringkat 1–3 diisi K, G, dan J. J tidak boleh di peringkat 1 dan tidak boleh bersebelahan peringkat dengan K, sehingga susunannya K (1), G (2), J (3). Susunan akhir: K, G, J, H, F, L. Peringkat 3 adalah J.", "category": "Verbal - Analitis", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A (Keuangan). Satu-satunya susunan yang sah dari lantai 1 ke 5 adalah Umum, Hukum, Keuangan, Perencanaan, SDM, sehingga lantai 3 ditempati Keuangan.", "concept": "Soal ini menguji penalaran analitis susunan vertikal: menggabungkan urutan relatif (Hukum < Keuangan < SDM), blok berurutan (Perencanaan tepat di bawah SDM), dan posisi ujung untuk Umum.", "steps": ["Dari syarat 1, 3, dan 5: Hukum di bawah Keuangan, Keuangan di bawah SDM, dan Perencanaan tepat di bawah SDM. Karena Perencanaan menempel pada SDM, urutan naiknya Hukum, Keuangan, Perencanaan, SDM.", "Uji Umum di lantai 5: keempat divisi lain mengisi lantai 1–4 dengan Hukum di lantai 1, melanggar syarat 6. Kemungkinan ini gugur.", "Jadi Umum di lantai 1, dan lantai 2–5 diisi berurutan: Hukum (2), Keuangan (3), Perencanaan (4), SDM (5).", "Cek syarat 4: Umum (lantai 1) dan Keuangan (lantai 3) tidak bersebelahan, terpenuhi. Lantai 3 adalah Keuangan."], "options": {"A": "Benar. Keuangan menempati lantai 3 pada satu-satunya susunan yang sah.", "B": "Salah. Hukum berada di lantai 2, paling bawah di antara empat divisi selain Umum.", "C": "Salah. Perencanaan berada di lantai 4, tepat di bawah SDM.", "D": "Salah. SDM berada di lantai 5, paling atas karena harus di atas Keuangan dan Perencanaan.", "E": "Salah. Umum berada di lantai 1; Umum di lantai 5 memaksa Hukum ke lantai 1."}, "tips": "Gabungkan syarat urutan relatif menjadi satu rantai lebih dulu; jika rantainya sepanjang jumlah tempat yang tersisa, susunannya langsung terkunci.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 44, "question_text": "Lima divisi, yaitu Keuangan, Hukum, Umum, Perencanaan, dan SDM, masing-masing menempati satu lantai berbeda pada gedung lima lantai (lantai 1 paling bawah). Ketentuannya:\n1. Keuangan berada di lantai yang lebih tinggi daripada Hukum.\n2. Umum berada di lantai 1 atau lantai 5.\n3. SDM berada tepat satu lantai di atas Perencanaan.\n4. Umum dan Keuangan tidak berada di lantai yang bersebelahan.\n5. SDM berada di lantai yang lebih tinggi daripada Keuangan.\n6. Hukum tidak berada di lantai 1.\n\nDivisi yang menempati lantai 3 adalah ...", "options": [{"key": "A", "text": "Keuangan"}, {"key": "B", "text": "Hukum"}, {"key": "C", "text": "Perencanaan"}, {"key": "D", "text": "SDM"}, {"key": "E", "text": "Umum"}], "correct_answer": "A", "scores": null, "explanation": "Urutan naik yang pasti: Hukum < Keuangan < SDM, dengan Perencanaan tepat di bawah SDM. Jika Umum di lantai 5, keempat divisi lain menempati lantai 1–4 dengan Hukum paling bawah, padahal Hukum tidak boleh di lantai 1. Jadi, Umum di lantai 1, dan lantai 2–5 diisi Hukum, Keuangan, Perencanaan, SDM. Susunan akhir (lantai 1–5): Umum, Hukum, Keuangan, Perencanaan, SDM. Lantai 3 ditempati Keuangan (tidak bersebelahan dengan Umum, sesuai syarat 4).", "category": "Verbal - Analitis", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C (Candra). Dengan Arif berhadapan dengan Dian dan Eka berhadapan dengan Bima, kursi sisa untuk Candra dan Fajar saling berhadapan; karena Candra tidak boleh di sebelah Dian, Fajar berhadapan dengan Candra.", "concept": "Soal ini menguji penalaran analitis susunan melingkar: pada meja bundar enam kursi, kursi i berhadapan dengan kursi i + 3, dan dua kursi berurutan saling bersebelahan.", "steps": ["Beri nomor kursi 1–6 melingkar: 1 berhadapan dengan 4, 2 dengan 5, 3 dengan 6.", "Arif di kursi 1, Dian di kursi 4 (syarat 1). Bima bersebelahan dengan Arif, misalnya kursi 2, sehingga Eka di kursi 5 (syarat 3).", "Kursi sisa 3 dan 6 untuk Candra dan Fajar; kursi 3 dan 6 saling berhadapan. Kursi 3 bersebelahan dengan Dian (kursi 4), maka Candra di kursi 6 dan Fajar di kursi 3.", "Susunan melingkar: Arif, Bima, Fajar, Dian, Eka, Candra. Jika Bima di kursi 6, hasilnya hanya cerminan dan Fajar tetap berhadapan dengan Candra."], "options": {"A": "Salah. Arif berhadapan dengan Dian (syarat 1).", "B": "Salah. Bima berhadapan dengan Eka (syarat 3).", "C": "Benar. Candra dan Fajar menempati dua kursi sisa yang saling berhadapan.", "D": "Salah. Dian berhadapan dengan Arif.", "E": "Salah. Eka berhadapan dengan Bima."}, "tips": "Pada meja bundar enam kursi, setelah dua pasang orang yang berhadapan diketahui, dua orang sisanya pasti saling berhadapan; syarat lain hanya menentukan sisi duduknya.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 45, "question_text": "Enam orang, yaitu Arif, Bima, Candra, Dian, Eka, dan Fajar, duduk mengelilingi meja bundar dengan enam kursi yang berjarak sama, sehingga setiap orang duduk berhadapan dengan tepat satu orang. Ketentuannya:\n1. Arif duduk berhadapan dengan Dian.\n2. Bima duduk bersebelahan dengan Arif.\n3. Eka duduk berhadapan dengan Bima.\n4. Candra tidak duduk bersebelahan dengan Dian.\n\nSiapakah yang duduk berhadapan dengan Fajar?", "options": [{"key": "A", "text": "Arif"}, {"key": "B", "text": "Bima"}, {"key": "C", "text": "Candra"}, {"key": "D", "text": "Dian"}, {"key": "E", "text": "Eka"}], "correct_answer": "C", "scores": null, "explanation": "Misalkan kursi diberi nomor 1–6 melingkar (kursi 1 berhadapan dengan 4, 2 dengan 5, 3 dengan 6). Arif di kursi 1, Dian di kursi 4. Bima di sebelah Arif, misalnya kursi 2, sehingga Eka di kursi 5. Sisa kursi 3 dan 6 untuk Candra dan Fajar; kursi 3 bersebelahan dengan Dian, maka Candra di kursi 6 dan Fajar di kursi 3. Susunan melingkar: Arif, Bima, Fajar, Dian, Eka, Candra (jika Bima di sisi lain, hasilnya hanya cerminan). Fajar berhadapan dengan Candra.", "category": "Verbal - Analitis", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A (180). 25% × 480 = 120 dan 0,4 × 150 = 60, sehingga jumlahnya 120 + 60 = 180.", "concept": "Soal ini menguji operasi hitung campuran persen dan desimal. Perkalian dikerjakan lebih dulu, baru penjumlahan.", "steps": ["Hitung 25% × 480 = 1/4 × 480 = 120.", "Hitung 0,4 × 150 = 4/10 × 150 = 60.", "Jumlahkan: 120 + 60 = 180."], "options": {"A": "Benar. 120 + 60 = 180.", "B": "Salah. 185 tidak dihasilkan oleh perhitungan yang benar; selisih 5 biasanya akibat salah hitung salah satu suku.", "C": "Salah. 190 tidak sesuai; kedua suku yang benar adalah 120 dan 60.", "D": "Salah. 200 tidak sesuai; jumlah yang benar 180.", "E": "Salah. 210 muncul bila 0,4 × 150 keliru dihitung 90 (seperti 0,6 × 150)."}, "tips": "Ubah persen dan desimal menjadi pecahan sederhana: 25% = 1/4 dan 0,4 = 2/5, sehingga hitungannya cukup dengan pembagian.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 46, "question_text": "Hasil dari 25% × 480 + 0,4 × 150 adalah ...", "options": [{"key": "A", "text": "180"}, {"key": "B", "text": "185"}, {"key": "C", "text": "190"}, {"key": "D", "text": "200"}, {"key": "E", "text": "210"}], "correct_answer": "A", "scores": null, "explanation": "25% × 480 = 120 dan 0,4 × 150 = 60. Jumlahnya 120 + 60 = 180.", "category": "Numerik - Berhitung", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C (1,8). 2/3 : 4/9 = 2/3 × 9/4 = 3/2, lalu 3/2 × 1,2 = 1,8.", "concept": "Soal ini menguji pembagian pecahan, yaitu mengalikan dengan kebalikan pembagi, serta urutan operasi yang mendahulukan isi kurung.", "steps": ["Kerjakan isi kurung: 2/3 : 4/9 = 2/3 × 9/4 = 18/12 = 3/2.", "Kalikan dengan 1,2: 3/2 × 1,2 = 3,6 : 2 = 1,8."], "options": {"A": "Salah. 1,2 muncul bila hasil isi kurung dianggap 1, padahal 2/3 : 4/9 = 3/2.", "B": "Salah. 1,6 tidak sesuai; hasil isi kurung 3/2 dikalikan 1,2 menghasilkan 1,8.", "C": "Benar. 3/2 × 1,2 = 1,8.", "D": "Salah. 2,0 tidak dihasilkan oleh langkah yang benar.", "E": "Salah. 2,4 muncul bila isi kurung keliru dihitung 2, lalu 2 × 1,2 = 2,4."}, "tips": "Bagi pecahan = kali kebalikannya; sederhanakan silang dulu (2 dengan 4, 3 dengan 9) agar angkanya kecil.", "reference": "a/b : c/d = a/b × d/c.", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 47, "question_text": "Hasil dari (2/3 : 4/9) × 1,2 adalah ...", "options": [{"key": "A", "text": "1,2"}, {"key": "B", "text": "1,6"}, {"key": "C", "text": "1,8"}, {"key": "D", "text": "2,0"}, {"key": "E", "text": "2,4"}], "correct_answer": "C", "scores": null, "explanation": "Pembagian pecahan diubah menjadi perkalian dengan kebalikannya: 2/3 × 9/4 = 18/12 = 3/2. Kemudian 3/2 × 1,2 = 1,8.", "category": "Numerik - Berhitung", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E (19). √1.296 = 36, ∛3.375 = 15, dan 2⁵ = 32, sehingga 36 + 15 − 32 = 19.", "concept": "Soal ini menguji penghitungan akar kuadrat, akar pangkat tiga, dan perpangkatan. Akar sempurna dapat ditebak dari angka satuan dan perkiraan kuadrat atau kubik terdekat.", "steps": ["√1.296: angka satuan 6 berarti akarnya berakhiran 4 atau 6. Karena 35² = 1.225 < 1.296, akarnya 36 (cek 36² = 1.296).", "∛3.375: angka satuan 5 berarti akarnya berakhiran 5. Karena 10³ = 1.000 dan 20³ = 8.000, akarnya 15 (cek 15³ = 3.375).", "2⁵ = 32.", "Hitung: 36 + 15 − 32 = 19."], "options": {"A": "Salah. 11 tidak sesuai dengan 36 + 15 − 32.", "B": "Salah. 13 tidak sesuai; periksa kembali nilai akar dan pangkat.", "C": "Salah. 15 hanya nilai ∛3.375, bukan hasil akhir.", "D": "Salah. 17 muncul bila ∛3.375 keliru dihitung 13 (36 + 13 − 32 = 17), padahal 13³ = 2.197.", "E": "Benar. 36 + 15 − 32 = 19."}, "tips": "Gunakan angka satuan untuk menebak akar sempurna: kuadrat berakhiran 6 berasal dari 4 atau 6, kubik berakhiran 5 berasal dari 5.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 48, "question_text": "Hasil dari √1.296 + ∛3.375 − 2⁵ adalah ...", "options": [{"key": "A", "text": "11"}, {"key": "B", "text": "13"}, {"key": "C", "text": "15"}, {"key": "D", "text": "17"}, {"key": "E", "text": "19"}], "correct_answer": "E", "scores": null, "explanation": "√1.296 = 36 (karena 36² = 1.296), ∛3.375 = 15 (karena 15³ = 3.375), dan 2⁵ = 32. Jadi 36 + 15 − 32 = 19. Trik: angka satuan 6 pada 1.296 menunjukkan akar berakhiran 4 atau 6; 35² = 1.225 sehingga akarnya 36.", "category": "Numerik - Berhitung", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B (192). Dari 3^(x + 1) = 243 = 3⁵ diperoleh x = 4, sehingga 2^(2x) − 4^(x − 1) = 2⁸ − 4³ = 256 − 64 = 192.", "concept": "Soal ini menguji persamaan eksponen dengan menyamakan basis, lalu substitusi nilai x ke bentuk perpangkatan lain.", "steps": ["Tulis 243 sebagai pangkat 3: 243 = 3⁵.", "Samakan pangkat: x + 1 = 5, sehingga x = 4.", "Hitung 2^(2x) = 2⁸ = 256 dan 4^(x − 1) = 4³ = 64.", "Kurangkan: 256 − 64 = 192."], "options": {"A": "Salah. 128 = 2⁷, tidak sesuai dengan 256 − 64.", "B": "Benar. 256 − 64 = 192.", "C": "Salah. 224 muncul bila yang dikurangkan 32, bukan 4³ = 64.", "D": "Salah. 240 muncul bila 4^(x − 1) keliru dihitung 4² = 16.", "E": "Salah. 256 hanya nilai 2^(2x); suku 4^(x − 1) lupa dikurangkan."}, "tips": "Karena 4^(x − 1) = 2^(2x) : 4, hasilnya cukup 3/4 × 2^(2x) = 3/4 × 256 = 192.", "reference": "Jika a^m = a^n (a > 0, a ≠ 1), maka m = n.", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 49, "question_text": "Jika 3^(x + 1) = 243, maka nilai dari 2^(2x) − 4^(x − 1) adalah ...", "options": [{"key": "A", "text": "128"}, {"key": "B", "text": "192"}, {"key": "C", "text": "224"}, {"key": "D", "text": "240"}, {"key": "E", "text": "256"}], "correct_answer": "B", "scores": null, "explanation": "243 = 3⁵, sehingga x + 1 = 5 dan x = 4. Maka 2^(2x) = 2⁸ = 256 dan 4^(x − 1) = 4³ = 64. Hasilnya 256 − 64 = 192. Trik: 4^(x−1) = 2^(2x)/4, sehingga hasilnya 3/4 × 256 = 192.", "category": "Numerik - Berhitung", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D (159). Setiap suku diperoleh dari suku sebelumnya dikali 2 lalu ditambah 1, sehingga suku berikutnya 79 × 2 + 1 = 159.", "concept": "Soal ini menguji deret dengan pola operasi campuran (kali lalu tambah) yang diterapkan berulang pada suku sebelumnya.", "steps": ["Uji pola kali 2 tambah 1: 4 × 2 + 1 = 9, 9 × 2 + 1 = 19, 19 × 2 + 1 = 39, 39 × 2 + 1 = 79. Pola konsisten.", "Suku berikutnya: 79 × 2 + 1 = 159.", "Cek alternatif: selisihnya 5, 10, 20, 40 (dikali 2), sehingga selisih berikutnya 80 dan 79 + 80 = 159."], "options": {"A": "Salah. 119 = 79 + 40, yaitu selisih terakhir diulang, padahal selisihnya selalu dikali 2.", "B": "Salah. 149 tidak sesuai pola kali 2 tambah 1.", "C": "Salah. 158 = 79 × 2; langkah tambah 1 terlupa.", "D": "Benar. 79 × 2 + 1 = 159.", "E": "Salah. 161 = 79 × 2 + 3; tambahannya seharusnya 1."}, "tips": "Jika suku-suku kira-kira berlipat dua, uji pola 'kali 2 lalu tambah/kurang konstanta' sebelum mencari pola selisih.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 50, "question_text": "Bilangan berikutnya dari deret 4, 9, 19, 39, 79, ... adalah ...", "options": [{"key": "A", "text": "119"}, {"key": "B", "text": "149"}, {"key": "C", "text": "158"}, {"key": "D", "text": "159"}, {"key": "E", "text": "161"}], "correct_answer": "D", "scores": null, "explanation": "Pola: setiap suku dikali 2 lalu ditambah 1 (4×2+1 = 9, 9×2+1 = 19, dan seterusnya). Suku berikutnya 79 × 2 + 1 = 159.", "category": "Numerik - Deret Angka", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B (47). Selisih antarsuku adalah 3, 6, 9, 12 (bertambah 3), sehingga selisih berikutnya 15 dan suku berikutnya 32 + 15 = 47.", "concept": "Soal ini menguji deret bertingkat dua: selisih tingkat pertama membentuk deret aritmetika dengan beda tetap 3.", "steps": ["Hitung selisih: 5 − 2 = 3, 11 − 5 = 6, 20 − 11 = 9, 32 − 20 = 12.", "Selisih 3, 6, 9, 12 bertambah 3, sehingga selisih berikutnya 12 + 3 = 15.", "Suku berikutnya: 32 + 15 = 47."], "options": {"A": "Salah. 45 = 32 + 13; selisih seharusnya bertambah 3 menjadi 15, bukan 13.", "B": "Benar. 32 + 15 = 47.", "C": "Salah. 48 = 32 + 16, tidak sesuai pola selisih kelipatan 3.", "D": "Salah. 50 = 32 + 18, yaitu melompati satu selisih (seharusnya 15).", "E": "Salah. 52 = 32 + 20, tidak sesuai pola selisih."}, "tips": "Jika selisih antarsuku tidak tetap, tuliskan selisihnya dan cari pola tingkat kedua; di sini selisih tingkat kedua selalu 3.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 51, "question_text": "Bilangan berikutnya dari deret 2, 5, 11, 20, 32, ... adalah ...", "options": [{"key": "A", "text": "45"}, {"key": "B", "text": "47"}, {"key": "C", "text": "48"}, {"key": "D", "text": "50"}, {"key": "E", "text": "52"}], "correct_answer": "B", "scores": null, "explanation": "Selisih antarsuku: 3, 6, 9, 12 (bertambah 3 setiap kali). Selisih berikutnya 15, sehingga suku berikutnya 32 + 15 = 47.", "category": "Numerik - Deret Angka", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E (80, 28). Deret terdiri atas dua deret berselang: suku ganjil 5, 10, 20, 40 dikali 2 (berikutnya 80), dan suku genap 12, 16, 20, 24 ditambah 4 (berikutnya 28).", "concept": "Soal ini menguji deret berselang (loncat), yaitu dua deret dengan pola berbeda yang disisipkan bergantian. Deret panjang dengan naik-turun tidak teratur biasanya berpola seperti ini.", "steps": ["Pisahkan suku urutan ganjil: 5, 10, 20, 40. Polanya dikali 2, sehingga berikutnya 40 × 2 = 80.", "Pisahkan suku urutan genap: 12, 16, 20, 24. Polanya ditambah 4, sehingga berikutnya 24 + 4 = 28.", "Deret sudah memiliki 8 suku, maka suku ke-9 berasal dari deret ganjil (80) dan suku ke-10 dari deret genap (28). Jawaban: 80, 28."], "options": {"A": "Salah. 48 = 40 + 8; deret ganjil seharusnya dikali 2, bukan ditambah 8.", "B": "Salah. 60 = 40 + 20; deret ganjil dikali 2 sehingga hasilnya 80.", "C": "Salah. 80 benar, tetapi 26 = 24 + 2; deret genap selalu ditambah 4.", "D": "Salah. 80 benar, tetapi 30 = 24 + 6; deret genap selalu ditambah 4.", "E": "Benar. 40 × 2 = 80 dan 24 + 4 = 28."}, "tips": "Jika deret panjang (8 suku atau lebih) naik-turun tidak beraturan, langsung pisahkan suku ganjil dan suku genap.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 52, "question_text": "Dua bilangan berikutnya dari deret 5, 12, 10, 16, 20, 20, 40, 24, ..., ... adalah ...", "options": [{"key": "A", "text": "48, 28"}, {"key": "B", "text": "60, 28"}, {"key": "C", "text": "80, 26"}, {"key": "D", "text": "80, 30"}, {"key": "E", "text": "80, 28"}], "correct_answer": "E", "scores": null, "explanation": "Deret ini terdiri atas dua deret berselang. Suku ganjil: 5, 10, 20, 40, ... (dikali 2), berikutnya 80. Suku genap: 12, 16, 20, 24, ... (ditambah 4), berikutnya 28. Jadi dua bilangan berikutnya adalah 80, 28.", "category": "Numerik - Deret Angka", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C (U). Jika huruf diubah ke nomor urut abjad, deretnya 1, 3, 6, 10, 15 dengan selisih 2, 3, 4, 5, sehingga berikutnya 15 + 6 = 21, yaitu huruf U.", "concept": "Soal ini menguji deret huruf yang diubah menjadi deret angka berdasarkan urutan abjad (A = 1, B = 2, dan seterusnya), lalu dicari pola selisihnya.", "steps": ["Ubah ke angka: A = 1, C = 3, F = 6, J = 10, O = 15.", "Hitung selisih: 2, 3, 4, 5 (bertambah 1).", "Selisih berikutnya 6, sehingga 15 + 6 = 21.", "Huruf ke-21 adalah U (P = 16, Q = 17, R = 18, S = 19, T = 20, U = 21)."], "options": {"A": "Salah. S = 19 = 15 + 4; selisih seharusnya 6.", "B": "Salah. T = 20 = 15 + 5, yaitu selisih terakhir diulang, padahal selisih selalu bertambah 1.", "C": "Benar. 15 + 6 = 21 = U.", "D": "Salah. V = 22 = 15 + 7; selisih melompat terlalu jauh.", "E": "Salah. W = 23 = 15 + 8, tidak sesuai pola selisih."}, "tips": "Hafalkan patokan abjad E = 5, J = 10, O = 15, T = 20, Y = 25 agar konversi huruf ke angka cepat.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 53, "question_text": "Huruf berikutnya dari deret A, C, F, J, O, ... adalah ...", "options": [{"key": "A", "text": "S"}, {"key": "B", "text": "T"}, {"key": "C", "text": "U"}, {"key": "D", "text": "V"}, {"key": "E", "text": "W"}], "correct_answer": "C", "scores": null, "explanation": "Ubah huruf menjadi urutan abjad: A = 1, C = 3, F = 6, J = 10, O = 15. Selisihnya 2, 3, 4, 5, sehingga selisih berikutnya 6: 15 + 6 = 21, yaitu huruf U.", "category": "Numerik - Deret Angka", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A (54). Setiap suku sama dengan jumlah dua suku sebelumnya ditambah 1, sehingga suku berikutnya 20 + 33 + 1 = 54.", "concept": "Soal ini menguji deret rekursif mirip Fibonacci, yaitu suku dibentuk dari dua suku sebelumnya. Polanya juga terlihat dari selisih antarsuku yang membentuk deret Fibonacci.", "steps": ["Uji pola: 1 + 2 + 1 = 4, 2 + 4 + 1 = 7, 4 + 7 + 1 = 12, 7 + 12 + 1 = 20, 12 + 20 + 1 = 33. Pola konsisten.", "Suku berikutnya: 20 + 33 + 1 = 54.", "Cek dengan selisih: 1, 2, 3, 5, 8, 13 (deret Fibonacci). Selisih berikutnya 8 + 13 = 21, dan 33 + 21 = 54."], "options": {"A": "Benar. 20 + 33 + 1 = 54.", "B": "Salah. 55 = 33 + 22; selisih berikutnya seharusnya 21 (8 + 13).", "C": "Salah. 56 = 33 + 23, tidak sesuai pola.", "D": "Salah. 63 tidak sesuai pola jumlah dua suku sebelumnya ditambah 1.", "E": "Salah. 66 = 33 × 2; pola deret ini bukan kali 2."}, "tips": "Jika selisih antarsuku tampak seperti 1, 2, 3, 5, 8, 13, curigai pola Fibonacci: selisih berikutnya adalah jumlah dua selisih terakhir.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 54, "question_text": "Bilangan berikutnya dari deret 1, 2, 4, 7, 12, 20, 33, ... adalah ...", "options": [{"key": "A", "text": "54"}, {"key": "B", "text": "55"}, {"key": "C", "text": "56"}, {"key": "D", "text": "63"}, {"key": "E", "text": "66"}], "correct_answer": "A", "scores": null, "explanation": "Setiap suku sama dengan jumlah dua suku sebelumnya ditambah 1: 1 + 2 + 1 = 4, 2 + 4 + 1 = 7, 4 + 7 + 1 = 12, 7 + 12 + 1 = 20, 12 + 20 + 1 = 33. Suku berikutnya 20 + 33 + 1 = 54. Cara lain: selisihnya 1, 2, 3, 5, 8, 13 (deret Fibonacci), selisih berikutnya 21, sehingga 33 + 21 = 54.", "category": "Numerik - Deret Angka", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban yang tepat adalah B (P < Q). P = 3/8 × 64 = 24 dan Q = 60% × 45 = 27, sehingga P lebih kecil daripada Q.", "concept": "Soal ini menguji perbandingan kuantitatif: hitung nilai P dan Q secara pasti, lalu bandingkan.", "steps": ["Hitung P: 64 : 8 = 8, lalu 8 × 3 = 24.", "Hitung Q: 60% × 45 = 0,6 × 45 = 27.", "Bandingkan: 24 < 27, maka P < Q."], "options": {"A": "Salah. P = 24 lebih kecil, bukan lebih besar, daripada Q = 27.", "B": "Benar. 24 < 27.", "C": "Salah. 24 ≠ 27.", "D": "Salah. 2P = 48, tidak sama dengan Q = 27.", "E": "Salah. P dan Q bernilai pasti, sehingga hubungannya dapat ditentukan."}, "tips": "Pilihan 'tidak dapat ditentukan' hanya tepat bila ada variabel yang nilainya tidak tunggal; jika P dan Q berupa angka pasti, cukup hitung.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 55, "question_text": "Jika P = 3/8 × 64 dan Q = 60% dari 45, maka ...", "options": [{"key": "A", "text": "P > Q"}, {"key": "B", "text": "P < Q"}, {"key": "C", "text": "P = Q"}, {"key": "D", "text": "2P = Q"}, {"key": "E", "text": "Hubungan P dan Q tidak dapat ditentukan"}], "correct_answer": "B", "scores": null, "explanation": "P = 3/8 × 64 = 24 dan Q = 60/100 × 45 = 27. Karena 24 < 27, maka P < Q. (2P = 48 ≠ 27.)", "category": "Numerik - Perbandingan Kuantitatif", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D (P = Q). x = 2/3 × 90 = 60 dan y = 125% × 48 = 60, sehingga P = Q = 60.", "concept": "Soal ini menguji perbandingan kuantitatif dengan pecahan dan persen lebih dari 100%. 125% sama dengan 5/4.", "steps": ["Hitung x: 90 : 3 = 30, lalu 30 × 2 = 60.", "Hitung y: 125% = 5/4, sehingga 48 : 4 = 12, lalu 12 × 5 = 60.", "Karena P = x = 60 dan Q = y = 60, maka P = Q."], "options": {"A": "Salah. P tidak lebih besar; keduanya bernilai 60.", "B": "Salah. P tidak lebih kecil; keduanya bernilai 60.", "C": "Salah. 2Q = 120, tidak sama dengan P = 60.", "D": "Benar. P = Q = 60.", "E": "Salah. Nilai x dan y pasti, sehingga hubungannya dapat ditentukan."}, "tips": "Ubah persen di atas 100% menjadi pecahan: 125% = 5/4, 150% = 3/2, 175% = 7/4.", "reference": null, "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 56, "question_text": "Diketahui x = 2/3 dari 90 dan y = 125% dari 48.\nJika P = x dan Q = y, maka ...", "options": [{"key": "A", "text": "P > Q"}, {"key": "B", "text": "P < Q"}, {"key": "C", "text": "P = 2Q"}, {"key": "D", "text": "P = Q"}, {"key": "E", "text": "Hubungan P dan Q tidak dapat ditentukan"}], "correct_answer": "D", "scores": null, "explanation": "x = 2/3 × 90 = 60 dan y = 125/100 × 48 = 5/4 × 48 = 60. Jadi P = Q = 60.", "category": "Numerik - Perbandingan Kuantitatif", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E (tidak dapat ditentukan). Persamaan x² − 7x + 12 = 0 memiliki dua akar, x = 3 dan x = 4; untuk x = 3 berlaku P < Q, sedangkan untuk x = 4 berlaku P > Q.", "concept": "Soal ini menguji perbandingan kuantitatif dengan variabel dari persamaan kuadrat. Jika nilai variabel tidak tunggal dan memberi hubungan yang berbeda, hubungan P dan Q tidak dapat ditentukan.", "steps": ["Faktorkan: x² − 7x + 12 = (x − 3)(x − 4) = 0, sehingga x = 3 atau x = 4.", "Untuk x = 3: P = 3 < Q = 3,5.", "Untuk x = 4: P = 4 > Q = 3,5.", "Karena hubungan berubah sesuai akar yang dipilih, hubungan P dan Q tidak dapat ditentukan."], "options": {"A": "Salah. P > Q hanya berlaku untuk x = 4, tidak untuk x = 3.", "B": "Salah. P < Q hanya berlaku untuk x = 3, tidak untuk x = 4.", "C": "Salah. P = Q memerlukan x = 3,5, padahal 3,5 bukan akar persamaan.", "D": "Salah. 2P = Q memerlukan x = 1,75, yang juga bukan akar persamaan.", "E": "Benar. Dua akar memberi dua hubungan berbeda, sehingga hubungannya tidak tunggal."}, "tips": "Jika Q berada di antara dua akar persamaan kuadrat, jawabannya hampir pasti 'tidak dapat ditentukan'; jika Q di luar kedua akar, hubungannya tetap.", "reference": "Jumlah akar x² + bx + c = 0 adalah −b dan hasil kalinya c; di sini akar 3 dan 4 (3 + 4 = 7, 3 × 4 = 12).", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 57, "question_text": "Jika x memenuhi persamaan x² − 7x + 12 = 0, P = x, dan Q = 3,5, maka ...", "options": [{"key": "A", "text": "P > Q"}, {"key": "B", "text": "P < Q"}, {"key": "C", "text": "P = Q"}, {"key": "D", "text": "2P = Q"}, {"key": "E", "text": "Hubungan P dan Q tidak dapat ditentukan"}], "correct_answer": "E", "scores": null, "explanation": "x² − 7x + 12 = (x − 3)(x − 4) = 0, sehingga x = 3 atau x = 4. Untuk x = 3 berlaku P < Q, sedangkan untuk x = 4 berlaku P > Q. Karena hubungannya bergantung pada nilai x yang tidak tunggal, hubungan P dan Q tidak dapat ditentukan. Trik: perhatikan bahwa Q = 3,5 tepat berada di antara kedua akar.", "category": "Numerik - Perbandingan Kuantitatif", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban yang tepat adalah C (Rp540.000). Setelah diskon 25% harganya Rp600.000, lalu diskon tambahan 10% dari Rp600.000 menghasilkan Rp540.000.", "concept": "Soal ini menguji diskon bertingkat: diskon kedua dihitung dari harga setelah diskon pertama, sehingga persentase diskon tidak boleh dijumlahkan.", "steps": ["Diskon pertama 25%: harga menjadi 75% × Rp800.000 = Rp600.000.", "Diskon kedua 10% dari Rp600.000 = Rp60.000, sehingga harga menjadi Rp600.000 − Rp60.000 = Rp540.000.", "Cara cepat: 800.000 × 0,75 × 0,9 = 540.000 (setara diskon total 32,5%, bukan 35%)."], "options": {"A": "Salah. Rp520.000 muncul bila diskon dijumlahkan menjadi 35% (800.000 × 0,65), atau bila 10% dihitung dari harga awal.", "B": "Salah. Rp530.000 tidak dihasilkan oleh perhitungan diskon bertingkat yang benar.", "C": "Benar. 800.000 × 0,75 × 0,9 = 540.000.", "D": "Salah. Rp560.000 setara diskon 30% dari harga awal, tidak sesuai dengan diskon 25% lalu 10%.", "E": "Salah. Rp600.000 baru harga setelah diskon pertama; diskon tambahan 10% belum dihitung."}, "tips": "Diskon bertingkat a% lalu b% setara dengan diskon total a + b − (a × b)/100 persen; di sini 25 + 10 − 2,5 = 32,5%.", "reference": "Harga akhir = harga awal × (1 − d₁) × (1 − d₂).", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 58, "question_text": "Sebuah toko memberikan diskon 25% untuk sebuah jaket seharga Rp800.000, kemudian diskon tambahan 10% dari harga setelah diskon pertama. Harga yang harus dibayar pembeli adalah ...", "options": [{"key": "A", "text": "Rp520.000"}, {"key": "B", "text": "Rp530.000"}, {"key": "C", "text": "Rp540.000"}, {"key": "D", "text": "Rp560.000"}, {"key": "E", "text": "Rp600.000"}], "correct_answer": "C", "scores": null, "explanation": "Setelah diskon 25%: 75% × Rp800.000 = Rp600.000. Setelah diskon tambahan 10%: 90% × Rp600.000 = Rp540.000. Diskon bertingkat tidak boleh dijumlahkan menjadi 35% (yang menghasilkan Rp520.000). Trik: 800.000 × 0,75 × 0,9 = 540.000.", "category": "Numerik - Soal Cerita", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban yang tepat adalah A (10). Bersama-sama mereka menyelesaikan 1/6 pekerjaan per hari, sehingga dalam 2 hari selesai 1/3 dan sisa 2/3; Bayu menyelesaikan 2/3 pekerjaan dalam 2/3 × 15 = 10 hari.", "concept": "Soal ini menguji pekerjaan bersama: kecepatan kerja dinyatakan sebagai bagian pekerjaan per hari (1/waktu), dan kecepatan bersama adalah jumlah kecepatan masing-masing.", "steps": ["Kecepatan Andi = 1/10 per hari, Bayu = 1/15 per hari. Bersama: 1/10 + 1/15 = 3/30 + 2/30 = 5/30 = 1/6 per hari.", "Selama 2 hari: 2 × 1/6 = 1/3 pekerjaan selesai, sehingga sisa 1 − 1/3 = 2/3.", "Bayu sendirian menyelesaikan sisa: (2/3) : (1/15) = 2/3 × 15 = 10 hari."], "options": {"A": "Benar. Sisa 2/3 pekerjaan dikerjakan Bayu dalam 2/3 × 15 = 10 hari.", "B": "Salah. 11 hari tidak dihasilkan oleh perhitungan yang benar.", "C": "Salah. 12 hari adalah total waktu sejak awal (2 + 10), bukan waktu Bayu menyelesaikan sisanya.", "D": "Salah. 13 hari tidak sesuai; sisa pekerjaan 2/3 dengan kecepatan Bayu 1/15 per hari.", "E": "Salah. 15 hari adalah waktu Bayu menyelesaikan seluruh pekerjaan sendirian dari awal."}, "tips": "Baca pertanyaan dengan teliti: yang ditanyakan waktu Bayu menyelesaikan sisa, bukan total waktu sejak awal (12 hari).", "reference": "Kecepatan bersama = 1/t₁ + 1/t₂; waktu = bagian pekerjaan : kecepatan.", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 59, "question_text": "Andi dapat menyelesaikan suatu pekerjaan sendirian dalam 10 hari, sedangkan Bayu dapat menyelesaikannya sendirian dalam 15 hari. Mereka bekerja bersama selama 2 hari, kemudian Andi berhenti dan sisa pekerjaan diselesaikan Bayu sendirian. Sisa pekerjaan tersebut diselesaikan Bayu dalam waktu ... hari.", "options": [{"key": "A", "text": "10"}, {"key": "B", "text": "11"}, {"key": "C", "text": "12"}, {"key": "D", "text": "13"}, {"key": "E", "text": "15"}], "correct_answer": "A", "scores": null, "explanation": "Kecepatan kerja bersama per hari = 1/10 + 1/15 = 3/30 + 2/30 = 1/6. Selama 2 hari terselesaikan 2/6 = 1/3 pekerjaan, sehingga sisa 2/3 pekerjaan. Bayu menyelesaikan sisa tersebut dalam 2/3 × 15 = 10 hari. (Total waktu sejak awal 12 hari, tetapi yang ditanyakan hanya waktu Bayu menyelesaikan sisanya.)", "category": "Numerik - Soal Cerita", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban yang tepat adalah D (09.00). Pukul 07.30 Andi sudah menempuh 30 km, sehingga sisa jarak 210 km ditempuh bersama dengan kecepatan 140 km/jam dalam 1,5 jam; mereka berpapasan pukul 07.30 + 1,5 jam = 09.00.", "concept": "Soal ini menguji gerak berpapasan dengan waktu berangkat berbeda: samakan dulu titik awal waktu, lalu gunakan jumlah kecepatan karena keduanya saling mendekat.", "steps": ["Dari 07.00 sampai 07.30 hanya Andi yang bergerak: 0,5 jam × 60 km/jam = 30 km.", "Sisa jarak pada pukul 07.30: 240 − 30 = 210 km.", "Sejak 07.30 keduanya saling mendekat dengan kecepatan 60 + 80 = 140 km/jam, sehingga waktu berpapasan 210 : 140 = 1,5 jam.", "Waktu berpapasan: 07.30 + 1 jam 30 menit = 09.00."], "options": {"A": "Salah. 08.30 muncul bila durasi 1,5 jam dihitung dari pukul 07.00, padahal durasi itu berlaku sejak 07.30.", "B": "Salah. 08.43 muncul bila 240 : 140 ≈ 1 jam 43 menit dihitung sejak 07.00 tanpa memperhitungkan keterlambatan berangkat Budi.", "C": "Salah. 08.45 tidak sesuai; waktu berpapasan dihitung 1,5 jam setelah 07.30.", "D": "Benar. 07.30 + 1,5 jam = 09.00.", "E": "Salah. 09.30 terlambat 30 menit; pada pukul 09.00 total jarak tempuh Andi 120 km dan Budi 120 km, sudah 240 km."}, "tips": "Cek jawaban: pukul 09.00 Andi sudah berjalan 2 jam (120 km) dan Budi 1,5 jam (120 km); 120 + 120 = 240 km, tepat sama dengan jarak kedua kota.", "reference": "Waktu berpapasan = sisa jarak : (v₁ + v₂), dihitung sejak keduanya sama-sama bergerak.", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 60, "question_text": "Jarak kota A dan kota B adalah 240 km. Andi berangkat dari kota A menuju kota B pukul 07.00 dengan kecepatan rata-rata 60 km/jam. Pada jalan yang sama, Budi berangkat dari kota B menuju kota A pukul 07.30 dengan kecepatan rata-rata 80 km/jam. Mereka akan berpapasan pada pukul ...", "options": [{"key": "A", "text": "08.30"}, {"key": "B", "text": "08.43"}, {"key": "C", "text": "08.45"}, {"key": "D", "text": "09.00"}, {"key": "E", "text": "09.30"}], "correct_answer": "D", "scores": null, "explanation": "Pukul 07.30 Andi sudah menempuh 0,5 × 60 = 30 km, sehingga sisa jarak 210 km. Sejak 07.30 keduanya saling mendekat dengan kecepatan 60 + 80 = 140 km/jam, sehingga waktu berpapasan 210 : 140 = 1,5 jam. Mereka berpapasan pukul 07.30 + 1 jam 30 menit = 09.00. Kesalahan umum adalah menghitung 240 : 140 sejak pukul 07.00 (sekitar 08.43).", "category": "Numerik - Soal Cerita", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban yang tepat adalah E (80). Jumlah nilai 25 siswa adalah 1.700 dan jumlah nilai 30 siswa adalah 2.100, sehingga jumlah nilai 5 siswa susulan 400 dan rata-ratanya 400 : 5 = 80.", "concept": "Soal ini menguji rata-rata gabungan: rata-rata dikalikan banyak data menghasilkan jumlah nilai, dan jumlah nilai kelompok baru adalah selisih jumlah total dengan jumlah awal.", "steps": ["Jumlah nilai awal: 25 × 68 = 1.700.", "Jumlah nilai seluruh 30 siswa: 30 × 70 = 2.100.", "Jumlah nilai 5 siswa susulan: 2.100 − 1.700 = 400.", "Rata-rata 5 siswa susulan: 400 : 5 = 80."], "options": {"A": "Salah. 72 muncul bila kenaikan rata-rata 2 langsung ditambahkan ke 70 tanpa memperhitungkan banyak siswa.", "B": "Salah. 74 tidak sesuai; jumlah nilai siswa susulan 400 dibagi 5 adalah 80.", "C": "Salah. 76 tidak sesuai dengan perhitungan jumlah nilai.", "D": "Salah. 78 tidak sesuai; periksa kembali 30 × 70 = 2.100 dan 25 × 68 = 1.700.", "E": "Benar. 400 : 5 = 80."}, "tips": "Cara cepat: kenaikan rata-rata 2 untuk 30 siswa (30 × 2 = 60) ditanggung 5 siswa, sehingga rata-rata mereka 70 + 60 : 5 = 80.", "reference": "Jumlah nilai = rata-rata × banyak data.", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tiu", "question_number": 61, "question_text": "Nilai rata-rata ujian 25 siswa adalah 68. Setelah 5 siswa susulan ikut ujian, nilai rata-rata seluruh siswa menjadi 70. Nilai rata-rata 5 siswa susulan tersebut adalah ...", "options": [{"key": "A", "text": "72"}, {"key": "B", "text": "74"}, {"key": "C", "text": "76"}, {"key": "D", "text": "78"}, {"key": "E", "text": "80"}], "correct_answer": "E", "scores": null, "explanation": "Jumlah nilai awal = 25 × 68 = 1.700. Jumlah nilai 30 siswa = 30 × 70 = 2.100. Jumlah nilai 5 siswa susulan = 2.100 − 1.700 = 400, sehingga rata-ratanya 400 : 5 = 80. Trik: kenaikan rata-rata 2 untuk 30 siswa (= 60) ditanggung 5 siswa, sehingga rata-rata mereka 70 + 60/5 = 80.", "category": "Numerik - Soal Cerita", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban terbaik adalah opsi A (skor 5). Petugas memanfaatkan data kependudukan yang sudah tersedia di sistem untuk memverifikasi data keluarga, sehingga warga lanjut usia yang datang dari jauh tetap dapat dilayani tanpa melanggar ketentuan.", "concept": "Soal ini menguji aspek pelayanan publik, yaitu orientasi pada kebutuhan masyarakat. ASN yang ideal mencari solusi yang memudahkan warga, terutama kelompok rentan seperti lansia, dengan tetap berpegang pada prosedur resmi.", "steps": ["Orientasi pelayanan: utamakan solusi yang membuat warga tetap terlayani, bukan sekadar menyatakan berkas kurang lengkap.", "Kepatuhan aturan: jalan keluar harus tetap sesuai ketentuan, misalnya verifikasi melalui sistem kependudukan resmi, bukan melonggarkan syarat sesuka hati.", "Empati pada kelompok rentan: pertimbangkan kondisi warga lanjut usia yang datang dari jauh agar tidak perlu bolak-balik."], "options": {"A": "Skor 5: Petugas proaktif memakai sistem kependudukan resmi untuk menutup kekurangan dokumen sehingga warga terlayani tanpa melanggar prosedur.", "B": "Skor 3: Penjelasan yang ramah sudah baik, tetapi warga lansia tetap harus kembali dari tempat yang jauh tanpa ada upaya mencari alternatif.", "C": "Skor 4: Ada inisiatif memberi jalan keluar melalui perangkat desa, tetapi layanan belum dapat diproses pada hari itu juga.", "D": "Skor 2: Saran ini tidak menyelesaikan masalah saat itu dan justru memindahkan beban pengurusan kepada keluarga warga.", "E": "Skor 1: Menolak secara kaku dengan merujuk papan informasi menunjukkan sikap tanpa empati dan tanpa upaya membantu."}, "tips": "Pilih opsi yang menyelesaikan kebutuhan warga saat itu juga melalui cara resmi; opsi skor 4 biasanya membantu, tetapi penyelesaiannya masih tertunda.", "reference": "Nilai dasar ASN BerAKHLAK: Berorientasi Pelayanan", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 62, "question_text": "Anda bertugas di loket pelayanan KTP elektronik kantor kecamatan. Seorang warga lanjut usia datang dari desa yang cukup jauh, tetapi tidak membawa fotokopi Kartu Keluarga yang menjadi salah satu persyaratan. Sikap Anda ...", "options": [{"key": "A", "text": "Saya memverifikasi data keluarganya melalui sistem kependudukan dan memprosesnya bila memungkinkan sesuai ketentuan."}, {"key": "B", "text": "Saya menjelaskan dengan ramah bahwa persyaratannya belum lengkap dan memintanya datang kembali dengan membawa fotokopi Kartu Keluarga."}, {"key": "C", "text": "Saya menjelaskan persyaratan secara rinci dan menawarkan agar dokumen yang kurang dapat dititipkan melalui perangkat desa setempat."}, {"key": "D", "text": "Saya menyarankan agar pengurusan selanjutnya diwakilkan kepada anggota keluarga yang lebih muda supaya tidak perlu bolak-balik."}, {"key": "E", "text": "Saya menolak berkasnya karena persyaratan layanan sudah jelas tertulis di papan informasi di depan kantor kecamatan."}], "correct_answer": null, "scores": {"A": 5, "B": 3, "C": 4, "D": 2, "E": 1}, "explanation": "Soal ini menguji aspek pelayanan publik, khususnya orientasi pada kebutuhan masyarakat. Opsi A paling ideal karena petugas mencari solusi yang memudahkan warga tanpa melanggar prosedur sekaligus tetap memberi edukasi persyaratan, sedangkan opsi E paling rendah karena petugas menolak secara kaku tanpa empati maupun alternatif penyelesaian. Urutan skor: A (5), C (4), B (3), D (2), E (1).", "category": "Pelayanan Publik", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban terbaik adalah opsi D (skor 5). Menghubungi langsung perwakilan dinas yang jarang hadir untuk memahami kendalanya, lalu menyepakati jadwal bersama, menyentuh akar masalah dan memperkuat koordinasi lintas instansi.", "concept": "Soal ini menguji aspek jejaring kerja, khususnya komunikasi dan koordinasi lintas instansi. ASN yang ideal aktif menjalin komunikasi, mencari tahu hambatan mitra, dan membangun kesepakatan demi tujuan program bersama.", "steps": ["Inisiatif komunikasi: dekati mitra secara langsung untuk memahami kendalanya, bukan menunggu atau menyalahkan.", "Solusi bersama: kesepakatan jadwal yang disetujui semua pihak lebih efektif daripada keputusan sepihak.", "Fokus pada tujuan program: keberhasilan penurunan stunting lebih penting daripada mempersoalkan siapa yang kurang berkomitmen."], "options": {"A": "Skor 1: Ikut mengurangi kehadiran justru melemahkan tim dan mengorbankan tujuan program bersama.", "B": "Skor 3: Disiplin menjalankan tugas sendiri itu baik, tetapi tidak ada upaya mengatasi hambatan koordinasi yang terjadi.", "C": "Skor 2: Melaporkan rekan sebagai kurang berkomitmen cenderung menyalahkan tanpa memahami kendalanya terlebih dahulu.", "D": "Skor 5: Pendekatan langsung untuk memahami kendala dan menyepakati jadwal bersama memperkuat jejaring sekaligus menyelesaikan akar masalah.", "E": "Skor 4: Usulan berbagi notulen membantu agar semua anggota tetap terinformasi, tetapi belum menyentuh penyebab ketidakhadiran."}, "tips": "Opsi skor 5 pada soal jejaring kerja biasanya mendekati pihak terkait secara langsung untuk mencari kesepakatan, sedangkan skor 4 hanya memperbaiki alur informasi atau prosedur.", "reference": "Nilai dasar ASN BerAKHLAK: Kolaboratif", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 63, "question_text": "Anda ditunjuk menjadi anggota tim lintas dinas untuk program percepatan penurunan stunting. Dalam beberapa rapat koordinasi terakhir, perwakilan dari salah satu dinas jarang hadir sehingga pembahasan sering tertunda. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya ikut mengurangi kehadiran karena rapat tidak akan efektif apabila anggota lain juga tidak serius mengikutinya."}, {"key": "B", "text": "Saya tetap menghadiri setiap rapat dan menyelesaikan tugas bagian saya sesuai dengan jadwal yang telah ditetapkan tim."}, {"key": "C", "text": "Saya menyampaikan kepada ketua tim bahwa perwakilan dinas tersebut kurang berkomitmen terhadap keberhasilan program bersama."}, {"key": "D", "text": "Saya menghubungi perwakilan dinas itu untuk memahami kendalanya, lalu mengusulkan jadwal rapat yang disepakati bersama."}, {"key": "E", "text": "Saya mengusulkan kepada ketua tim agar notulen dan pembagian tugas dikirimkan kepada seluruh anggota setelah setiap rapat selesai."}], "correct_answer": null, "scores": {"A": 1, "B": 3, "C": 2, "D": 5, "E": 4}, "explanation": "Soal ini menguji aspek jejaring kerja, khususnya membangun komunikasi dan koordinasi lintas instansi. Opsi D paling ideal karena pendekatan langsung dan solusi yang disepakati bersama memperkuat jejaring kerja, sedangkan opsi A paling rendah karena sikap tersebut justru melemahkan kerja sama dan mengorbankan tujuan program. Urutan skor: D (5), E (4), B (3), C (2), A (1).", "category": "Jejaring Kerja", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban terbaik adalah opsi B (skor 5). Menghadiri undangan sambil mempelajari makna tradisi dan menyesuaikan diri dengan tata krama setempat menunjukkan keterbukaan dan penghargaan yang tulus terhadap budaya masyarakat tempat bertugas.", "concept": "Soal ini menguji aspek sosial budaya, khususnya kemampuan beradaptasi dengan keragaman budaya. ASN yang ideal terbuka, menghormati adat setempat, dan mau belajar agar dapat berbaur dengan masyarakat yang dilayaninya.", "steps": ["Keterbukaan: hadir dan terlibat dalam kegiatan masyarakat sebagai bentuk penghargaan.", "Kemauan belajar: memahami makna tradisi, bukan sekadar hadir secara formal.", "Adaptasi: menyesuaikan sikap dengan tata krama setempat agar diterima dengan baik."], "options": {"A": "Skor 3: Hadir sebagian menunjukkan niat baik, tetapi keterlibatannya masih bergantung pada kenyamanan pribadi.", "B": "Skor 5: Hadir sekaligus mempelajari makna tradisi dan menyesuaikan diri mencerminkan adaptasi budaya yang paling utuh.", "C": "Skor 2: Menitipkan salam terkesan sopan, tetapi menghindari kesempatan untuk belajar dan berbaur dengan warga.", "D": "Skor 4: Hadir dan menanyakan etika terlebih dahulu sudah sangat baik, tetapi belum sampai pada upaya memahami makna tradisinya.", "E": "Skor 1: Menolak hadir karena menganggap tradisi tidak berkaitan dengan dirinya menunjukkan sikap menutup diri."}, "tips": "Bedakan antara sekadar menyesuaikan etika (skor 4) dan berupaya memahami makna budaya sekaligus menyesuaikan diri (skor 5).", "reference": "Nilai dasar ASN BerAKHLAK: Harmonis", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 64, "question_text": "Anda baru ditempatkan di daerah yang adat istiadatnya sangat berbeda dengan daerah asal Anda. Warga sekitar sering mengadakan upacara adat dan beberapa kali mengundang Anda untuk hadir. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menghadiri sebagian undangan yang waktunya tidak bertabrakan dengan urusan pekerjaan maupun urusan pribadi saya."}, {"key": "B", "text": "Saya menghadiri undangan sambil mempelajari makna tradisinya dan menyesuaikan diri dengan tata krama setempat."}, {"key": "C", "text": "Saya menitipkan salam dan permohonan maaf melalui tetangga karena merasa belum memahami adat setempat dengan baik."}, {"key": "D", "text": "Saya menghadiri undangan dan terlebih dahulu bertanya kepada rekan kerja setempat tentang etika yang perlu saya perhatikan."}, {"key": "E", "text": "Saya tidak menghadiri undangan tersebut karena merasa tradisi itu tidak ada kaitannya dengan diri dan tugas saya."}], "correct_answer": null, "scores": {"A": 3, "B": 5, "C": 2, "D": 4, "E": 1}, "explanation": "Soal ini menguji aspek sosial budaya, khususnya adaptasi terhadap keragaman budaya. Opsi B paling ideal karena menunjukkan keterbukaan, penghargaan, dan kesediaan belajar budaya setempat, sedangkan opsi E paling rendah karena mencerminkan sikap menutup diri dan tidak menghargai masyarakat tempat bertugas. Urutan skor: B (5), D (4), A (3), C (2), E (1).", "category": "Sosial Budaya", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban terbaik adalah opsi B (skor 5). Pegawai belajar secara mandiri dari panduan, mengikuti pelatihan resmi, dan bertanya kepada admin, sehingga cepat menguasai aplikasi dan mendukung transformasi digital instansi.", "concept": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya adaptasi terhadap transformasi digital. ASN yang ideal terbuka terhadap perubahan dan berinisiatif meningkatkan kemampuan digitalnya melalui sumber resmi.", "steps": ["Sikap adaptif: menerima kebijakan digitalisasi, bukan mempertahankan cara lama.", "Inisiatif belajar mandiri: memanfaatkan panduan dan pelatihan yang disediakan instansi.", "Memanfaatkan dukungan resmi: bertanya kepada admin saat menemui kendala agar penguasaan aplikasi tuntas."], "options": {"A": "Skor 1: Menolak perubahan dengan alasan sistem lama sudah baik menghambat transformasi digital instansi.", "B": "Skor 5: Belajar dari panduan, pelatihan, dan admin menunjukkan inisiatif mandiri melalui sumber resmi untuk menguasai aplikasi.", "C": "Skor 4: Belajar dari rekan yang mahir sudah adaptif, tetapi masih bergantung pada orang lain dan belum memanfaatkan sumber resmi secara menyeluruh.", "D": "Skor 2: Tetap bekerja manual lalu membebankan pemindahan data kepada rekan berarti menghindari kewajiban menggunakan aplikasi.", "E": "Skor 3: Menggunakan aplikasi sebatas kebutuhan sudah patuh, tetapi tanpa upaya meningkatkan kemampuan."}, "tips": "Opsi skor 5 menunjukkan belajar mandiri melalui jalur resmi secara menyeluruh, sedangkan skor 4 umumnya masih bergantung pada bantuan rekan.", "reference": "Nilai dasar ASN BerAKHLAK: Adaptif", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 65, "question_text": "Instansi tempat Anda bekerja mewajibkan penggunaan aplikasi persuratan elektronik untuk menggantikan surat-menyurat manual. Anda belum terbiasa menggunakan aplikasi tersebut. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya menyampaikan keberatan kepada atasan karena sistem manual selama ini sudah berjalan baik dan tidak bermasalah."}, {"key": "B", "text": "Saya mempelajari panduan, mengikuti pelatihan yang disediakan, dan bertanya kepada admin bila menemui kesulitan."}, {"key": "C", "text": "Saya meminta rekan yang sudah mahir untuk mengajari saya cara menggunakan fitur-fitur utama aplikasi tersebut."}, {"key": "D", "text": "Saya tetap membuat surat secara manual, lalu meminta rekan memindahkannya ke dalam aplikasi persuratan."}, {"key": "E", "text": "Saya menggunakan aplikasi tersebut sebatas fitur yang diperlukan untuk menyelesaikan tugas harian saya."}], "correct_answer": null, "scores": {"A": 1, "B": 5, "C": 4, "D": 2, "E": 3}, "explanation": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya adaptasi terhadap transformasi digital. Opsi B paling ideal karena pegawai belajar secara mandiri dan memanfaatkan sumber resmi untuk menguasai aplikasi, sedangkan opsi A paling rendah karena sikap menolak perubahan menghambat transformasi digital instansi. Urutan skor: B (5), C (4), E (3), D (2), A (1).", "category": "Teknologi Informasi dan Komunikasi", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban terbaik adalah opsi E (skor 5). Pegawai menyusun prioritas berdasarkan tenggat dan dampak, lalu mengomunikasikan rencana penyelesaiannya kepada atasan, sehingga kedua tugas dapat dikelola secara terencana dan transparan.", "concept": "Soal ini menguji aspek profesionalisme, khususnya manajemen prioritas dan tanggung jawab kerja. ASN yang ideal menerima tugas, mengatur beban kerja secara sistematis, dan berkomunikasi terbuka dengan atasan.", "steps": ["Tanggung jawab: tidak menolak atau melempar tugas yang diberikan atasan.", "Manajemen prioritas: tentukan urutan pengerjaan berdasarkan tenggat dan dampak pekerjaan.", "Komunikasi dengan atasan: sampaikan rencana penyelesaian agar ekspektasi selaras."], "options": {"A": "Skor 2: Meminta tugas baru ditunda menunjukkan kurangnya kesiapan mengelola beban kerja yang mendesak.", "B": "Skor 4: Mengutamakan tugas mendesak dan menambah jam kerja menunjukkan tanggung jawab tinggi, tetapi tanpa perencanaan yang dikomunikasikan kepada atasan.", "C": "Skor 1: Menyerahkan tugas kepada rekan berarti melempar tanggung jawab yang telah diberikan kepadanya.", "D": "Skor 3: Mengerjakan bergantian menunjukkan kesediaan, tetapi tanpa prioritas yang jelas sehingga keduanya berisiko terlambat.", "E": "Skor 5: Menyusun prioritas berdasarkan tenggat dan dampak lalu menyampaikannya kepada atasan adalah pengelolaan kerja yang terencana dan transparan."}, "tips": "Jika dua opsi sama-sama mengerjakan tugas, pilih yang disertai perencanaan prioritas dan komunikasi dengan atasan sebagai skor 5.", "reference": "Nilai dasar ASN BerAKHLAK: Akuntabel", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 66, "question_text": "Atasan memberikan tugas mendesak kepada Anda, padahal Anda sedang menyelesaikan laporan lain yang tenggat waktunya juga sudah dekat. Sikap Anda ...", "options": [{"key": "A", "text": "Saya meminta atasan menunda tugas baru tersebut sampai laporan yang sedang saya kerjakan benar-benar selesai."}, {"key": "B", "text": "Saya mengerjakan tugas mendesak terlebih dahulu dan menambah jam kerja agar laporan sebelumnya tetap selesai tepat waktu."}, {"key": "C", "text": "Saya menyerahkan tugas baru tersebut kepada rekan lain karena beban pekerjaan saya sudah cukup banyak."}, {"key": "D", "text": "Saya menerima tugas tersebut dan mengerjakannya secara bergantian dengan laporan yang sedang saya susun."}, {"key": "E", "text": "Saya menyusun prioritas berdasarkan tenggat dan dampaknya, lalu menyampaikan rencana penyelesaiannya kepada atasan."}], "correct_answer": null, "scores": {"A": 2, "B": 4, "C": 1, "D": 3, "E": 5}, "explanation": "Soal ini menguji aspek profesionalisme, khususnya manajemen prioritas dan tanggung jawab kerja. Opsi E paling ideal karena pegawai mengelola beban kerja secara terencana dan transparan kepada atasan, sedangkan opsi C paling rendah karena pegawai melempar tanggung jawab yang telah diberikan kepadanya. Urutan skor: E (5), B (4), D (3), A (2), C (1).", "category": "Profesionalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban terbaik adalah opsi C (skor 5). Pegawai meluruskan pesan provokatif dengan klarifikasi dari sumber resmi dan melaporkannya melalui kanal aduan, sehingga penyebaran hoaks bernuansa SARA dihentikan secara aktif dan sesuai jalur yang benar.", "concept": "Soal ini menguji aspek anti radikalisme, khususnya penangkalan hoaks dan ujaran kebencian bernuansa SARA. ASN yang ideal menjaga persatuan dengan aktif meluruskan informasi menyesatkan dan menggunakan mekanisme pelaporan resmi.", "steps": ["Verifikasi: rujuk sumber resmi sebelum menanggapi informasi yang belum jelas kebenarannya.", "Peran aktif meluruskan: sampaikan klarifikasi agar warga tidak terprovokasi.", "Jalur resmi: laporkan konten provokatif melalui kanal aduan agar ditindaklanjuti pihak berwenang."], "options": {"A": "Skor 3: Tidak meneruskan dan mencari kebenaran sudah tepat, tetapi masih pasif terhadap provokasi yang sedang berlangsung di grup.", "B": "Skor 4: Meminta admin menghapus pesan dan mengingatkan kerukunan sudah aktif, tetapi belum disertai klarifikasi resmi dan pelaporan.", "C": "Skor 5: Meluruskan dengan klarifikasi resmi dan melapor melalui kanal aduan menghentikan hoaks secara aktif dan tepat jalur.", "D": "Skor 1: Meneruskan pesan kepada keluarga justru ikut menyebarkan konten yang memecah belah masyarakat.", "E": "Skor 2: Keluar dari grup memang menghindari konflik, tetapi membiarkan hoaks terus menyebar tanpa upaya pencegahan."}, "tips": "Opsi skor 5 umumnya memadukan klarifikasi dari sumber resmi dengan pelaporan, sedangkan skor 4 baru mencegah tanpa meluruskan informasinya.", "reference": "Nilai dasar ASN BerAKHLAK: Loyal, sejalan dengan kewajiban ASN setia dan taat kepada Pancasila, UUD 1945, NKRI, dan pemerintah yang sah", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 67, "question_text": "Di grup percakapan warga, beredar pesan berantai yang menghasut kebencian terhadap kelompok suku tertentu dengan informasi yang belum jelas kebenarannya. Beberapa anggota grup mulai ikut berkomentar keras. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya tidak meneruskan pesan tersebut dan mencari tahu kebenarannya melalui situs resmi pemerintah atau aparat."}, {"key": "B", "text": "Saya meminta admin grup menghapus pesan tersebut dan mengingatkan seluruh anggota untuk menjaga kerukunan antarwarga."}, {"key": "C", "text": "Saya meluruskan pesan itu dengan klarifikasi dari sumber resmi dan melaporkan kontennya melalui kanal aduan resmi."}, {"key": "D", "text": "Saya meneruskan pesan itu kepada keluarga agar mereka lebih waspada terhadap kelompok yang disebutkan."}, {"key": "E", "text": "Saya keluar dari grup tersebut agar tidak ikut terlibat dalam perdebatan yang berpotensi semakin memanas."}], "correct_answer": null, "scores": {"A": 3, "B": 4, "C": 5, "D": 1, "E": 2}, "explanation": "Soal ini menguji aspek anti radikalisme, khususnya penangkalan hoaks dan ujaran kebencian bernuansa SARA. Opsi C paling ideal karena pegawai aktif meluruskan informasi, menjaga kerukunan, dan menggunakan jalur pelaporan resmi, sedangkan opsi D paling rendah karena pegawai justru ikut menyebarkan konten yang memecah belah masyarakat. Urutan skor: C (5), B (4), A (3), E (2), D (1).", "category": "Anti Radikalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban terbaik adalah opsi D (skor 5). Pegawai tetap menuntaskan layanan bagi pasien yang sudah mengambil nomor antrean dan mengabari keluarga bahwa ia akan sedikit terlambat, sehingga kepentingan pelayanan didahulukan tanpa mengabaikan urusan pribadi.", "concept": "Soal ini menguji aspek pelayanan publik, khususnya komitmen menuntaskan layanan kepada masyarakat. ASN yang ideal mendahulukan kepentingan pelayanan di atas kepentingan pribadi dan memastikan warga yang sudah mengantre tetap terlayani.", "steps": ["Komitmen menuntaskan layanan: warga yang sudah terdaftar berhak dilayani sampai selesai.", "Mendahulukan kepentingan umum: urusan pribadi dikelola tanpa mengorbankan layanan.", "Kualitas layanan: penyelesaian tidak boleh dipaksakan cepat hingga mengurangi mutu."], "options": {"A": "Skor 4: Berkoordinasi dengan rekan agar pasien tetap terlayani adalah solusi yang baik, tetapi tanggung jawab layanan dialihkan kepada orang lain.", "B": "Skor 2: Meminta pasien kembali besok dengan prioritas antrean tetap merugikan pasien yang sudah menunggu hari itu.", "C": "Skor 1: Menutup layanan sambil menyalahkan pasien mengabaikan kebutuhan masyarakat yang sudah mengantre.", "D": "Skor 5: Melayani pasien terdaftar hingga selesai sambil mengabari keluarga menunjukkan komitmen penuh pada layanan.", "E": "Skor 3: Mempercepat pelayanan menunjukkan niat menyelesaikan, tetapi berisiko menurunkan kualitas layanan kepada pasien."}, "tips": "Bila ada opsi menuntaskan layanan sendiri dan opsi mengalihkannya kepada rekan, opsi menuntaskan sendiri biasanya bernilai 5.", "reference": "Nilai dasar ASN BerAKHLAK: Berorientasi Pelayanan", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 68, "question_text": "Anda bertugas di loket pendaftaran puskesmas. Jam layanan hampir berakhir, tetapi masih ada beberapa pasien yang sudah mengambil nomor antrean. Di sisi lain, Anda memiliki janji penting dengan keluarga. Sikap Anda ...", "options": [{"key": "A", "text": "Saya berkoordinasi dengan rekan yang masih bertugas agar pasien tetap terlayani, lalu memastikan serah terima berjalan baik."}, {"key": "B", "text": "Saya meminta pasien yang belum terlayani untuk kembali besok pagi dengan nomor antrean yang didahulukan."}, {"key": "C", "text": "Saya menutup layanan sesuai jam yang tertera karena pasien seharusnya datang lebih awal dari jadwal."}, {"key": "D", "text": "Saya tetap melayani pasien yang sudah terdaftar hingga selesai dan mengabari keluarga bahwa saya akan sedikit terlambat."}, {"key": "E", "text": "Saya mempercepat pelayanan kepada pasien yang tersisa agar dapat selesai tepat ketika jam layanan berakhir."}], "correct_answer": null, "scores": {"A": 4, "B": 2, "C": 1, "D": 5, "E": 3}, "explanation": "Soal ini menguji aspek pelayanan publik, khususnya komitmen menuntaskan layanan kepada masyarakat. Opsi D paling ideal karena pegawai menuntaskan layanan secara langsung dan tetap mengomunikasikan urusan pribadinya, sedangkan opsi C paling rendah karena pegawai menyalahkan pasien dan mengabaikan kebutuhan masyarakat yang sudah mengantre. Urutan skor: D (5), A (4), E (3), B (2), C (1).", "category": "Pelayanan Publik", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban terbaik adalah opsi E (skor 5). Pegawai baru aktif memperkenalkan diri, terlibat dalam kegiatan tim, dan terbuka belajar dari senior, sehingga cepat membangun relasi kerja yang baik dalam tim yang sudah solid.", "concept": "Soal ini menguji aspek jejaring kerja, khususnya inisiatif membangun relasi kerja. ASN yang ideal proaktif menjalin hubungan dengan rekan, terlibat dalam kegiatan bersama, dan bersedia belajar dari yang lebih berpengalaman.", "steps": ["Inisiatif: memulai interaksi tanpa menunggu diajak.", "Keterlibatan: ikut serta dalam kegiatan tim, tidak hanya bersosialisasi di waktu luang.", "Keterbukaan belajar: menghargai pengalaman rekan senior sebagai sumber pembelajaran."], "options": {"A": "Skor 3: Fokus pada kinerja itu positif, tetapi kurang ada upaya aktif membangun hubungan dengan rekan kerja.", "B": "Skor 4: Menyapa dan mengenal rekan satu per satu sudah proaktif, tetapi keterlibatannya masih sebatas di luar kegiatan kerja tim.", "C": "Skor 1: Lebih banyak bekerja sendiri menunjukkan sikap menarik diri sehingga jejaring dalam tim tidak terbangun.", "D": "Skor 2: Menunggu diajak senior menunjukkan sikap pasif dalam membangun relasi kerja.", "E": "Skor 5: Aktif memperkenalkan diri, terlibat dalam kegiatan tim, dan belajar dari senior adalah bentuk inisiatif membangun jejaring yang paling lengkap."}, "tips": "Skor 5 menggabungkan inisiatif berkenalan dengan keterlibatan nyata dalam kegiatan tim, sedangkan skor 4 hanya pada tahap bersosialisasi.", "reference": "Nilai dasar ASN BerAKHLAK: Kolaboratif", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 69, "question_text": "Anda pegawai baru di sebuah dinas. Rekan-rekan satu tim sudah lama bekerja bersama dan terlihat sangat akrab satu sama lain. Sikap Anda ...", "options": [{"key": "A", "text": "Saya fokus menyelesaikan pekerjaan dengan baik agar rekan-rekan menilai kinerja dan sikap saya secara positif."}, {"key": "B", "text": "Saya menyapa rekan-rekan dan berusaha mengenal mereka satu per satu ketika jam istirahat kantor."}, {"key": "C", "text": "Saya lebih banyak bekerja sendiri karena merasa sulit masuk ke dalam kelompok yang sudah akrab."}, {"key": "D", "text": "Saya menunggu rekan-rekan yang lebih senior untuk terlebih dahulu mengajak saya berinteraksi."}, {"key": "E", "text": "Saya aktif memperkenalkan diri, terlibat dalam kegiatan tim, dan terbuka belajar dari rekan-rekan senior."}], "correct_answer": null, "scores": {"A": 3, "B": 4, "C": 1, "D": 2, "E": 5}, "explanation": "Soal ini menguji aspek jejaring kerja, khususnya inisiatif membangun relasi kerja. Opsi E paling ideal karena pegawai proaktif membangun hubungan dan bersedia belajar dari rekan kerja, sedangkan opsi C paling rendah karena pegawai menarik diri sehingga tidak membangun jejaring dalam tim. Urutan skor: E (5), B (4), A (3), D (2), C (1).", "category": "Jejaring Kerja", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban terbaik adalah opsi B (skor 5). Pegawai memahami gaya bicara rekan sebagai perbedaan budaya dan menengahi agar diskusi tetap fokus pada substansi, sehingga suasana rapat terjaga dan pendapat yang baik tetap dihargai.", "concept": "Soal ini menguji aspek sosial budaya, khususnya toleransi terhadap perbedaan gaya komunikasi antarbudaya. ASN yang ideal memahami latar belakang budaya orang lain dan berperan merekatkan, bukan memperuncing perbedaan.", "steps": ["Pemahaman budaya: melihat gaya bicara sebagai perbedaan kebiasaan, bukan niat buruk.", "Peran menengahi: menjaga suasana tetap kondusif saat itu juga.", "Fokus pada substansi: menilai pendapat berdasarkan isinya, bukan cara penyampaiannya."], "options": {"A": "Skor 3: Menanggapi isi secara objektif sudah tepat, tetapi tidak membantu meredakan ketegangan rekan yang tersinggung.", "B": "Skor 5: Memahami perbedaan budaya sekaligus menengahi agar diskusi fokus pada substansi menjaga rapat tetap produktif.", "C": "Skor 2: Meminta pimpinan rapat menegur semua peserta mengalihkan masalah tanpa memahami akar perbedaan budaya.", "D": "Skor 4: Menyimak substansi lalu menyampaikan masukan secara pribadi itu bijak, tetapi ketegangan dalam rapat dibiarkan berlangsung saat itu.", "E": "Skor 1: Menegur di depan forum bersifat emosional dan dapat mempermalukan rekan."}, "tips": "Pilih opsi yang menyelesaikan ketegangan saat itu juga sambil menghargai perbedaan budaya; penanganan yang ditunda setelah rapat biasanya bernilai 4.", "reference": "Nilai dasar ASN BerAKHLAK: Harmonis", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 70, "question_text": "Dalam rapat tim, seorang rekan dari daerah lain menyampaikan pendapat dengan nada tinggi dan blak-blakan sesuai kebiasaan di daerahnya. Beberapa rekan terlihat tersinggung, padahal isi pendapatnya cukup baik. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menanggapi isi pendapatnya secara objektif tanpa mempersoalkan cara penyampaian yang ia gunakan."}, {"key": "B", "text": "Saya memahami gaya bicaranya sebagai perbedaan budaya dan membantu menengahi agar diskusi tetap fokus pada substansi."}, {"key": "C", "text": "Saya meminta pimpinan rapat mengingatkan seluruh peserta agar menjaga nada bicara selama berdiskusi."}, {"key": "D", "text": "Saya menyimak substansi pendapatnya, lalu seusai rapat menyampaikan secara pribadi bahwa sebagian rekan merasa kurang nyaman."}, {"key": "E", "text": "Saya ikut menegurnya di depan forum karena cara bicaranya telah mengganggu suasana dan perasaan peserta rapat."}], "correct_answer": null, "scores": {"A": 3, "B": 5, "C": 2, "D": 4, "E": 1}, "explanation": "Soal ini menguji aspek sosial budaya, khususnya toleransi terhadap perbedaan gaya komunikasi antarbudaya. Opsi B paling ideal karena pegawai memahami perbedaan budaya sekaligus menjaga suasana rapat tetap produktif saat itu juga, sedangkan opsi E paling rendah karena teguran di depan forum bersifat emosional dan dapat mempermalukan rekan. Urutan skor: B (5), D (4), A (3), C (2), E (1).", "category": "Sosial Budaya", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban terbaik adalah opsi A (skor 5). Pegawai tidak membuka tautan, memverifikasi melalui kanal resmi, dan melaporkan surel kepada pengelola TI, sehingga dirinya terlindungi dan pegawai lain juga terhindar dari upaya phishing.", "concept": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya keamanan informasi dan kewaspadaan terhadap phishing. ASN yang ideal menjaga kerahasiaan kredensial, memverifikasi informasi melalui jalur resmi, dan melaporkan ancaman siber.", "steps": ["Kewaspadaan: jangan pernah memasukkan nama pengguna dan kata sandi melalui tautan yang belum terverifikasi.", "Verifikasi melalui kanal resmi instansi.", "Pelaporan: informasikan kepada pengelola TI agar ancaman dapat dicegah secara menyeluruh."], "options": {"A": "Skor 5: Menghindari tautan, memverifikasi melalui kanal resmi, dan melapor kepada pengelola TI melindungi diri sekaligus organisasi.", "B": "Skor 1: Mengisi data begitu saja berarti menyerahkan kredensial kepada pihak yang belum terverifikasi.", "C": "Skor 4: Mengabaikan tautan dan mengecek situs resmi sudah aman, tetapi tidak melaporkan ancaman sehingga pegawai lain tetap berisiko.", "D": "Skor 3: Menghapus surel mencurigakan sudah aman bagi diri sendiri, tetapi tanpa verifikasi maupun pelaporan.", "E": "Skor 2: Bertanya kepada rekan menunjukkan kehati-hatian, tetapi masih membuka kemungkinan untuk mengisi data pada tautan berbahaya."}, "tips": "Pada soal keamanan siber, skor 5 biasanya memadukan menghindari risiko, verifikasi resmi, dan pelaporan, sedangkan skor 4 tidak melaporkan.", "reference": "Nilai dasar ASN BerAKHLAK: Akuntabel", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 71, "question_text": "Anda menerima surel yang mengatasnamakan instansi pembina kepegawaian. Surel tersebut meminta Anda memperbarui data kepegawaian dengan memasukkan nama pengguna dan kata sandi melalui tautan yang disertakan. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya tidak membuka tautannya, memverifikasi melalui kanal resmi instansi, dan melaporkan surel itu kepada pengelola TI."}, {"key": "B", "text": "Saya segera mengisi data yang diminta agar data kepegawaian saya tidak terlambat diperbarui."}, {"key": "C", "text": "Saya mengabaikan tautan tersebut, lalu mengecek kebenaran pengumuman pembaruan data melalui situs resmi instansi terkait."}, {"key": "D", "text": "Saya menghapus surel tersebut karena alamat pengirimnya terlihat mencurigakan dan tidak resmi."}, {"key": "E", "text": "Saya bertanya kepada rekan apakah mereka juga menerima surel serupa sebelum memutuskan untuk mengisinya."}], "correct_answer": null, "scores": {"A": 5, "B": 1, "C": 4, "D": 3, "E": 2}, "explanation": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya keamanan informasi dan kewaspadaan terhadap phishing. Opsi A paling ideal karena pegawai menghindari risiko, memverifikasi melalui jalur resmi, dan membantu mencegah korban lain, sedangkan opsi B paling rendah karena pegawai menyerahkan kredensial kepada pihak yang belum terverifikasi. Urutan skor: A (5), C (4), D (3), E (2), B (1).", "category": "Teknologi Informasi dan Komunikasi", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban terbaik adalah opsi E (skor 5). Pegawai segera menghubungi atasan, menjelaskan kesalahannya secara terbuka, dan menyerahkan laporan yang telah diperbaiki, sehingga integritas dan akurasi data tetap terjaga.", "concept": "Soal ini menguji aspek profesionalisme, khususnya integritas dan tanggung jawab atas hasil kerja. ASN yang ideal jujur mengakui kesalahan dan segera memperbaikinya sebelum menimbulkan dampak.", "steps": ["Kejujuran: mengakui kesalahan meskipun belum ada yang menyadarinya.", "Kesegeraan: koreksi secepat mungkin sebelum data dipakai untuk mengambil keputusan.", "Komunikasi langsung: sampaikan penjelasan kepada atasan agar tidak terjadi salah paham."], "options": {"A": "Skor 1: Membiarkan kesalahan karena tidak ada yang tahu berarti menutupi kesalahan yang dapat merugikan organisasi.", "B": "Skor 2: Menunggu tanggapan atasan menunda koreksi dan meremehkan dampak kesalahan data.", "C": "Skor 4: Mengirimkan revisi disertai catatan perubahan sudah bertanggung jawab, tetapi kurang disertai komunikasi langsung kepada atasan.", "D": "Skor 3: Memperbaiki hanya di arsip pribadi tanpa memberi tahu atasan bersifat pasif dan kurang transparan.", "E": "Skor 5: Segera menghubungi atasan, menjelaskan kesalahan, dan menyerahkan perbaikan menunjukkan integritas dan tanggung jawab penuh."}, "tips": "Opsi skor 5 menunjukkan koreksi yang segera disertai penjelasan langsung kepada atasan, sedangkan skor 4 hanya mengirimkan perbaikan.", "reference": "Nilai dasar ASN BerAKHLAK: Akuntabel", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 72, "question_text": "Setelah mengirimkan laporan kepada atasan, Anda menyadari ada kesalahan angka pada salah satu tabel. Sejauh ini belum ada yang menyadari kesalahan tersebut. Sikap Anda ...", "options": [{"key": "A", "text": "Saya membiarkannya karena laporan sudah terkirim dan tidak ada yang menyadari kesalahan tersebut."}, {"key": "B", "text": "Saya menunggu tanggapan atasan terlebih dahulu karena kesalahannya kecil dan belum tentu berpengaruh."}, {"key": "C", "text": "Saya memperbaiki laporan tersebut dan mengirimkan versi revisinya kepada atasan disertai catatan perubahan."}, {"key": "D", "text": "Saya memperbaikinya di arsip saya dan akan menyampaikannya apabila atasan menanyakan laporan tersebut."}, {"key": "E", "text": "Saya segera menghubungi atasan, menjelaskan kesalahannya, dan menyerahkan laporan yang sudah diperbaiki."}], "correct_answer": null, "scores": {"A": 1, "B": 2, "C": 4, "D": 3, "E": 5}, "explanation": "Soal ini menguji aspek profesionalisme, khususnya integritas dan tanggung jawab atas hasil kerja. Opsi E paling ideal karena pegawai jujur, bertanggung jawab, dan segera mengoreksi kesalahannya secara terbuka, sedangkan opsi A paling rendah karena pegawai menutupi kesalahan yang dapat merugikan organisasi. Urutan skor: E (5), C (4), D (3), B (2), A (1).", "category": "Profesionalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban terbaik adalah opsi C (skor 5). Pegawai menolak dengan tegas, menjelaskan kedudukan Pancasila sebagai dasar negara, dan melaporkan kelompok tersebut kepada pihak berwenang, sehingga ia tidak hanya menjaga diri tetapi juga mencegah penyebaran paham yang mengancam dasar negara.", "concept": "Soal ini menguji aspek anti radikalisme, khususnya kesetiaan pada Pancasila dan kewaspadaan terhadap paham radikal. ASN yang ideal teguh menolak ideologi yang bertentangan dengan dasar negara dan berperan aktif mencegah penyebarannya melalui jalur resmi.", "steps": ["Ketegasan sikap: tidak memberi ruang bagi ajakan yang menolak Pancasila.", "Edukasi: meluruskan pemahaman tentang kedudukan Pancasila sebagai dasar negara.", "Pelaporan resmi: menyampaikan kepada pihak berwenang agar potensi radikalisme ditangani."], "options": {"A": "Skor 2: Menunda jawaban demi menjaga hubungan menunjukkan sikap ragu terhadap ajakan yang bertentangan dengan dasar negara.", "B": "Skor 3: Menolak dengan sopan dan menjaga jarak melindungi diri sendiri, tetapi tidak meluruskan pemahaman maupun mencegah penyebarannya.", "C": "Skor 5: Menolak tegas, menjelaskan kedudukan Pancasila, dan melapor kepada pihak berwenang merupakan bentuk kesetiaan dan pencegahan yang paling lengkap.", "D": "Skor 4: Menolak sambil mengingatkan sudah tegas dan edukatif, tetapi belum menempuh jalur pelaporan resmi.", "E": "Skor 1: Ikut menghadiri kajian membuka diri terhadap paparan paham yang bertentangan dengan dasar negara."}, "tips": "Pada soal radikalisme, skor 5 biasanya menolak, meluruskan, dan melapor; skor 4 menolak dan meluruskan tanpa pelaporan.", "reference": "Nilai dasar ASN BerAKHLAK: Loyal, sejalan dengan kewajiban ASN setia dan taat kepada Pancasila, UUD 1945, NKRI, dan pemerintah yang sah", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 73, "question_text": "Seorang kenalan di lingkungan tempat tinggal mengajak Anda bergabung dengan kelompok kajian tertutup yang berpandangan bahwa Pancasila tidak perlu lagi dijadikan dasar negara. Sikap Anda ...", "options": [{"key": "A", "text": "Saya mengatakan akan memikirkannya terlebih dahulu agar hubungan bertetangga tetap terjaga baik."}, {"key": "B", "text": "Saya menolak ajakan tersebut dengan sopan dan menjaga jarak dari kenalan itu di kemudian hari."}, {"key": "C", "text": "Saya menolak dengan tegas, menjelaskan kedudukan Pancasila sebagai dasar negara, dan melaporkannya kepada pihak berwenang."}, {"key": "D", "text": "Saya menolak ajakan tersebut dan mengingatkannya bahwa pandangan itu bertentangan dengan Pancasila sebagai dasar negara Indonesia."}, {"key": "E", "text": "Saya ikut menghadiri kajian tersebut sekali untuk mengetahui isi dan kegiatan kelompoknya."}], "correct_answer": null, "scores": {"A": 2, "B": 3, "C": 5, "D": 4, "E": 1}, "explanation": "Soal ini menguji aspek anti radikalisme, khususnya kesetiaan pada Pancasila dan kewaspadaan terhadap paham radikal. Opsi C paling ideal karena pegawai menolak tegas, meluruskan pemahaman, dan menempuh jalur pelaporan resmi, sedangkan opsi E paling rendah karena pegawai membuka diri terhadap paparan paham yang bertentangan dengan dasar negara. Urutan skor: C (5), D (4), B (3), A (2), E (1).", "category": "Anti Radikalisme", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban terbaik adalah opsi D (skor 5). Pengelola akun membalas dengan sopan, meminta detail keluhan, lalu meneruskannya ke unit terkait, sehingga keluhan warga benar-benar ditindaklanjuti meskipun disampaikan dengan kasar.", "concept": "Soal ini menguji aspek pelayanan publik, khususnya penanganan keluhan masyarakat. ASN yang ideal tetap santun, tidak defensif, dan memastikan setiap keluhan diproses sampai ada tindak lanjut.", "steps": ["Pengendalian emosi: tetap sopan meskipun keluhan disampaikan dengan kasar.", "Menggali informasi: meminta detail agar keluhan dapat ditangani secara tepat.", "Tindak lanjut: meneruskan keluhan ke unit yang berwenang hingga ditangani."], "options": {"A": "Skor 1: Membalas secara defensif dan meminta warga bersabar tidak menyelesaikan masalah yang dikeluhkan.", "B": "Skor 4: Membalas sopan dan mengarahkan ke kanal pengaduan resmi sudah tepat, tetapi warga dibebani untuk mengadu ulang.", "C": "Skor 2: Menyembunyikan komentar menghindari keluhan tanpa menindaklanjuti substansinya.", "D": "Skor 5: Membalas sopan, menggali detail keluhan, dan meneruskannya ke unit terkait memastikan keluhan ditangani secara tuntas.", "E": "Skor 3: Melapor kepada atasan menunjukkan kehati-hatian, tetapi menunda respons kepada warga."}, "tips": "Skor 5 berarti petugas sendiri yang memastikan keluhan diteruskan dan ditindaklanjuti, sedangkan skor 4 hanya mengarahkan warga ke kanal lain.", "reference": "Nilai dasar ASN BerAKHLAK: Berorientasi Pelayanan", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 74, "question_text": "Anda mengelola akun media sosial resmi instansi. Seorang warga menulis komentar bernada kasar yang mengeluhkan lambatnya proses layanan di kantor Anda. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya membalas dengan menegaskan bahwa petugas sudah bekerja keras dan warga perlu lebih bersabar."}, {"key": "B", "text": "Saya membalas dengan sopan dan mengarahkan warga tersebut untuk menyampaikan keluhan melalui kanal pengaduan resmi."}, {"key": "C", "text": "Saya menyembunyikan komentar tersebut karena mengandung kata-kata kasar yang tidak pantas dibaca publik."}, {"key": "D", "text": "Saya membalas dengan sopan, meminta detail keluhannya, lalu meneruskannya ke unit terkait untuk ditindaklanjuti."}, {"key": "E", "text": "Saya meneruskan keluhan tersebut kepada atasan dan menunggu arahan sebelum memberikan tanggapan."}], "correct_answer": null, "scores": {"A": 1, "B": 4, "C": 2, "D": 5, "E": 3}, "explanation": "Soal ini menguji aspek pelayanan publik, khususnya penanganan keluhan masyarakat. Opsi D paling ideal karena pegawai merespons secara santun sekaligus memastikan keluhan ditindaklanjuti, sedangkan opsi A paling rendah karena pegawai bersikap defensif dan tidak menyelesaikan masalah yang dikeluhkan. Urutan skor: D (5), B (4), E (3), C (2), A (1).", "category": "Pelayanan Publik", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban terbaik adalah opsi E (skor 5). Menemui langsung penanggung jawab data untuk memahami kendalanya dan menyepakati jadwal yang realistis menyelesaikan akar keterlambatan sekaligus menjaga hubungan baik antarunit.", "concept": "Soal ini menguji aspek jejaring kerja, khususnya koordinasi antarunit. ASN yang ideal membangun komunikasi langsung, memahami kendala mitra, dan menghasilkan kesepakatan kerja yang realistis.", "steps": ["Komunikasi langsung: temui pihak terkait untuk memahami kendala sebenarnya.", "Kesepakatan bersama: jadwal yang realistis lebih mungkin dipatuhi oleh kedua pihak.", "Menjaga hubungan kerja: hindari sikap menyalahkan yang merusak kerja sama."], "options": {"A": "Skor 1: Menunggu dan menganggapnya bukan tanggung jawab sendiri adalah sikap pasif yang menghambat pekerjaan bersama.", "B": "Skor 4: Pengingat resmi dengan tenggat dan tembusan ke atasan efektif dan tertib, tetapi kurang menyentuh kendala yang dihadapi mitra.", "C": "Skor 2: Melaporkan keterlambatan sebagai kesalahan unit lain cenderung menyalahkan dan merusak hubungan kerja.", "D": "Skor 3: Mengerjakan bagian yang sudah tersedia itu produktif, tetapi tidak menyelesaikan penyebab keterlambatan data.", "E": "Skor 5: Menemui penanggung jawab data untuk memahami kendala dan menyepakati jadwal adalah koordinasi yang paling konstruktif."}, "tips": "Skor 5 menekankan dialog langsung dan kesepakatan bersama, sedangkan skor 4 cenderung memakai jalur formal atau tekanan administratif.", "reference": "Nilai dasar ASN BerAKHLAK: Kolaboratif", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 75, "question_text": "Unit Anda dan unit lain ditugaskan menyusun laporan gabungan. Unit tersebut terus terlambat mengirimkan data sehingga pekerjaan Anda ikut tertunda. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya menunggu saja hingga data dikirimkan karena keterlambatan itu bukan tanggung jawab saya."}, {"key": "B", "text": "Saya mengirimkan pengingat resmi disertai tenggat yang jelas dan menembuskannya kepada atasan kedua unit."}, {"key": "C", "text": "Saya melaporkan kepada atasan bahwa keterlambatan pekerjaan ini sepenuhnya disebabkan oleh unit lain."}, {"key": "D", "text": "Saya mengerjakan bagian yang datanya sudah tersedia lebih dahulu sambil menunggu data dari unit tersebut dikirimkan."}, {"key": "E", "text": "Saya menemui penanggung jawab data di unit itu untuk memahami kendalanya dan menyepakati jadwal yang realistis."}], "correct_answer": null, "scores": {"A": 1, "B": 4, "C": 2, "D": 3, "E": 5}, "explanation": "Soal ini menguji aspek jejaring kerja, khususnya koordinasi antarunit. Opsi E paling ideal karena komunikasi langsung untuk memahami kendala dan membuat kesepakatan memperkuat kerja sama, sedangkan opsi A paling rendah karena sikap pasif dan lepas tangan membuat pekerjaan bersama terhambat. Urutan skor: E (5), B (4), D (3), C (2), A (1).", "category": "Jejaring Kerja", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban terbaik adalah opsi B (skor 5). Pegawai menghormati perayaan keagamaan rekannya dan mewujudkannya dalam bantuan nyata dengan menawarkan diri menyelesaikan tugas rekan selama cuti.", "concept": "Soal ini menguji aspek sosial budaya, khususnya toleransi antarumat beragama di lingkungan kerja. ASN yang ideal menghormati keyakinan orang lain dan menunjukkan sikap saling mendukung dalam keberagaman.", "steps": ["Penghormatan: menghargai hak rekan menjalankan perayaan keagamaannya.", "Toleransi aktif: mewujudkan sikap saling menghargai dalam tindakan nyata.", "Kepedulian tim: memastikan pekerjaan tetap berjalan selama rekan cuti."], "options": {"A": "Skor 4: Mengucapkan selamat dan menjaga suasana kantor menunjukkan toleransi yang baik, tetapi belum dalam bentuk bantuan nyata.", "B": "Skor 5: Menghormati perayaan sekaligus menawarkan bantuan atas tugasnya merupakan toleransi yang diwujudkan secara aktif.", "C": "Skor 1: Keberatan menerima limpahan pekerjaan menunjukkan sikap tidak saling mendukung dalam keberagaman.", "D": "Skor 2: Menghindari pembicaraan tentang perayaan terkesan menjaga jarak dan kurang menunjukkan penghargaan.", "E": "Skor 3: Bersikap biasa saja tidak salah, tetapi netral tanpa ekspresi penghargaan atau kepedulian."}, "tips": "Bedakan toleransi pasif atau simbolik (skor 3–4) dengan toleransi aktif yang disertai tindakan nyata membantu (skor 5).", "reference": "Nilai dasar ASN BerAKHLAK: Harmonis", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 76, "question_text": "Rekan kerja Anda yang berbeda agama sedang merayakan hari besar keagamaannya dan mengambil cuti beberapa hari. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menyampaikan ucapan selamat dan ikut menjaga suasana kantor tetap nyaman selama perayaan berlangsung."}, {"key": "B", "text": "Saya menghormati perayaannya dan menawarkan diri membantu menyelesaikan tugasnya selama ia cuti."}, {"key": "C", "text": "Saya keberatan apabila pekerjaan rekan tersebut harus dibagikan kepada saya selama ia cuti."}, {"key": "D", "text": "Saya menghindari pembicaraan tentang perayaan tersebut agar tidak terjadi salah paham di kantor."}, {"key": "E", "text": "Saya bersikap biasa saja dan tetap menjalankan pekerjaan seperti hari-hari sebelumnya."}], "correct_answer": null, "scores": {"A": 4, "B": 5, "C": 1, "D": 2, "E": 3}, "explanation": "Soal ini menguji aspek sosial budaya, khususnya toleransi antarumat beragama di lingkungan kerja. Opsi B paling ideal karena pegawai menghormati perbedaan sekaligus mewujudkannya dalam bentuk bantuan nyata, sedangkan opsi C paling rendah karena pegawai tidak menunjukkan sikap saling mendukung dalam keberagaman. Urutan skor: B (5), A (4), E (3), D (2), C (1).", "category": "Sosial Budaya", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban terbaik adalah opsi A (skor 5). Pegawai menjaga kerahasiaan kata sandi sekaligus membantu rekannya menghubungi admin agar akun segera dipulihkan, sehingga keamanan akun terjaga dan kebutuhan rekan tetap terpenuhi melalui jalur yang benar.", "concept": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya keamanan akun dan kerahasiaan kata sandi. ASN yang ideal tidak pernah membagikan kredensial pribadi, tetapi tetap membantu menyelesaikan masalah melalui prosedur resmi.", "steps": ["Kerahasiaan kredensial: kata sandi bersifat pribadi dan tidak boleh dibagikan kepada siapa pun.", "Solusi melalui jalur resmi: pemulihan akun dilakukan oleh admin aplikasi.", "Kepedulian: tetap membantu rekan agar urusannya tidak terhambat."], "options": {"A": "Skor 5: Menolak memberi kata sandi sambil membantu menghubungi admin menjaga keamanan dan tetap menyelesaikan masalah rekan.", "B": "Skor 2: Memberikan kata sandi meskipun akan segera diganti tetap membuka celah penyalahgunaan akun.", "C": "Skor 3: Mengunggahkan dokumen lewat akun sendiri tidak membocorkan kata sandi, tetapi mencampuradukkan identitas akun dan bukan solusi resmi.", "D": "Skor 4: Menolak sambil menjelaskan kerahasiaan akun sudah tepat, tetapi belum membantu rekan menyelesaikan masalahnya.", "E": "Skor 1: Memberikan kata sandi karena rasa percaya adalah pelanggaran keamanan yang paling berisiko."}, "tips": "Pada soal kredensial, skor 5 menolak membagikan akses sekaligus menawarkan solusi resmi, sedangkan skor 4 hanya menolak tanpa membantu.", "reference": "Nilai dasar ASN BerAKHLAK: Akuntabel", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 77, "question_text": "Akun aplikasi kepegawaian milik rekan Anda terkunci, padahal ia harus segera mengunggah dokumen. Ia meminta kata sandi akun Anda agar dapat mengunggah dokumen tersebut. Sikap Anda ...", "options": [{"key": "A", "text": "Saya tidak memberikan kata sandi, lalu membantunya menghubungi admin aplikasi agar akunnya segera dipulihkan."}, {"key": "B", "text": "Saya memberikan kata sandi dengan syarat hanya dipakai sekali, lalu saya segera menggantinya setelah itu."}, {"key": "C", "text": "Saya menawarkan diri mengunggahkan dokumennya melalui akun saya dengan disaksikan langsung oleh rekan tersebut."}, {"key": "D", "text": "Saya menolak memberikan kata sandi dan menjelaskan bahwa akun bersifat pribadi serta wajib dijaga kerahasiaannya."}, {"key": "E", "text": "Saya memberikan kata sandi karena ia rekan dekat yang dapat dipercaya dan sedang membutuhkan bantuan."}], "correct_answer": null, "scores": {"A": 5, "B": 2, "C": 3, "D": 4, "E": 1}, "explanation": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya keamanan akun dan kerahasiaan kata sandi. Opsi A paling ideal karena pegawai menjaga keamanan akun sekaligus membantu rekan melalui jalur yang benar, sedangkan opsi E paling rendah karena pegawai membagikan kredensial pribadi yang membuka celah penyalahgunaan data. Urutan skor: A (5), D (4), C (3), B (2), E (1).", "category": "Teknologi Informasi dan Komunikasi", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban terbaik adalah opsi D (skor 5). Pegawai menerima tugas di luar keahliannya, mempelajari hal yang dibutuhkan, dan berkonsultasi dengan pihak yang lebih memahami, sehingga tugas dapat diselesaikan dengan baik sekaligus meningkatkan kompetensinya.", "concept": "Soal ini menguji aspek profesionalisme, khususnya kemauan belajar dan tanggung jawab terhadap tugas. ASN yang ideal siap menerima tantangan baru dan aktif meningkatkan kompetensi agar dapat memberikan hasil terbaik.", "steps": ["Tanggung jawab: menerima penugasan organisasi tanpa berdalih latar belakang pendidikan.", "Pengembangan diri: mempelajari pengetahuan yang dibutuhkan secara mandiri.", "Konsultasi: memanfaatkan pihak yang lebih ahli agar hasil kerja berkualitas."], "options": {"A": "Skor 2: Meminta tugas dikerjakan bersama rekan berpengalaman menunjukkan ketergantungan sebelum mencoba sendiri.", "B": "Skor 1: Menolak tugas karena tidak sesuai latar belakang pendidikan menunjukkan sikap tidak bertanggung jawab terhadap tugas organisasi.", "C": "Skor 4: Menerima tugas dan meminta arahan rinci sudah bertanggung jawab, tetapi belum menunjukkan inisiatif belajar mandiri.", "D": "Skor 5: Menerima tugas sambil belajar dan berkonsultasi menunjukkan tanggung jawab sekaligus komitmen pada peningkatan kompetensi.", "E": "Skor 3: Mengerjakan sebisanya menunjukkan kesediaan, tetapi tanpa upaya meningkatkan kualitas hasil kerja."}, "tips": "Opsi skor 5 menunjukkan inisiatif belajar sendiri ditambah konsultasi, sedangkan skor 4 lebih mengandalkan arahan dari atasan.", "reference": "Nilai dasar ASN BerAKHLAK: Kompeten", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 78, "question_text": "Atasan memberikan tugas kepada Anda yang berada di luar bidang keahlian dan latar belakang pendidikan Anda. Sikap Anda ...", "options": [{"key": "A", "text": "Saya meminta atasan agar tugas tersebut dikerjakan bersama rekan yang lebih berpengalaman."}, {"key": "B", "text": "Saya menolak tugas tersebut karena tidak sesuai dengan latar belakang pendidikan saya."}, {"key": "C", "text": "Saya menerima tugas tersebut dan meminta atasan memberikan arahan yang lebih rinci tentang hasil yang diharapkan."}, {"key": "D", "text": "Saya menerima tugas itu, mempelajari hal-hal yang dibutuhkan, dan berkonsultasi dengan pihak yang lebih memahami."}, {"key": "E", "text": "Saya menerima tugas tersebut dan mengerjakannya sebisa mungkin sesuai kemampuan yang saya miliki."}], "correct_answer": null, "scores": {"A": 2, "B": 1, "C": 4, "D": 5, "E": 3}, "explanation": "Soal ini menguji aspek profesionalisme, khususnya kemauan belajar dan tanggung jawab terhadap tugas. Opsi D paling ideal karena pegawai menerima tantangan disertai upaya belajar dan konsultasi, sedangkan opsi B paling rendah karena pegawai menolak tugas organisasi dengan alasan pribadi. Urutan skor: D (5), C (4), E (3), A (2), B (1).", "category": "Profesionalisme", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban terbaik adalah opsi C (skor 5). Pegawai memeriksa kebenaran video melalui sumber resmi, membagikan klarifikasi, dan melaporkan akun penyebar, sehingga provokasi bernuansa agama dapat diredam secara aktif dan melalui jalur yang benar.", "concept": "Soal ini menguji aspek anti radikalisme, khususnya penangkalan provokasi dan hoaks bernuansa SARA. ASN yang ideal tidak ikut menyebarkan, aktif meluruskan informasi, dan melapor agar konflik antarkelompok tidak tersulut.", "steps": ["Verifikasi: cek kebenaran informasi melalui sumber resmi.", "Klarifikasi: sebarkan informasi yang benar untuk meredam provokasi.", "Pelaporan: laporkan akun penyebar melalui kanal aduan agar ditindak."], "options": {"A": "Skor 2: Bertanya di kolom komentar justru menambah interaksi pada unggahan provokatif dan tidak meredam penyebarannya.", "B": "Skor 1: Membagikan video ke grup keluarga ikut memperluas penyebaran hoaks yang dapat memicu konflik.", "C": "Skor 5: Memverifikasi, membagikan klarifikasi, dan melaporkan akun adalah langkah aktif yang paling lengkap untuk menangkal hoaks.", "D": "Skor 4: Melaporkan unggahan ke platform sudah tepat, tetapi belum disertai klarifikasi kepada masyarakat yang telanjur terpapar.", "E": "Skor 3: Tidak membagikan sudah benar, tetapi menunggu klarifikasi resmi bersifat pasif."}, "tips": "Skor 5 pada soal hoaks memadukan verifikasi, klarifikasi, dan pelaporan; skor 4 umumnya hanya salah satu langkah aktif, misalnya melapor saja.", "reference": "Nilai dasar ASN BerAKHLAK: Loyal, sejalan dengan kewajiban ASN setia dan taat kepada Pancasila, UUD 1945, NKRI, dan pemerintah yang sah", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 79, "question_text": "Sebuah akun anonim menyebarkan video lama yang telah disunting seolah-olah baru saja terjadi bentrokan antarkelompok agama di daerah Anda. Video itu mulai ramai dibagikan. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya menanyakan kebenaran video tersebut di kolom komentar agar pengunggah memberikan penjelasan."}, {"key": "B", "text": "Saya membagikan video tersebut ke grup keluarga agar mereka berhati-hati ketika bepergian."}, {"key": "C", "text": "Saya memeriksa kebenarannya melalui sumber resmi, membagikan klarifikasi, dan melaporkan akun tersebut ke kanal aduan."}, {"key": "D", "text": "Saya melaporkan unggahan tersebut kepada platform media sosial sebagai konten yang menyesatkan dan provokatif."}, {"key": "E", "text": "Saya tidak membagikan video tersebut dan memilih menunggu adanya klarifikasi resmi dari aparat atau pemerintah setempat."}], "correct_answer": null, "scores": {"A": 2, "B": 1, "C": 5, "D": 4, "E": 3}, "explanation": "Soal ini menguji aspek anti radikalisme, khususnya penangkalan provokasi dan hoaks bernuansa SARA. Opsi C paling ideal karena pegawai aktif memverifikasi, meluruskan informasi, dan melapor melalui jalur resmi, sedangkan opsi B paling rendah karena pegawai ikut memperluas penyebaran hoaks yang dapat memicu konflik. Urutan skor: C (5), D (4), E (3), A (2), B (1).", "category": "Anti Radikalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban terbaik adalah opsi B (skor 5). Pegawai menjelaskan dengan sopan bahwa semua permohonan diproses sesuai urutan dan standar, lalu tetap membantu memeriksa kelengkapan berkas, sehingga asas keadilan terjaga tanpa mengurangi kualitas pelayanan.", "concept": "Soal ini menguji aspek pelayanan publik, khususnya keadilan dan nondiskriminasi dalam pelayanan. ASN yang ideal memberikan perlakuan setara kepada semua pemohon dan menolak intervensi berdasarkan kedekatan dengan pejabat.", "steps": ["Keadilan: semua pemohon dilayani sesuai urutan dan standar yang sama.", "Ketegasan yang santun: menolak permintaan istimewa dengan penjelasan yang sopan.", "Tetap melayani: membantu kelancaran berkas pemohon sesuai prosedur."], "options": {"A": "Skor 3: Memproses sesuai antrean sudah adil, tetapi tanpa penjelasan sehingga pemohon tidak memahami prinsip kesetaraan layanan.", "B": "Skor 5: Menjelaskan kesetaraan layanan dengan sopan sambil memeriksa kelengkapan berkas menunjukkan ketegasan dan pelayanan yang baik sekaligus.", "C": "Skor 2: Meminta pemohon menghubungi pejabat membuka peluang intervensi dan melemahkan prosedur.", "D": "Skor 4: Menjelaskan kesetaraan layanan dan menunjukkan cara memantau status sudah baik, tetapi belum langsung membantu pemeriksaan berkas.", "E": "Skor 1: Mendahulukan karena kedekatan dengan pejabat adalah perlakuan istimewa yang melanggar asas keadilan."}, "tips": "Skor 5 menegakkan aturan sekaligus memberi bantuan konkret atas berkas pemohon; skor 4 menegakkan aturan dengan bantuan yang lebih umum.", "reference": "Nilai dasar ASN BerAKHLAK: Berorientasi Pelayanan", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 80, "question_text": "Anda petugas layanan perizinan. Seorang pelaku usaha meminta permohonannya didahulukan dengan menyebut bahwa ia mengenal baik salah satu pejabat di instansi Anda. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menerima permohonannya dan memprosesnya sesuai antrean tanpa menanggapi pernyataan tentang kedekatannya dengan pejabat."}, {"key": "B", "text": "Saya menjelaskan dengan sopan bahwa semua permohonan diproses sesuai urutan dan standar, lalu memeriksa kelengkapan berkasnya."}, {"key": "C", "text": "Saya meminta pelaku usaha tersebut menghubungi pejabat yang dikenalnya agar memberikan arahan langsung kepada saya."}, {"key": "D", "text": "Saya menjelaskan bahwa layanan diberikan setara kepada semua pemohon dan menunjukkan cara memantau status permohonan secara daring."}, {"key": "E", "text": "Saya mendahulukan permohonannya agar tidak menimbulkan masalah dengan pejabat yang dikenalnya."}], "correct_answer": null, "scores": {"A": 3, "B": 5, "C": 2, "D": 4, "E": 1}, "explanation": "Soal ini menguji aspek pelayanan publik, khususnya keadilan dan nondiskriminasi dalam pelayanan. Opsi B paling ideal karena pegawai tegas menjaga kesetaraan layanan sambil tetap membantu kelancaran berkas pemohon, sedangkan opsi E paling rendah karena pegawai memberi perlakuan istimewa yang melanggar asas keadilan pelayanan publik. Urutan skor: B (5), D (4), A (3), C (2), E (1).", "category": "Pelayanan Publik", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban terbaik adalah opsi E (skor 5). Pegawai memfasilitasi diskusi agar setiap pihak menyampaikan gagasannya, lalu bersama merumuskan konsep yang disepakati, sehingga semua pemangku kepentingan merasa dilibatkan dan dihargai.", "concept": "Soal ini menguji aspek jejaring kerja, khususnya kolaborasi dengan berbagai pemangku kepentingan. ASN yang ideal mampu menjembatani perbedaan, mengakomodasi gagasan semua pihak, dan mengarahkan pada kesepakatan bersama.", "steps": ["Inklusivitas: beri ruang yang setara bagi setiap pihak untuk menyampaikan gagasan.", "Fasilitasi: arahkan diskusi agar tetap fokus pada tujuan acara.", "Kesepakatan bersama: keputusan dirumuskan bersama, bukan dipaksakan oleh satu pihak."], "options": {"A": "Skor 1: Mempertahankan konsep sendiri berarti memaksakan pendapat dan mengabaikan mitra kerja.", "B": "Skor 2: Mendukung pihak penyandang dana terbesar tidak adil bagi mitra lain dan mengabaikan aspirasi mereka.", "C": "Skor 4: Mengusulkan musyawarah dengan mempertimbangkan anggaran dan waktu sudah tepat, tetapi belum berperan aktif memfasilitasi gagasan setiap pihak.", "D": "Skor 3: Menyerahkan keputusan kepada ketua panitia tidak salah, tetapi pasif dalam menjembatani perbedaan.", "E": "Skor 5: Memfasilitasi diskusi dan merumuskan konsep bersama mengakomodasi semua pihak dan memperkuat kolaborasi."}, "tips": "Skor 5 berperan aktif sebagai fasilitator yang menghimpun gagasan semua pihak; skor 4 baru mengusulkan mekanisme musyawarah.", "reference": "Nilai dasar ASN BerAKHLAK: Kolaboratif", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 81, "question_text": "Anda menjadi panitia kegiatan bersama yang melibatkan karang taruna, tokoh masyarakat, dan perwakilan perusahaan swasta. Terjadi perbedaan pendapat tentang konsep acara. Sikap Anda ...", "options": [{"key": "A", "text": "Saya mempertahankan konsep usulan saya karena saya merasa paling memahami kebutuhan acara tersebut."}, {"key": "B", "text": "Saya mendukung usulan perusahaan swasta karena merekalah yang memberikan dana terbesar untuk acara."}, {"key": "C", "text": "Saya mengusulkan agar keputusan diambil melalui musyawarah dengan mempertimbangkan anggaran dan waktu yang tersedia."}, {"key": "D", "text": "Saya menyerahkan keputusan kepada ketua panitia karena ia yang paling bertanggung jawab atas acara."}, {"key": "E", "text": "Saya memfasilitasi diskusi agar tiap pihak menyampaikan gagasannya, lalu bersama merumuskan konsep yang disepakati."}], "correct_answer": null, "scores": {"A": 1, "B": 2, "C": 4, "D": 3, "E": 5}, "explanation": "Soal ini menguji aspek jejaring kerja, khususnya kolaborasi dengan berbagai pemangku kepentingan. Opsi E paling ideal karena pegawai mengakomodasi semua pihak dan mengarahkan diskusi pada tujuan bersama, sedangkan opsi A paling rendah karena pegawai memaksakan pendapat sendiri dan mengabaikan mitra kerja. Urutan skor: E (5), C (4), D (3), B (2), A (1).", "category": "Jejaring Kerja", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban terbaik adalah opsi C (skor 5). Pegawai mengajak keluarga pendatang terlibat dalam kegiatan lingkungan dan membantu warga lain saling mengenal, sehingga ia tidak hanya bersikap ramah tetapi juga menjembatani kerukunan di lingkungannya.", "concept": "Soal ini menguji aspek sosial budaya, khususnya kemampuan merekatkan masyarakat yang beragam. ASN yang ideal menjadi perekat sosial dengan merangkul perbedaan dan mendorong interaksi yang harmonis.", "steps": ["Penerimaan: menyambut warga pendatang tanpa memandang perbedaan bahasa dan kebiasaan.", "Peran perekat: menjembatani interaksi antara pendatang dan warga lama.", "Pelibatan: mengajak terlibat dalam kegiatan bersama agar terjalin kebersamaan."], "options": {"A": "Skor 2: Menunggu pendatang menyesuaikan diri menempatkan beban adaptasi sepenuhnya pada mereka.", "B": "Skor 3: Bersikap ramah saat berpapasan itu baik, tetapi tidak berupaya membangun kedekatan.", "C": "Skor 5: Mengajak pendatang terlibat dan membantu warga saling mengenal menjadikan pegawai perekat kerukunan lingkungan.", "D": "Skor 1: Ikut menjaga jarak berarti turut mengucilkan warga hanya karena perbedaan latar belakang.", "E": "Skor 4: Menyapa dan menawarkan bantuan menunjukkan penerimaan yang baik, tetapi belum menjembatani hubungan dengan warga lain."}, "tips": "Skor 5 tidak hanya menerima perbedaan secara pribadi, tetapi juga menjembatani hubungan antarkelompok di lingkungan.", "reference": "Nilai dasar ASN BerAKHLAK: Harmonis", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 82, "question_text": "Di lingkungan tempat tinggal Anda, ada keluarga pendatang dari luar daerah dengan bahasa dan kebiasaan yang berbeda. Sebagian warga cenderung menjauhi keluarga tersebut. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menunggu keluarga pendatang tersebut menyesuaikan diri terlebih dahulu dengan kebiasaan lingkungan kami."}, {"key": "B", "text": "Saya bersikap ramah kepada mereka ketika berpapasan tanpa perlu terlibat terlalu jauh."}, {"key": "C", "text": "Saya mengajak keluarga tersebut terlibat dalam kegiatan lingkungan dan membantu warga lain untuk saling mengenal."}, {"key": "D", "text": "Saya ikut menjaga jarak karena khawatir kebiasaan mereka akan memengaruhi lingkungan kami."}, {"key": "E", "text": "Saya menyapa dan berkenalan dengan keluarga pendatang tersebut serta menawarkan bantuan bila mereka membutuhkan."}], "correct_answer": null, "scores": {"A": 2, "B": 3, "C": 5, "D": 1, "E": 4}, "explanation": "Soal ini menguji aspek sosial budaya, khususnya kemampuan merekatkan masyarakat yang beragam. Opsi C paling ideal karena pegawai menjembatani interaksi sehingga tercipta kerukunan di lingkungan, sedangkan opsi D paling rendah karena pegawai ikut mengucilkan warga hanya karena perbedaan latar belakang. Urutan skor: C (5), E (4), B (3), A (2), D (1).", "category": "Sosial Budaya", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban terbaik adalah opsi D (skor 5). Pegawai menolak menyimpan passphrase karena bersifat pribadi, lalu membantu atasan menandatangani dokumen dari jarak jauh melalui aplikasi, sehingga keamanan identitas elektronik terjaga dan layanan tidak terhambat.", "concept": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya keamanan dan pemanfaatan tanda tangan elektronik. ASN yang ideal menjaga kerahasiaan identitas elektronik dan memanfaatkan teknologi untuk menjaga kelancaran pekerjaan.", "steps": ["Kerahasiaan identitas elektronik: passphrase hanya boleh digunakan oleh pemiliknya.", "Solusi teknologi: memanfaatkan fitur tanda tangan jarak jauh agar dokumen tetap dapat diproses.", "Kesantunan: menolak dengan sopan sambil tetap membantu atasan."], "options": {"A": "Skor 1: Menerima passphrase dan menandatangani tanpa konfirmasi adalah penyalahgunaan identitas elektronik atasan tanpa kewenangan.", "B": "Skor 3: Menyiapkan dokumen agar mudah ditandatangani itu membantu, tetapi tidak menjawab persoalan saat atasan berada di luar kantor.", "C": "Skor 4: Menjelaskan risiko dan mengusulkan pelimpahan wewenang sesuai ketentuan sudah tepat, tetapi belum memberi solusi yang langsung dapat dijalankan.", "D": "Skor 5: Menolak dengan sopan sambil membantu penandatanganan jarak jauh menjaga keamanan dan kelancaran layanan sekaligus.", "E": "Skor 2: Menerima passphrase meskipun hanya untuk dokumen yang disetujui tetap melanggar prinsip kerahasiaan identitas elektronik."}, "tips": "Skor 5 menolak penyerahan kredensial sekaligus memberi solusi teknis yang langsung dapat dipakai; skor 4 masih berupa usulan prosedural.", "reference": "Nilai dasar ASN BerAKHLAK: Akuntabel", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 83, "question_text": "Instansi Anda menerapkan tanda tangan elektronik untuk dokumen dinas. Atasan yang sering bertugas ke luar kota meminta Anda menyimpan passphrase tanda tangan elektroniknya agar dokumen tetap dapat ditandatangani saat ia tidak di kantor. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menerima passphrase tersebut dan menandatangani dokumen yang menurut saya sudah layak tanpa konfirmasi."}, {"key": "B", "text": "Saya menyiapkan seluruh dokumen yang perlu ditandatangani sehingga atasan cukup membubuhkan tanda tangan ketika sempat."}, {"key": "C", "text": "Saya menjelaskan risiko keamanan apabila passphrase dipakai orang lain dan mengusulkan mekanisme pelimpahan wewenang sesuai ketentuan."}, {"key": "D", "text": "Saya menolak dengan sopan karena passphrase bersifat pribadi, lalu membantu atasan menandatangani dari jarak jauh melalui aplikasi."}, {"key": "E", "text": "Saya menerima passphrase tersebut, tetapi hanya menggunakannya untuk dokumen yang sudah disetujui atasan."}], "correct_answer": null, "scores": {"A": 1, "B": 3, "C": 4, "D": 5, "E": 2}, "explanation": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya keamanan dan pemanfaatan tanda tangan elektronik. Opsi D paling ideal karena pegawai menjaga kerahasiaan passphrase sekaligus memberi solusi teknis agar layanan tidak terhambat, sedangkan opsi A paling rendah karena pegawai menyalahgunakan identitas elektronik atasan tanpa kewenangan. Urutan skor: D (5), C (4), B (3), E (2), A (1).", "category": "Teknologi Informasi dan Komunikasi", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban terbaik adalah opsi C (skor 5). Pegawai menolak titip presensi, mengisi presensi sesuai kehadiran sebenarnya, dan mengingatkan rekan bahwa praktik tersebut melanggar disiplin, sehingga ia jujur dan turut menegakkan disiplin di lingkungan kerja.", "concept": "Soal ini menguji aspek profesionalisme, khususnya integritas dan disiplin pegawai. ASN yang ideal jujur dalam mencatat kehadiran, taat aturan disiplin, dan berani mengingatkan rekan yang keliru.", "steps": ["Kejujuran: presensi harus mencerminkan kehadiran yang sebenarnya.", "Kepatuhan disiplin: menolak praktik titip presensi meskipun dianggap lazim.", "Menegakkan budaya kerja: mengingatkan rekan secara baik agar pelanggaran tidak berulang."], "options": {"A": "Skor 1: Menerima tawaran karena dianggap kebiasaan berarti menormalisasi pelanggaran disiplin.", "B": "Skor 3: Menolak dan bergegas datang sudah jujur, tetapi tidak mengingatkan rekan maupun berkomunikasi dengan atasan.", "C": "Skor 5: Menolak, mencatat kehadiran sebenarnya, dan mengingatkan rekan menunjukkan integritas sekaligus turut menegakkan disiplin.", "D": "Skor 2: Menerima tawaran dengan alasan mendesak tetap merupakan pelanggaran disiplin.", "E": "Skor 4: Menolak dan melapor kepada atasan menunjukkan kejujuran dan tanggung jawab, tetapi tidak mengingatkan rekan tentang pelanggaran tersebut."}, "tips": "Skor 5 jujur bagi diri sendiri sekaligus mencegah pelanggaran di lingkungannya; skor 4 hanya jujur dan transparan bagi diri sendiri.", "reference": "Nilai dasar ASN BerAKHLAK: Akuntabel", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 84, "question_text": "Seorang rekan menawarkan diri untuk menitipkan presensi Anda pada pagi hari ketika Anda mengabarkan akan terlambat datang ke kantor. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menerima tawaran tersebut karena hal serupa sudah biasa dilakukan oleh rekan-rekan lain."}, {"key": "B", "text": "Saya menolak tawaran tersebut dan berusaha tiba di kantor secepat mungkin agar tidak terlalu lama terlambat."}, {"key": "C", "text": "Saya menolak, mengisi presensi sesuai kehadiran sebenarnya, dan mengingatkan rekan bahwa praktik itu melanggar disiplin."}, {"key": "D", "text": "Saya menerima tawaran tersebut kali ini saja karena keterlambatan saya disebabkan hal mendesak."}, {"key": "E", "text": "Saya menolak tawaran tersebut dan memberitahukan keterlambatan saya beserta alasannya kepada atasan secara langsung melalui telepon."}], "correct_answer": null, "scores": {"A": 1, "B": 3, "C": 5, "D": 2, "E": 4}, "explanation": "Soal ini menguji aspek profesionalisme, khususnya integritas dan disiplin pegawai. Opsi C paling ideal karena pegawai jujur, taat aturan, dan turut menegakkan disiplin di lingkungan kerja, sedangkan opsi A paling rendah karena pegawai menormalisasi pelanggaran disiplin dengan alasan kebiasaan. Urutan skor: C (5), E (4), B (3), D (2), A (1).", "category": "Profesionalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban terbaik adalah opsi A (skor 5). Pegawai mengajak rekannya berdiskusi secara pribadi tentang nilai Pancasila, lalu melapor kepada atasan bila penyebaran berlanjut, sehingga pendekatan persuasif didahulukan dan jalur resmi tetap disiapkan.", "concept": "Soal ini menguji aspek anti radikalisme, khususnya kesetiaan ASN pada Pancasila dan penanganan paham anti-demokrasi. ASN yang ideal tidak membiarkan paham yang bertentangan dengan dasar negara, mengedepankan dialog, dan menempuh jalur resmi bila diperlukan.", "steps": ["Tidak membiarkan: penyebaran paham yang bertentangan dengan dasar negara harus ditanggapi.", "Pendekatan persuasif: diskusi pribadi menjaga martabat rekan dan lebih efektif mengubah pandangan.", "Jalur resmi berjenjang: melapor kepada atasan apabila upaya persuasif tidak berhasil."], "options": {"A": "Skor 5: Dialog pribadi tentang nilai Pancasila yang dilanjutkan pelaporan bila perlu adalah penanganan persuasif sekaligus tegas.", "B": "Skor 1: Membiarkan dengan dalih kebebasan berpendapat sama dengan membiarkan paham anti-Pancasila menyebar.", "C": "Skor 3: Mengingatkan langsung di grup sudah tegas, tetapi berpotensi mempermalukan rekan dan memicu perdebatan terbuka.", "D": "Skor 4: Melapor kepada atasan sesuai ketentuan disiplin sudah tepat jalur, tetapi melewatkan upaya persuasif terlebih dahulu.", "E": "Skor 2: Meminta admin menghapus unggahan hanya menyentuh aspek relevansi grup, bukan bahaya paham yang disebarkan."}, "tips": "Skor 5 mendahulukan dialog persuasif lalu melapor bila perlu, sedangkan skor 4 langsung melapor tanpa pendekatan pribadi.", "reference": "Nilai dasar ASN BerAKHLAK: Loyal, sejalan dengan kewajiban ASN setia dan taat kepada Pancasila, UUD 1945, NKRI, dan pemerintah yang sah", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 85, "question_text": "Seorang rekan kerja sering membagikan materi di grup percakapan kantor yang menyatakan bahwa sistem demokrasi bertentangan dengan keyakinan sehingga perlu diganti. Sikap Anda ...", "options": [{"key": "A", "text": "Saya mengajaknya berdiskusi secara pribadi tentang nilai Pancasila, lalu melapor kepada atasan bila ia terus menyebarkannya."}, {"key": "B", "text": "Saya membiarkannya karena setiap orang memiliki kebebasan berpendapat di media sosial."}, {"key": "C", "text": "Saya menanggapi unggahan tersebut langsung di grup dengan mengingatkan bahwa setiap ASN wajib setia kepada Pancasila dan UUD 1945."}, {"key": "D", "text": "Saya melaporkan unggahan tersebut kepada atasan agar ditindaklanjuti sesuai ketentuan disiplin ASN yang berlaku."}, {"key": "E", "text": "Saya meminta admin grup menghapus unggahan yang tidak berkaitan dengan urusan pekerjaan kantor."}], "correct_answer": null, "scores": {"A": 5, "B": 1, "C": 3, "D": 4, "E": 2}, "explanation": "Soal ini menguji aspek anti radikalisme, khususnya kesetiaan ASN pada Pancasila dan penanganan paham anti-demokrasi. Opsi A paling ideal karena pegawai mengedepankan dialog persuasif lebih dahulu lalu menempuh jalur resmi bila diperlukan, sedangkan opsi B paling rendah karena pegawai membiarkan penyebaran paham yang bertentangan dengan dasar negara. Urutan skor: A (5), D (4), C (3), E (2), B (1).", "category": "Anti Radikalisme", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban terbaik adalah opsi E (skor 5). Meskipun layanan bukan kewenangan dinasnya, pegawai menjelaskan instansi yang berwenang, persyaratan umumnya, dan kontak yang dapat dihubungi, sehingga warga memperoleh informasi yang tuntas.", "concept": "Soal ini menguji aspek pelayanan publik, khususnya pemberian informasi layanan yang tuntas. ASN yang ideal tetap membantu warga semaksimal mungkin, termasuk mengarahkan dengan jelas ke instansi yang berwenang.", "steps": ["Tidak menolak: warga tetap dibantu meskipun urusannya bukan kewenangan unit sendiri.", "Informasi lengkap: sampaikan instansi yang berwenang, persyaratan, dan kontak layanan.", "Mencegah warga bolak-balik: bekali warga dengan informasi yang cukup sebelum datang ke instansi tujuan."], "options": {"A": "Skor 4: Menunjukkan instansi dan alamatnya sudah membantu, tetapi informasinya belum mencakup persyaratan dan kontak layanan.", "B": "Skor 3: Menyarankan mencari di situs resmi memberi arah, tetapi warga harus mencari sendiri.", "C": "Skor 2: Melempar pertanyaan kepada petugas keamanan menunjukkan kurangnya tanggung jawab sebagai petugas informasi.", "D": "Skor 1: Menyatakan bukan urusan dinas dan tidak dapat membantu membuat warga tidak memperoleh kejelasan.", "E": "Skor 5: Menjelaskan instansi berwenang, persyaratan umum, dan kontak layanan memberikan informasi yang paling tuntas."}, "tips": "Bandingkan kelengkapan informasinya: skor 5 membekali warga dengan instansi, persyaratan, dan kontak, sedangkan skor 4 hanya instansi dan alamat.", "reference": "Nilai dasar ASN BerAKHLAK: Berorientasi Pelayanan", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 86, "question_text": "Anda bertugas di meja informasi sebuah dinas. Seorang warga menanyakan prosedur layanan yang ternyata bukan kewenangan dinas Anda. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menjelaskan bahwa layanan tersebut ditangani oleh instansi lain dan memberitahukan alamat kantor instansi tersebut."}, {"key": "B", "text": "Saya menyarankan warga mencari informasi lengkap melalui situs resmi pemerintah daerah."}, {"key": "C", "text": "Saya meminta warga bertanya kepada petugas keamanan di depan yang biasanya mengetahui alamat instansi lain."}, {"key": "D", "text": "Saya menyampaikan bahwa layanan tersebut bukan urusan dinas kami sehingga saya tidak dapat membantu."}, {"key": "E", "text": "Saya menjelaskan instansi yang berwenang beserta persyaratan umumnya dan memberikan kontak layanan yang dapat dihubungi."}], "correct_answer": null, "scores": {"A": 4, "B": 3, "C": 2, "D": 1, "E": 5}, "explanation": "Soal ini menguji aspek pelayanan publik, khususnya pemberian informasi layanan yang tuntas. Opsi E paling ideal karena pegawai tetap membantu warga secara lengkap meskipun layanan bukan kewenangan dinasnya, sedangkan opsi D paling rendah karena pegawai menolak membantu sehingga warga tidak memperoleh kejelasan informasi. Urutan skor: E (5), A (4), B (3), C (2), D (1).", "category": "Pelayanan Publik", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban terbaik adalah opsi B (skor 5). Pegawai menyusun usulan yang jelas dan mendiskusikannya dengan unit terkait sejak awal, sehingga unit mitra merasa dilibatkan dan inovasi mendapatkan dukungan bersama.", "concept": "Soal ini menguji aspek jejaring kerja, khususnya inisiatif membangun kemitraan antarunit. ASN yang ideal proaktif membangun kerja sama, melibatkan mitra sejak tahap perencanaan, dan tidak mudah menyerah menghadapi kerumitan koordinasi.", "steps": ["Inisiatif: wujudkan gagasan dengan usulan yang konkret dan jelas.", "Pelibatan sejak awal: ajak unit terkait berdiskusi agar merasa memiliki inovasi tersebut.", "Ketekunan: tidak mengurungkan gagasan hanya karena koordinasi dianggap rumit."], "options": {"A": "Skor 4: Mengajukan melalui atasan tetap mendorong kerja sama, tetapi pegawai kurang membangun jejaring secara langsung.", "B": "Skor 5: Menyusun usulan yang jelas dan melibatkan unit terkait sejak awal adalah inisiatif kemitraan yang paling kuat.", "C": "Skor 3: Uji coba di unit sendiri menunjukkan inisiatif, tetapi menunda pelibatan mitra yang justru dibutuhkan.", "D": "Skor 1: Mengurungkan gagasan karena menganggap kerja sama rumit berarti menyerah sebelum mencoba.", "E": "Skor 2: Menunggu program resmi dari pimpinan menunjukkan sikap pasif terhadap peluang inovasi."}, "tips": "Skor 5 membangun kerja sama secara langsung dengan mitra sejak awal; skor 4 menitipkan koordinasi kepada atasan.", "reference": "Nilai dasar ASN BerAKHLAK: Kolaboratif", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 87, "question_text": "Anda memiliki gagasan inovasi layanan yang membutuhkan dukungan data dan sumber daya dari unit kerja lain. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya mengajukan usulan kepada atasan agar beliau yang berkoordinasi dengan pimpinan unit kerja lain."}, {"key": "B", "text": "Saya menyusun usulan yang jelas dan mendiskusikannya dengan unit terkait sejak awal agar mereka ikut terlibat."}, {"key": "C", "text": "Saya menguji coba gagasan tersebut di unit saya terlebih dahulu sebelum mengajak unit kerja lain untuk bergabung."}, {"key": "D", "text": "Saya mengurungkan gagasan tersebut karena kerja sama dengan unit lain biasanya rumit dan lama."}, {"key": "E", "text": "Saya menunggu adanya program resmi dari pimpinan yang memungkinkan gagasan tersebut dijalankan."}], "correct_answer": null, "scores": {"A": 4, "B": 5, "C": 3, "D": 1, "E": 2}, "explanation": "Soal ini menguji aspek jejaring kerja, khususnya inisiatif membangun kemitraan antarunit. Opsi B paling ideal karena pegawai proaktif melibatkan mitra sejak awal sehingga inovasi memiliki dukungan bersama, sedangkan opsi D paling rendah karena pegawai menyerah sebelum mencoba membangun kerja sama. Urutan skor: B (5), A (4), C (3), E (2), D (1).", "category": "Jejaring Kerja", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban terbaik adalah opsi D (skor 5). Sebagai pemimpin tim, pegawai membagi tugas berdasarkan kompetensi dan menjelaskan pentingnya kerja sama lintas latar belakang kepada seluruh tim, sehingga profesionalisme dan persatuan tim terjaga.", "concept": "Soal ini menguji aspek sosial budaya, khususnya pengelolaan tim yang beragam secara inklusif. ASN yang ideal menempatkan kompetensi di atas kesamaan latar belakang dan aktif membina persatuan dalam keberagaman.", "steps": ["Objektivitas: pembagian tugas didasarkan pada kompetensi, bukan suku atau asal daerah.", "Pembinaan menyeluruh: tanamkan nilai kerja sama lintas latar belakang kepada seluruh anggota tim.", "Menolak eksklusivitas: tidak menuruti permintaan yang mendorong pengelompokan berdasarkan suku."], "options": {"A": "Skor 4: Berbicara secara pribadi untuk memahami alasan dan meyakinkan anggota sudah bijak, tetapi belum menetapkan dasar pembagian tugas yang objektif bagi seluruh tim.", "B": "Skor 1: Membiarkan anggota memilih rekan sendiri justru membuka peluang pengelompokan berdasarkan latar belakang.", "C": "Skor 2: Menuruti permintaan walau sementara membenarkan sikap eksklusif dalam tim.", "D": "Skor 5: Membagi tugas berdasarkan kompetensi sambil menanamkan kerja sama lintas latar belakang adalah pengelolaan keberagaman yang paling tepat.", "E": "Skor 3: Pembagian acak mencegah pengelompokan, tetapi mengabaikan kompetensi dan tidak membina pemahaman anggota."}, "tips": "Skor 5 memadukan keputusan objektif berbasis kompetensi dengan pembinaan nilai kebersamaan bagi seluruh tim, sedangkan skor 4 hanya menyasar satu orang.", "reference": "Nilai dasar ASN BerAKHLAK: Harmonis", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 88, "question_text": "Anda memimpin tim yang anggotanya berasal dari berbagai daerah. Saat pembagian tugas, seorang anggota meminta agar ia hanya dipasangkan dengan rekan yang berasal dari suku yang sama. Sikap Anda ...", "options": [{"key": "A", "text": "Saya berbicara secara pribadi dengan anggota tersebut untuk memahami alasannya dan meyakinkannya tentang manfaat tim yang beragam."}, {"key": "B", "text": "Saya membiarkan setiap anggota memilih rekan kerjanya sendiri agar mereka merasa nyaman bekerja."}, {"key": "C", "text": "Saya menuruti permintaannya untuk sementara agar suasana tim tetap kondusif dan pekerjaan dapat berjalan."}, {"key": "D", "text": "Saya membagi tugas berdasarkan kompetensi dan menjelaskan pentingnya kerja sama lintas latar belakang kepada seluruh tim."}, {"key": "E", "text": "Saya menetapkan pembagian tugas secara acak agar tidak terjadi pengelompokan berdasarkan latar belakang tertentu."}], "correct_answer": null, "scores": {"A": 4, "B": 1, "C": 2, "D": 5, "E": 3}, "explanation": "Soal ini menguji aspek sosial budaya, khususnya pengelolaan tim yang beragam secara inklusif. Opsi D paling ideal karena pemimpin menempatkan kompetensi di atas latar belakang sambil membina persatuan tim, sedangkan opsi B paling rendah karena pemimpin membiarkan pengelompokan berdasarkan kesamaan latar belakang. Urutan skor: D (5), A (4), E (3), C (2), B (1).", "category": "Sosial Budaya", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban terbaik adalah opsi E (skor 5). Pegawai mendampingi warga lanjut usia mendaftar sekaligus menyampaikan masukan perbaikan aplikasi kepada pengelola, sehingga warga terbantu saat itu dan hambatan layanan digital dapat diperbaiki ke depannya.", "concept": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya pemanfaatan layanan digital yang inklusif. ASN yang ideal memastikan digitalisasi tidak meninggalkan kelompok rentan dan aktif mendorong perbaikan sistem.", "steps": ["Pendampingan langsung: bantu warga yang kesulitan agar tetap memperoleh layanan.", "Inklusivitas digital: layanan daring harus dapat diakses semua kalangan, termasuk lansia.", "Perbaikan berkelanjutan: sampaikan masukan kepada pengelola agar masalah tidak terulang."], "options": {"A": "Skor 2: Menyarankan bantuan keluarga mengalihkan tanggung jawab layanan kepada pihak lain.", "B": "Skor 3: Membuat panduan cetak cukup membantu, tetapi lansia yang kesulitan teknologi mungkin tetap memerlukan pendampingan langsung.", "C": "Skor 1: Memaksa lansia menggunakan aplikasi secara mandiri menunjukkan sikap kaku dan tidak peduli pada hambatan pengguna.", "D": "Skor 4: Membantu mendaftarkan lansia secara langsung sudah sangat membantu, tetapi belum mendorong perbaikan sistem.", "E": "Skor 5: Mendampingi pendaftaran dan menyampaikan masukan perbaikan aplikasi menyelesaikan masalah saat ini sekaligus ke depan."}, "tips": "Skor 5 sering memadukan solusi langsung bagi warga dengan masukan perbaikan sistem, sedangkan skor 4 hanya menyelesaikan masalah saat itu.", "reference": "Nilai dasar ASN BerAKHLAK: Berorientasi Pelayanan", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 89, "question_text": "Instansi Anda meluncurkan layanan antrean daring. Ternyata banyak warga lanjut usia yang kesulitan menggunakan aplikasi tersebut. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya menyarankan warga lanjut usia meminta bantuan anggota keluarganya untuk mendaftar melalui aplikasi."}, {"key": "B", "text": "Saya membuat panduan penggunaan aplikasi dalam bentuk cetak yang dibagikan di loket pelayanan."}, {"key": "C", "text": "Saya meminta warga lanjut usia tetap menggunakan aplikasi secara mandiri karena kebijakan antrean daring sudah ditetapkan."}, {"key": "D", "text": "Saya membantu mendaftarkan warga lanjut usia melalui aplikasi ketika mereka datang langsung ke kantor."}, {"key": "E", "text": "Saya mendampingi warga lanjut usia mendaftar dan menyampaikan masukan perbaikan aplikasi kepada pengelola layanan."}], "correct_answer": null, "scores": {"A": 2, "B": 3, "C": 1, "D": 4, "E": 5}, "explanation": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya pemanfaatan layanan digital yang inklusif. Opsi E paling ideal karena pegawai membantu secara langsung sekaligus mendorong perbaikan sistem, sedangkan opsi C paling rendah karena pegawai bersikap kaku dan tidak peduli pada hambatan pengguna layanan digital. Urutan skor: E (5), D (4), B (3), A (2), C (1).", "category": "Teknologi Informasi dan Komunikasi", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban terbaik adalah opsi B (skor 5). Pegawai menerima kritik dengan tenang, lalu menemui atasan untuk memahami harapannya dan memperbaiki hasil kerja, sehingga perbedaan pemahaman terselesaikan tanpa konfrontasi di depan forum.", "concept": "Soal ini menguji aspek profesionalisme, khususnya pengendalian diri dan keterbukaan terhadap kritik. ASN yang ideal tidak defensif, menjaga emosi, dan berorientasi pada perbaikan hasil kerja.", "steps": ["Pengendalian diri: menerima kritik dengan tenang meskipun merasa sudah sesuai arahan.", "Klarifikasi yang tepat: memahami harapan atasan secara langsung di luar forum.", "Orientasi perbaikan: menindaklanjuti kritik dengan memperbaiki hasil kerja."], "options": {"A": "Skor 4: Mencatat dan segera memperbaiki sesuai masukan sudah responsif, tetapi tanpa klarifikasi sehingga perbedaan pemahaman dengan atasan bisa terulang.", "B": "Skor 5: Tenang menerima kritik, mengklarifikasi harapan atasan secara pribadi, dan memperbaiki hasil kerja adalah respons yang paling profesional.", "C": "Skor 1: Merasa malu lalu menghindari atasan membiarkan emosi menghambat penyelesaian masalah.", "D": "Skor 3: Membela diri di forum dapat dipandang defensif dan kurang menjaga suasana rapat.", "E": "Skor 2: Menyerahkan perbaikan kepada rekan lain berarti melepaskan tanggung jawab atas hasil kerja sendiri."}, "tips": "Skor 5 menambahkan klarifikasi yang santun di luar forum sebelum memperbaiki, sedangkan skor 4 langsung memperbaiki tanpa menyamakan pemahaman.", "reference": "Nilai dasar ASN BerAKHLAK: Kompeten", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 90, "question_text": "Dalam rapat, atasan mengkritik hasil kerja Anda di depan rekan-rekan, padahal menurut Anda pekerjaan itu sudah sesuai dengan arahan yang diberikan sebelumnya. Sikap Anda ...", "options": [{"key": "A", "text": "Saya mencatat poin-poin kritik tersebut dan segera memperbaiki hasil kerja sesuai masukan yang disampaikan."}, {"key": "B", "text": "Saya menerima kritik itu dengan tenang, lalu menemui atasan untuk memahami harapannya dan memperbaiki hasil kerja."}, {"key": "C", "text": "Saya merasa malu dan memilih menghindari atasan untuk sementara waktu sampai suasana kembali tenang."}, {"key": "D", "text": "Saya menjelaskan secara singkat di forum bahwa hasil kerja saya telah mengikuti arahan yang diberikan sebelumnya."}, {"key": "E", "text": "Saya menerima kritik tersebut dan meminta rekan yang lebih berpengalaman untuk memperbaikinya."}], "correct_answer": null, "scores": {"A": 4, "B": 5, "C": 1, "D": 3, "E": 2}, "explanation": "Soal ini menguji aspek profesionalisme, khususnya pengendalian diri dan keterbukaan terhadap kritik. Opsi B paling ideal karena pegawai tenang, mengklarifikasi harapan atasan secara tepat, dan berorientasi pada perbaikan, sedangkan opsi C paling rendah karena pegawai menghindar dan membiarkan perasaan menghambat penyelesaian masalah. Urutan skor: B (5), A (4), D (3), E (2), C (1).", "category": "Profesionalisme", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban terbaik adalah opsi B (skor 5). Pegawai menegaskan bahwa peringatan kemerdekaan milik seluruh warga dan mengajak panitia merancang lomba yang inklusif, sehingga semangat persatuan terjaga dan sikap eksklusif dapat dicegah.", "concept": "Soal ini menguji aspek anti radikalisme, khususnya semangat persatuan dan penolakan sikap eksklusif. ASN yang ideal menjunjung persatuan Indonesia dan aktif menolak pengotakan warga berdasarkan golongan.", "steps": ["Menegakkan nilai persatuan: peringatan kemerdekaan adalah milik seluruh warga.", "Sikap tegas terhadap eksklusivitas: tidak memberi ruang bagi pembatasan berdasarkan golongan.", "Solusi inklusif: merancang kegiatan yang dapat diikuti semua warga."], "options": {"A": "Skor 3: Meminta pendapat ketua RT dan tokoh masyarakat cukup bijak, tetapi belum menunjukkan sikap tegas terhadap usulan yang eksklusif.", "B": "Skor 5: Menegaskan bahwa kemerdekaan milik semua warga dan merancang lomba inklusif mencerminkan semangat persatuan yang paling kuat.", "C": "Skor 4: Mengusulkan rapat warga dengan semangat persatuan sudah tepat arah, tetapi belum menegaskan sikap dan solusi inklusif secara langsung.", "D": "Skor 1: Menyetujui usulan karena faktor dana mendukung pengotakan warga berdasarkan golongan.", "E": "Skor 2: Membuat lomba terpisah per golongan tetap memecah warga dan bertentangan dengan semangat persatuan."}, "tips": "Skor 5 secara langsung menegaskan nilai persatuan dan menawarkan solusi inklusif, sedangkan skor 4 menyerahkan penentuan kepada forum.", "reference": "Nilai dasar ASN BerAKHLAK: Loyal, sejalan dengan kewajiban ASN setia dan taat kepada Pancasila, UUD 1945, NKRI, dan pemerintah yang sah", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 91, "question_text": "Anda menjadi panitia peringatan Hari Kemerdekaan di lingkungan tempat tinggal. Sebagian warga mengusulkan agar lomba hanya diikuti oleh warga dari golongan tertentu. Sikap Anda ...", "options": [{"key": "A", "text": "Saya meminta pendapat ketua RT dan tokoh masyarakat setempat tentang usulan tersebut sebelum panitia mengambil keputusan."}, {"key": "B", "text": "Saya menyampaikan bahwa peringatan kemerdekaan milik seluruh warga dan mengajak panitia merancang lomba yang inklusif."}, {"key": "C", "text": "Saya mengusulkan agar keputusan diambil melalui rapat warga dengan mengutamakan semangat persatuan."}, {"key": "D", "text": "Saya menyetujui usulan tersebut karena berasal dari warga yang paling banyak menyumbang dana."}, {"key": "E", "text": "Saya mengusulkan agar dibuat lomba terpisah untuk setiap golongan agar semua warga tetap terwadahi."}], "correct_answer": null, "scores": {"A": 3, "B": 5, "C": 4, "D": 1, "E": 2}, "explanation": "Soal ini menguji aspek anti radikalisme, khususnya semangat persatuan dan penolakan sikap eksklusif. Opsi B paling ideal karena pegawai menegaskan nilai persatuan dan menawarkan solusi kegiatan yang inklusif, sedangkan opsi D paling rendah karena pegawai mendukung pengotakan warga berdasarkan golongan. Urutan skor: B (5), C (4), A (3), E (2), D (1).", "category": "Anti Radikalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban terbaik adalah opsi A (skor 5). Petugas menyampaikan informasi gangguan secara terbuka dan menawarkan pendataan berkas, sehingga warga mendapat kepastian dan tidak perlu menunggu lama meskipun sistem sedang bermasalah.", "concept": "Soal ini menguji aspek pelayanan publik, khususnya keterbukaan informasi dan pemberian solusi saat layanan terganggu. ASN yang ideal transparan kepada warga dan tetap mencari cara agar layanan berjalan meskipun ada kendala teknis.", "steps": ["Transparansi: sampaikan kondisi gangguan secara jujur agar warga memahami situasi.", "Solusi alternatif: tawarkan langkah yang mengurangi waktu tunggu, seperti pendataan berkas.", "Tetap hadir melayani: tidak meninggalkan warga saat mereka membutuhkan kepastian."], "options": {"A": "Skor 5: Menginformasikan gangguan secara terbuka dan menawarkan pendataan berkas memberi kepastian sekaligus solusi bagi warga.", "B": "Skor 3: Meminta warga bersabar tanpa kepastian atau alternatif membuat kegelisahan tetap berlanjut.", "C": "Skor 2: Mempersilakan warga pulang dan kembali besok membebani warga tanpa upaya mencari solusi.", "D": "Skor 1: Beristirahat saat warga menunggu berarti meninggalkan tanggung jawab layanan.", "E": "Skor 4: Mengumumkan gangguan, meminta maaf, dan melapor ke tim teknis sudah transparan dan responsif, tetapi belum memberi alternatif bagi warga yang menunggu."}, "tips": "Skor 5 tidak berhenti pada transparansi dan permintaan maaf, tetapi juga menawarkan solusi nyata bagi warga yang terdampak.", "reference": "Nilai dasar ASN BerAKHLAK: Berorientasi Pelayanan", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 92, "question_text": "Anda petugas layanan administrasi kependudukan. Jaringan sistem sedang mengalami gangguan sehingga antrean menjadi sangat panjang dan warga mulai gelisah. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya menyampaikan informasi gangguan secara terbuka dan menawarkan pendataan berkas agar warga tidak perlu menunggu lama."}, {"key": "B", "text": "Saya meminta warga bersabar menunggu sampai jaringan kembali normal dan layanan dapat dilanjutkan."}, {"key": "C", "text": "Saya mempersilakan warga pulang dan kembali lagi keesokan harinya untuk mengurus dokumennya."}, {"key": "D", "text": "Saya beristirahat sejenak di ruang belakang karena layanan memang tidak dapat diproses saat ini."}, {"key": "E", "text": "Saya mengumumkan adanya gangguan sistem dan meminta maaf kepada warga, lalu melapor kepada tim teknis agar segera ditangani."}], "correct_answer": null, "scores": {"A": 5, "B": 3, "C": 2, "D": 1, "E": 4}, "explanation": "Soal ini menguji aspek pelayanan publik, khususnya keterbukaan informasi dan solusi saat layanan terganggu. Opsi A paling ideal karena pegawai transparan dan memberikan alternatif agar warga tetap terlayani, sedangkan opsi D paling rendah karena pegawai meninggalkan tanggung jawab layanan saat warga membutuhkan kepastian. Urutan skor: A (5), E (4), B (3), C (2), D (1).", "category": "Pelayanan Publik", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban terbaik adalah opsi A (skor 5). Pegawai mendukung program bersama dengan memberikan data setelah ada permintaan resmi dan kesepakatan kerahasiaan, serta menyamarkan data pribadi yang tidak relevan, sehingga kerja sama berjalan tanpa melanggar perlindungan data warga.", "concept": "Soal ini menguji aspek jejaring kerja, khususnya kerja sama antarinstansi yang tetap taat aturan. ASN yang ideal mendukung kolaborasi dengan mitra sambil menjaga prosedur dan perlindungan data pribadi warga.", "steps": ["Dukungan kolaborasi: tidak menolak kerja sama yang bermanfaat bagi program bersama.", "Kepatuhan prosedur: berbagi data melalui permintaan resmi dan kesepakatan kerahasiaan.", "Perlindungan data pribadi: hanya membagikan data yang relevan dan menyamarkan sisanya."], "options": {"A": "Skor 5: Memberikan data melalui jalur resmi, dengan kesepakatan kerahasiaan dan penyamaran data, menyeimbangkan kolaborasi dan perlindungan data.", "B": "Skor 4: Meminta surat resmi sudah sesuai prosedur, tetapi belum memperhatikan perlindungan data pribadi yang akan dibagikan.", "C": "Skor 1: Langsung mengirimkan data mengabaikan prosedur dan berisiko membocorkan data pribadi warga.", "D": "Skor 2: Menolak sepenuhnya memang melindungi data, tetapi menghambat program bersama yang sah.", "E": "Skor 3: Berkonsultasi dengan atasan menunjukkan kehati-hatian, tetapi belum menunjukkan pemahaman tentang prosedur berbagi data yang benar."}, "tips": "Pada soal berbagi data, skor 5 memenuhi prosedur resmi sekaligus perlindungan data pribadi; skor 4 baru memenuhi prosedur.", "reference": "Nilai dasar ASN BerAKHLAK: Kolaboratif", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 93, "question_text": "Rekan dari instansi mitra meminta data yang dikelola unit Anda untuk program bersama. Data tersebut memuat informasi pribadi warga. Sikap Anda ...", "options": [{"key": "A", "text": "Saya memberikan data setelah ada permintaan resmi dan kesepakatan kerahasiaan, dengan data pribadi yang tidak relevan disamarkan."}, {"key": "B", "text": "Saya meminta rekan tersebut mengajukan surat permintaan resmi terlebih dahulu agar pemberian data dapat diproses sesuai prosedur."}, {"key": "C", "text": "Saya langsung mengirimkan data tersebut karena kegiatan itu merupakan program bersama antarinstansi."}, {"key": "D", "text": "Saya menolak memberikan data karena memuat informasi pribadi warga yang wajib dirahasiakan."}, {"key": "E", "text": "Saya berkonsultasi dengan atasan terlebih dahulu sebelum memutuskan apakah data tersebut dapat dibagikan."}], "correct_answer": null, "scores": {"A": 5, "B": 4, "C": 1, "D": 2, "E": 3}, "explanation": "Soal ini menguji aspek jejaring kerja, khususnya kerja sama antarinstansi yang tetap taat aturan. Opsi A paling ideal karena pegawai mendukung program mitra sekaligus menjaga prosedur dan perlindungan data pribadi, sedangkan opsi C paling rendah karena pegawai mengabaikan prosedur dan berisiko membocorkan data pribadi warga. Urutan skor: A (5), B (4), E (3), D (2), C (1).", "category": "Jejaring Kerja", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban terbaik adalah opsi E (skor 5). Pegawai mengingatkan rekan-rekan secara santun bahwa candaan tentang logat daerah dapat menyinggung dan mengajak bercanda tanpa merendahkan, sehingga keharmonisan terjaga dan rekan yang menjadi sasaran terlindungi.", "concept": "Soal ini menguji aspek sosial budaya, khususnya sikap menghargai keragaman di lingkungan kerja. ASN yang ideal tidak menoleransi candaan yang merendahkan latar belakang orang lain dan berani mengingatkan dengan cara yang santun.", "steps": ["Kepekaan: menyadari bahwa candaan tentang latar belakang daerah dapat menyinggung.", "Keberanian menegur dengan santun: mengingatkan pelaku tanpa mempermalukan siapa pun.", "Menjaga harmoni: mengarahkan suasana akrab ke candaan yang tidak merendahkan."], "options": {"A": "Skor 2: Menganggap candaan itu wajar mengabaikan perasaan rekan yang menjadi sasaran.", "B": "Skor 1: Ikut tertawa agar diterima berarti mendukung perilaku yang merendahkan latar belakang daerah rekan.", "C": "Skor 3: Tidak ikut bercanda dan mengalihkan topik cukup baik, tetapi tidak menyentuh akar masalah sehingga candaan bisa terulang.", "D": "Skor 4: Menanyakan perasaan rekan yang menjadi sasaran menunjukkan empati, tetapi belum menghentikan perilaku pelaku candaan.", "E": "Skor 5: Mengingatkan secara santun dan mengajak bercanda tanpa merendahkan menghentikan perilaku tersebut sambil menjaga keakraban."}, "tips": "Skor 5 berani mengingatkan pelaku secara santun, sedangkan skor 4 hanya menunjukkan empati kepada korban.", "reference": "Nilai dasar ASN BerAKHLAK: Harmonis", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 94, "question_text": "Beberapa rekan kantor sering bercanda dengan menirukan logat daerah seorang rekan lain. Rekan yang menjadi bahan candaan tampak tidak nyaman. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menganggapnya sebagai candaan biasa yang wajar terjadi dalam pergaulan sehari-hari di lingkungan kantor."}, {"key": "B", "text": "Saya ikut tertawa bersama mereka agar tidak dianggap kaku atau tidak bisa bergaul oleh rekan-rekan yang lain."}, {"key": "C", "text": "Saya tidak ikut bercanda dan berusaha mengalihkan pembicaraan ke topik lain agar candaan tidak berlanjut."}, {"key": "D", "text": "Saya menghampiri rekan yang menjadi bahan candaan dan menanyakan apakah ia merasa terganggu dengan candaan tersebut."}, {"key": "E", "text": "Saya mengingatkan rekan-rekan secara santun bahwa candaan itu dapat menyinggung dan mengajak bercanda tanpa merendahkan."}], "correct_answer": null, "scores": {"A": 2, "B": 1, "C": 3, "D": 4, "E": 5}, "explanation": "Soal ini menguji aspek sosial budaya, khususnya sikap menghargai keragaman di lingkungan kerja. Opsi E paling ideal karena pegawai menegur dengan santun dan menjaga keharmonisan tanpa merendahkan siapa pun, sedangkan opsi B paling rendah karena pegawai ikut mendukung perilaku yang merendahkan latar belakang daerah rekannya. Urutan skor: E (5), D (4), C (3), A (2), B (1).", "category": "Sosial Budaya", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban terbaik adalah opsi D (skor 5). Pegawai menyerahkan flashdisk temuan kepada bagian umum atau pengelola TI tanpa mencolokkannya ke komputer kantor, sehingga risiko malware dan kebocoran data dapat dicegah dan barang tetap dapat dikembalikan kepada pemiliknya.", "concept": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya keamanan perangkat dan jaringan kantor. ASN yang ideal waspada terhadap perangkat penyimpanan asing dan menyerahkan penanganannya kepada pihak yang berwenang.", "steps": ["Kewaspadaan keamanan: perangkat asing berpotensi membawa malware sehingga tidak boleh dicolokkan sembarangan.", "Prosedur yang benar: serahkan kepada pengelola TI atau bagian umum yang berwenang.", "Menahan rasa penasaran demi melindungi data dan jaringan instansi."], "options": {"A": "Skor 3: Menyimpan flashdisk di laci tidak berisiko bagi jaringan, tetapi pasif dan tidak memudahkan pemilik menemukannya.", "B": "Skor 1: Mencolokkan flashdisk ke komputer kantor berisiko menyebarkan malware ke jaringan instansi.", "C": "Skor 2: Membukanya di laptop pribadi tetap berisiko malware dan dapat melanggar privasi pemiliknya.", "D": "Skor 5: Menyerahkan tanpa mencolokkan ke komputer kepada pihak berwenang mencegah risiko keamanan dan memastikan penanganan yang tepat.", "E": "Skor 4: Mengumumkan temuan di grup kantor aman dan membantu pemilik, tetapi penanganannya tidak melibatkan pihak yang berwenang."}, "tips": "Skor 5 pada soal perangkat asing selalu menghindari membuka isinya dan menyerahkan kepada pihak berwenang, sedangkan skor 4 aman tetapi ditangani sendiri.", "reference": "Nilai dasar ASN BerAKHLAK: Akuntabel", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 95, "question_text": "Anda menemukan sebuah flashdisk tanpa identitas pemilik di ruang rapat kantor. Anda penasaran dengan isinya. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya menyimpan flashdisk tersebut di laci meja kerja saya sampai suatu saat ada orang yang datang menanyakannya."}, {"key": "B", "text": "Saya mencolokkan flashdisk ke komputer kantor untuk memeriksa isinya dan mencari tahu siapa pemiliknya."}, {"key": "C", "text": "Saya membuka flashdisk tersebut di laptop pribadi untuk mencari identitas pemiliknya."}, {"key": "D", "text": "Saya menyerahkan flashdisk tersebut kepada bagian umum atau pengelola TI tanpa mencolokkannya ke komputer kantor."}, {"key": "E", "text": "Saya mengumumkan temuan flashdisk itu di grup kantor agar pemiliknya dapat mengambilnya kepada saya."}], "correct_answer": null, "scores": {"A": 3, "B": 1, "C": 2, "D": 5, "E": 4}, "explanation": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya keamanan perangkat dan jaringan kantor. Opsi D paling ideal karena pegawai mencegah risiko malware dan kebocoran data dengan menyerahkannya kepada pihak yang berwenang, sedangkan opsi B paling rendah karena pegawai membuka perangkat asing di komputer kantor yang berisiko menyebarkan malware ke jaringan instansi. Urutan skor: D (5), E (4), A (3), C (2), B (1).", "category": "Teknologi Informasi dan Komunikasi", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban terbaik adalah opsi D (skor 5). Pegawai menolak bingkisan dengan sopan, menjelaskan larangan gratifikasi, dan mempersilakan warga mengisi survei kepuasan layanan, sehingga integritas terjaga sekaligus warga teredukasi dan apresiasinya tersalurkan secara resmi.", "concept": "Soal ini menguji aspek profesionalisme, khususnya integritas dan penolakan gratifikasi. ASN yang ideal menolak segala bentuk pemberian terkait layanan, menjelaskan alasannya, dan mengarahkan apresiasi ke saluran resmi.", "steps": ["Integritas: menolak pemberian terkait jabatan, berapa pun nilainya.", "Edukasi: menjelaskan larangan gratifikasi agar warga memahami alasannya.", "Saluran apresiasi resmi: mengarahkan warga mengisi survei kepuasan layanan."], "options": {"A": "Skor 2: Menerima karena nilainya kecil tetap termasuk gratifikasi meskipun diberikan setelah layanan selesai.", "B": "Skor 3: Mengalihkan bingkisan ke bagian umum terkesan tidak menerima secara pribadi, tetapi pemberian tetap diterima oleh pegawai kantor.", "C": "Skor 4: Menolak dengan sopan sudah menjaga integritas, tetapi tidak disertai edukasi tentang larangan gratifikasi.", "D": "Skor 5: Menolak dengan sopan, menjelaskan larangan gratifikasi, dan mengarahkan ke survei kepuasan adalah sikap paling berintegritas dan edukatif.", "E": "Skor 1: Menerima bingkisan sambil menjanjikan kemudahan adalah gratifikasi yang disertai perlakuan istimewa."}, "tips": "Skor 5 menolak, mengedukasi, dan mengarahkan ke saluran resmi; skor 4 menolak tanpa menjelaskan alasan aturannya.", "reference": "Nilai dasar ASN BerAKHLAK: Akuntabel", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 96, "question_text": "Seorang warga yang urusan administrasinya baru saja selesai Anda layani menyodorkan bingkisan sebagai tanda terima kasih. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menerima bingkisan tersebut karena nilainya kecil dan diberikan setelah layanan selesai."}, {"key": "B", "text": "Saya meminta warga tersebut menyerahkan bingkisannya kepada bagian umum agar dapat dibagikan kepada seluruh pegawai kantor."}, {"key": "C", "text": "Saya menolak bingkisan dengan sopan dan menyampaikan bahwa ucapan terima kasih saja sudah cukup."}, {"key": "D", "text": "Saya menolak dengan sopan, menjelaskan larangan gratifikasi, dan mempersilakan warga mengisi survei kepuasan layanan."}, {"key": "E", "text": "Saya menerima bingkisan tersebut dan menawarkan kemudahan apabila ia membutuhkan layanan lain."}], "correct_answer": null, "scores": {"A": 2, "B": 3, "C": 4, "D": 5, "E": 1}, "explanation": "Soal ini menguji aspek profesionalisme, khususnya integritas dan penolakan gratifikasi. Opsi D paling ideal karena pegawai menolak gratifikasi sekaligus mengedukasi warga dan mengarahkan apresiasi ke saluran resmi, sedangkan opsi E paling rendah karena pegawai menerima gratifikasi dan menjanjikan perlakuan istimewa. Urutan skor: D (5), C (4), B (3), A (2), E (1).", "category": "Profesionalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban terbaik adalah opsi C (skor 5). Pegawai menasihati temannya secara pribadi tentang dampak hukum ujaran kebencian, lalu melaporkan kontennya bila unggahan berlanjut, sehingga pendekatan persuasif didahulukan dan langkah tegas tetap disiapkan.", "concept": "Soal ini menguji aspek anti radikalisme, khususnya penolakan terhadap ujaran kebencian. ASN yang ideal tidak membiarkan ujaran kebencian terhadap kelompok mana pun, mengutamakan pendekatan persuasif, dan menempuh pelaporan bila diperlukan.", "steps": ["Tidak membiarkan: ujaran kebencian harus dicegah karena dapat memecah belah masyarakat.", "Pendekatan persuasif: nasihat pribadi lebih efektif dan menjaga hubungan baik.", "Langkah tegas berjenjang: melaporkan konten apabila nasihat tidak diindahkan."], "options": {"A": "Skor 3: Mengajak saling menghargai di kolom komentar positif, tetapi tidak menyentuh pelaku secara langsung.", "B": "Skor 1: Membiarkan karena dianggap urusan pribadi berarti membiarkan ujaran kebencian menyebar.", "C": "Skor 5: Menasihati secara pribadi lalu melapor bila tetap berlanjut menggabungkan pendekatan persuasif dan tindakan tegas.", "D": "Skor 2: Berhenti mengikuti akun hanya melindungi diri sendiri tanpa mencegah penyebaran konten.", "E": "Skor 4: Melaporkan ke platform sudah tegas dan tepat, tetapi melewatkan upaya persuasif kepada teman sendiri."}, "tips": "Skor 5 mendahulukan nasihat pribadi lalu melapor bila perlu, sedangkan skor 4 langsung melapor tanpa pendekatan persuasif.", "reference": "Nilai dasar ASN BerAKHLAK: Loyal, sejalan dengan kewajiban ASN setia dan taat kepada Pancasila, UUD 1945, NKRI, dan pemerintah yang sah", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 97, "question_text": "Seorang teman di media sosial sering mengunggah ujaran kebencian terhadap kelompok minoritas di daerahnya. Unggahannya mulai mendapat banyak tanggapan. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menulis komentar yang mengajak teman-teman lain untuk saling menghargai perbedaan dan menahan diri."}, {"key": "B", "text": "Saya membiarkannya karena itu urusan pribadi teman saya di akun media sosialnya sendiri."}, {"key": "C", "text": "Saya menasihatinya secara pribadi tentang dampak hukum ujaran kebencian, lalu melaporkan kontennya bila ia tetap mengunggah."}, {"key": "D", "text": "Saya berhenti mengikuti akun teman tersebut agar tidak lagi terpapar konten serupa di beranda saya."}, {"key": "E", "text": "Saya melaporkan unggahan tersebut kepada pengelola platform media sosial sebagai konten yang mengandung ujaran kebencian."}], "correct_answer": null, "scores": {"A": 3, "B": 1, "C": 5, "D": 2, "E": 4}, "explanation": "Soal ini menguji aspek anti radikalisme, khususnya penolakan terhadap ujaran kebencian. Opsi C paling ideal karena pegawai menempuh pendekatan persuasif terlebih dahulu dan tetap menyiapkan langkah pelaporan, sedangkan opsi B paling rendah karena pegawai membiarkan ujaran kebencian menyebar tanpa upaya pencegahan. Urutan skor: C (5), E (4), A (3), D (2), B (1).", "category": "Anti Radikalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "E", "summary": "Jawaban terbaik adalah opsi E (skor 5). Pegawai mendengarkan keluhan dengan tenang, memeriksa status surat, dan memastikan surat selesai hari itu juga, sehingga emosi warga mereda dan janji layanan tetap ditepati.", "concept": "Soal ini menguji aspek pelayanan publik, khususnya pengendalian emosi dan ketepatan janji layanan. ASN yang ideal tetap tenang menghadapi warga yang marah dan bertanggung jawab menepati standar waktu layanan yang telah dijanjikan.", "steps": ["Pengendalian emosi: dengarkan keluhan dengan tenang dan empatik.", "Tindakan nyata: periksa status layanan secara langsung.", "Menepati janji layanan: pastikan hasil diberikan sesuai waktu yang dijanjikan."], "options": {"A": "Skor 3: Menjelaskan alasan keterlambatan memberi informasi, tetapi terkesan membela diri tanpa solusi.", "B": "Skor 2: Meminta warga menunggu tanpa kepastian waktu tidak menyelesaikan masalah.", "C": "Skor 1: Mensyaratkan warga tenang sebelum dilayani menunda layanan dan tidak empatik terhadap warga yang dirugikan.", "D": "Skor 4: Meminta maaf dan menanyakan perkiraan waktu penyelesaian sudah baik, tetapi belum memastikan janji layanan ditepati hari itu.", "E": "Skor 5: Mendengarkan dengan tenang, memeriksa status, dan memastikan surat selesai hari itu menuntaskan keluhan sekaligus menepati janji layanan."}, "tips": "Skor 5 memastikan hasil layanan tuntas sesuai janji, sedangkan skor 4 baru meminta maaf dan mencari informasi.", "reference": "Nilai dasar ASN BerAKHLAK: Berorientasi Pelayanan", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 98, "question_text": "Seorang warga datang ke kantor kelurahan dengan marah karena surat pengantar yang dijanjikan selesai hari ini ternyata belum selesai. Sikap Anda ...", "options": [{"key": "A", "text": "Saya menjelaskan bahwa hari ini banyak permohonan sehingga penyelesaian surat menjadi terlambat."}, {"key": "B", "text": "Saya meminta warga menunggu di ruang tunggu sampai petugas yang menangani suratnya kembali."}, {"key": "C", "text": "Saya meminta warga tersebut menenangkan diri terlebih dahulu sebelum saya bersedia melayaninya."}, {"key": "D", "text": "Saya meminta maaf atas keterlambatan tersebut dan menanyakan kepada petugas terkait kapan surat dapat diselesaikan."}, {"key": "E", "text": "Saya mendengarkan keluhannya dengan tenang, memeriksa status suratnya, dan memastikan surat selesai hari itu juga."}], "correct_answer": null, "scores": {"A": 3, "B": 2, "C": 1, "D": 4, "E": 5}, "explanation": "Soal ini menguji aspek pelayanan publik, khususnya pengendalian emosi dan ketepatan janji layanan. Opsi E paling ideal karena pegawai tenang, empatik, dan memastikan janji layanan ditepati, sedangkan opsi C paling rendah karena pegawai menunda layanan dan bersikap tidak empatik terhadap warga yang dirugikan. Urutan skor: E (5), D (4), A (3), B (2), C (1).", "category": "Pelayanan Publik", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban terbaik adalah opsi A (skor 5). Pegawai hadir, aktif berbagi pengalaman, dan menjalin komunikasi lanjutan dengan peserta lain, sehingga forum dimanfaatkan secara maksimal untuk membangun kolaborasi jangka panjang.", "concept": "Soal ini menguji aspek jejaring kerja, khususnya pemanfaatan forum untuk memperluas jejaring. ASN yang ideal tidak hanya hadir, tetapi juga berkontribusi dan merawat relasi untuk kolaborasi lintas instansi.", "steps": ["Partisipasi aktif: berkontribusi dengan berbagi pengalaman, bukan sekadar mendengarkan.", "Keberlanjutan relasi: menjalin komunikasi lanjutan setelah forum selesai.", "Orientasi kolaborasi: memandang forum sebagai peluang kerja sama lintas instansi."], "options": {"A": "Skor 5: Hadir, berbagi pengalaman, dan menindaklanjuti relasi menjadikan forum sebagai sarana kolaborasi yang nyata.", "B": "Skor 4: Mencatat praktik baik untuk diterapkan itu bermanfaat, tetapi sifatnya satu arah tanpa membangun relasi.", "C": "Skor 1: Tidak hadir karena dianggap tidak berkaitan dengan target kerja melewatkan kesempatan membangun jejaring.", "D": "Skor 3: Hadir dan mengikuti acara dengan tertib sudah baik, tetapi bersifat pasif.", "E": "Skor 2: Mewakilkan kepada rekan yang senggang menunjukkan kurangnya perhatian pada kesempatan membangun jejaring."}, "tips": "Skor 5 terlibat dua arah dan menjaga relasi setelah forum, sedangkan skor 4 hanya menyerap manfaat untuk unit sendiri.", "reference": "Nilai dasar ASN BerAKHLAK: Kolaboratif", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 99, "question_text": "Anda diundang menghadiri forum komunitas lintas instansi yang membahas inovasi pelayanan publik. Sikap Anda ...", "options": [{"key": "A", "text": "Saya hadir, aktif berbagi pengalaman, dan menjalin komunikasi lanjutan dengan peserta lain untuk berkolaborasi."}, {"key": "B", "text": "Saya hadir dan mencatat praktik baik dari instansi lain untuk dicoba diterapkan di unit kerja saya sendiri."}, {"key": "C", "text": "Saya tidak hadir karena forum tersebut tidak berkaitan langsung dengan target kerja saya."}, {"key": "D", "text": "Saya hadir dan mengikuti seluruh rangkaian acara forum dengan tertib dari awal hingga akhir kegiatan."}, {"key": "E", "text": "Saya mewakilkan kehadiran kepada rekan yang sedang tidak memiliki pekerjaan mendesak."}], "correct_answer": null, "scores": {"A": 5, "B": 4, "C": 1, "D": 3, "E": 2}, "explanation": "Soal ini menguji aspek jejaring kerja, khususnya pemanfaatan forum untuk memperluas jejaring. Opsi A paling ideal karena pegawai aktif berkontribusi dan menindaklanjuti relasi untuk kolaborasi, sedangkan opsi C paling rendah karena pegawai melewatkan kesempatan membangun jejaring kerja. Urutan skor: A (5), B (4), D (3), E (2), C (1).", "category": "Jejaring Kerja", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban terbaik adalah opsi C (skor 5). Pegawai menggandeng tokoh adat dan tokoh masyarakat agar program disampaikan dengan pendekatan yang sesuai budaya setempat, sehingga pesan kesehatan lebih mudah diterima tanpa merendahkan kepercayaan warga.", "concept": "Soal ini menguji aspek sosial budaya, khususnya kepekaan budaya dalam pelaksanaan program. ASN yang ideal menghormati nilai dan kepercayaan masyarakat serta memanfaatkan figur yang dipercaya warga untuk menyukseskan program.", "steps": ["Menghormati budaya: tidak merendahkan kepercayaan dan praktik masyarakat setempat.", "Pendekatan melalui tokoh: tokoh adat dan masyarakat dipercaya warga sehingga pesan lebih efektif.", "Komitmen pada program: tetap melaksanakan sosialisasi yang dibutuhkan masyarakat."], "options": {"A": "Skor 1: Membatalkan sosialisasi berarti menyerah dan menelantarkan program yang dibutuhkan masyarakat.", "B": "Skor 4: Mempelajari kebiasaan masyarakat terlebih dahulu menunjukkan kepekaan budaya, tetapi belum melibatkan figur yang dipercaya warga.", "C": "Skor 5: Menggandeng tokoh adat dan tokoh masyarakat menghormati budaya setempat sekaligus membuat program lebih mudah diterima.", "D": "Skor 3: Menyampaikan materi dengan bahasa sederhana sudah berupaya, tetapi kurang memperhatikan konteks budaya setempat.", "E": "Skor 2: Menegaskan bahwa pengobatan tradisional kurang ilmiah dapat menyinggung warga dan menimbulkan penolakan."}, "tips": "Skor 5 dalam program berbasis masyarakat biasanya melibatkan tokoh yang dipercaya warga, sedangkan skor 4 baru pada tahap memahami budaya.", "reference": "Nilai dasar ASN BerAKHLAK: Harmonis", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 100, "question_text": "Anda ditugaskan menyosialisasikan program kesehatan ibu dan anak di sebuah desa yang masyarakatnya masih memegang kuat kepercayaan terhadap pengobatan tradisional. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya membatalkan sosialisasi karena masyarakat desa tersebut sulit menerima program dari luar."}, {"key": "B", "text": "Saya mempelajari kebiasaan dan pandangan masyarakat terlebih dahulu agar materi sosialisasi lebih mudah diterima."}, {"key": "C", "text": "Saya menggandeng tokoh adat dan tokoh masyarakat agar program disampaikan dengan pendekatan yang sesuai budaya setempat."}, {"key": "D", "text": "Saya menyampaikan sosialisasi sesuai materi dari dinas dengan bahasa yang sederhana."}, {"key": "E", "text": "Saya menegaskan bahwa pengobatan tradisional kurang ilmiah dibandingkan layanan kesehatan modern."}], "correct_answer": null, "scores": {"A": 1, "B": 4, "C": 5, "D": 3, "E": 2}, "explanation": "Soal ini menguji aspek sosial budaya, khususnya kepekaan budaya dalam pelaksanaan program. Opsi C paling ideal karena pegawai menghormati budaya setempat dan memanfaatkan tokoh yang dipercaya masyarakat, sedangkan opsi A paling rendah karena pegawai menyerah dan menelantarkan program yang dibutuhkan masyarakat. Urutan skor: C (5), B (4), D (3), E (2), A (1).", "category": "Sosial Budaya", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban terbaik adalah opsi C (skor 5). Pengelola akun segera menyembunyikan komentar yang memuat foto KTP dan Kartu Keluarga, lalu menjawab pertanyaan warga lewat pesan pribadi sambil mengingatkan risiko data, sehingga paparan data pribadi langsung dihentikan dan warga tetap terlayani.", "concept": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya perlindungan data pribadi dalam layanan digital. ASN yang ideal cepat mencegah penyalahgunaan data pribadi warga dan tetap memberikan pelayanan serta edukasi.", "steps": ["Tindakan cepat: segera hentikan paparan data pribadi di ruang publik.", "Tetap melayani: jawab pertanyaan warga melalui kanal yang aman.", "Edukasi: ingatkan warga tentang risiko membagikan dokumen pribadi."], "options": {"A": "Skor 4: Menjawab lewat pesan pribadi dan menyarankan penghapusan sudah baik, tetapi data tetap terpapar sampai warga sendiri menghapusnya.", "B": "Skor 2: Menjawab di kolom komentar tanpa menyinggung dokumen yang terunggah membiarkan data pribadi tetap terpapar.", "C": "Skor 5: Menyembunyikan komentar, menjawab lewat pesan pribadi, dan mengingatkan risiko data langsung melindungi data sekaligus melayani.", "D": "Skor 1: Membiarkan komentar karena warga sendiri yang mengunggah mengabaikan risiko penyalahgunaan data pribadi.", "E": "Skor 3: Menjelaskan layanan sambil mengingatkan di kolom publik sudah mengedukasi, tetapi data tetap terpapar."}, "tips": "Skor 5 langsung menghentikan paparan data dengan kewenangan yang dimiliki, sedangkan skor 4 masih bergantung pada tindakan warga.", "reference": "Nilai dasar ASN BerAKHLAK: Akuntabel", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 101, "question_text": "Anda mengelola akun media sosial resmi instansi. Seorang warga bertanya tentang layanan sambil mengunggah foto KTP dan Kartu Keluarganya di kolom komentar publik. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya menjawab pertanyaannya melalui pesan pribadi dan menyarankan agar ia menghapus foto dokumen yang diunggahnya."}, {"key": "B", "text": "Saya menjawab pertanyaan warga tersebut di kolom komentar sesuai informasi layanan yang tersedia."}, {"key": "C", "text": "Saya segera menyembunyikan komentar itu, lalu menjawab pertanyaannya lewat pesan pribadi sambil mengingatkan risiko data."}, {"key": "D", "text": "Saya membiarkan komentar tersebut karena warga sendiri yang memilih untuk mengunggah dokumen pribadinya."}, {"key": "E", "text": "Saya membalas komentar dengan menjelaskan layanan dan mengingatkan agar tidak mengunggah dokumen pribadi."}], "correct_answer": null, "scores": {"A": 4, "B": 2, "C": 5, "D": 1, "E": 3}, "explanation": "Soal ini menguji aspek teknologi informasi dan komunikasi, khususnya perlindungan data pribadi dalam layanan digital. Opsi C paling ideal karena pegawai segera menutup paparan data pribadi sambil tetap melayani dan mengedukasi warga, sedangkan opsi D paling rendah karena pegawai membiarkan data pribadi warga terpapar publik. Urutan skor: C (5), A (4), E (3), B (2), D (1).", "category": "Teknologi Informasi dan Komunikasi", "difficulty": "hard"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban terbaik adalah opsi A (skor 5). Pegawai menanyakan kepada atasan atau rekan pekerjaan yang dapat dibantu, atau belajar hal yang menunjang tugas, sehingga sisa waktu kerja tetap produktif dan bermanfaat bagi tim maupun pengembangan diri.", "concept": "Soal ini menguji aspek profesionalisme, khususnya etos kerja dan pemanfaatan waktu kerja. ASN yang ideal memanfaatkan jam kerja secara optimal, peduli pada beban tim, dan terus mengembangkan kompetensi.", "steps": ["Disiplin jam kerja: tetap berada di tempat dan produktif hingga jam kerja berakhir.", "Kepedulian tim: menawarkan bantuan kepada atasan atau rekan.", "Pengembangan diri: memanfaatkan waktu untuk belajar hal yang menunjang tugas."], "options": {"A": "Skor 5: Menawarkan bantuan atau belajar hal yang menunjang tugas menunjukkan etos kerja, kepedulian tim, dan pengembangan diri.", "B": "Skor 3: Menyiapkan pekerjaan esok hari itu produktif, tetapi hanya berfokus pada tugas sendiri.", "C": "Skor 4: Memeriksa kembali hasil kerja menunjukkan ketelitian dan tanggung jawab atas mutu, tetapi belum memberi nilai tambah bagi tim.", "D": "Skor 2: Membaca berita dan media sosial sambil menunggu jam pulang adalah pemanfaatan waktu kerja yang tidak produktif.", "E": "Skor 1: Pulang lebih awal tanpa izin melanggar ketentuan jam kerja."}, "tips": "Skor 5 memanfaatkan waktu luang untuk membantu tim atau mengembangkan diri, sedangkan skor 4 masih seputar pekerjaannya sendiri.", "reference": "Nilai dasar ASN BerAKHLAK: Akuntabel", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 102, "question_text": "Pekerjaan yang menjadi tanggung jawab Anda hari ini sudah selesai sebelum jam kerja berakhir. Yang Anda lakukan ...", "options": [{"key": "A", "text": "Saya menanyakan kepada atasan atau rekan apakah ada pekerjaan yang dapat dibantu, atau belajar hal yang menunjang tugas."}, {"key": "B", "text": "Saya menyiapkan bahan untuk pekerjaan esok hari agar dapat diselesaikan lebih cepat."}, {"key": "C", "text": "Saya memeriksa kembali hasil pekerjaan saya untuk memastikan tidak ada kesalahan sebelum diserahkan."}, {"key": "D", "text": "Saya membaca berita dan media sosial di internet sambil menunggu jam pulang kantor tiba."}, {"key": "E", "text": "Saya pulang lebih awal tanpa izin karena seluruh pekerjaan yang menjadi tanggung jawab saya hari ini sudah selesai dikerjakan."}], "correct_answer": null, "scores": {"A": 5, "B": 3, "C": 4, "D": 2, "E": 1}, "explanation": "Soal ini menguji aspek profesionalisme, khususnya etos kerja dan pemanfaatan waktu kerja. Opsi A paling ideal karena pegawai produktif, peduli pada tim, dan mau mengembangkan diri, sedangkan opsi E paling rendah karena pegawai melanggar ketentuan jam kerja. Urutan skor: A (5), C (4), B (3), D (2), E (1).", "category": "Profesionalisme", "difficulty": "easy"}, {"explanation_detail": {"v": 1, "answer": "A", "summary": "Jawaban terbaik adalah opsi A (skor 5). Pegawai tidak ikut menyebarkan ceramah, mengingatkan teman bahwa ajakan tersebut bertentangan dengan Pancasila, dan melaporkannya, sehingga ia memutus penyebaran sekaligus meluruskan pemahaman lingkungannya.", "concept": "Soal ini menguji aspek anti radikalisme, khususnya kesetiaan pada NKRI dan sikap kritis terhadap ajakan tidak mengakui pemerintahan yang sah. ASN yang ideal setia pada dasar negara tanpa terpengaruh ketokohan seseorang dan aktif mencegah penyebaran ajakan tersebut.", "steps": ["Memutus penyebaran: tidak ikut membagikan konten yang bertentangan dengan dasar negara.", "Meluruskan pemahaman: mengingatkan teman secara jelas tentang pertentangannya dengan Pancasila.", "Pelaporan: menempuh jalur resmi agar konten ditangani pihak berwenang."], "options": {"A": "Skor 5: Tidak menyebarkan, mengingatkan teman tentang pertentangannya dengan Pancasila, dan melapor adalah sikap setia dan aktif mencegah.", "B": "Skor 2: Berhenti menonton tanpa menanggapi hanya menjaga diri sendiri dan membiarkan penyebaran berlanjut.", "C": "Skor 4: Mengajak teman bersikap kritis sudah aktif, tetapi belum menegaskan pertentangannya dengan dasar negara maupun melapor.", "D": "Skor 1: Ikut membagikan karena ketokohan berarti turut menyebarkan ajakan yang bertentangan dengan dasar negara.", "E": "Skor 3: Tidak menyetujui bagian yang bertentangan sudah benar secara pribadi, tetapi tidak mencegah penyebaran di lingkungannya."}, "tips": "Skor 5 menegaskan pertentangan dengan Pancasila dan melapor, sedangkan skor 4 hanya mengajak bersikap kritis secara umum.", "reference": "Nilai dasar ASN BerAKHLAK: Loyal, sejalan dengan kewajiban ASN setia dan taat kepada Pancasila, UUD 1945, NKRI, dan pemerintah yang sah", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 103, "question_text": "Seorang tokoh yang Anda kagumi menyampaikan ceramah daring yang memuat ajakan untuk tidak mengakui pemerintahan yang sah. Banyak teman Anda memuji dan membagikan ceramah tersebut. Sikap Anda ...", "options": [{"key": "A", "text": "Saya tidak ikut menyebarkannya, mengingatkan teman bahwa ajakan itu bertentangan dengan Pancasila, dan melaporkannya."}, {"key": "B", "text": "Saya berhenti menonton ceramah tokoh tersebut tanpa menanggapi pujian dari teman-teman."}, {"key": "C", "text": "Saya mengingatkan teman-teman agar bersikap kritis terhadap isi ceramah meskipun disampaikan oleh tokoh yang dihormati."}, {"key": "D", "text": "Saya ikut membagikan ceramah tersebut karena tokoh itu memiliki banyak pengikut dan dihormati."}, {"key": "E", "text": "Saya tetap menghormati tokoh tersebut, tetapi tidak menyetujui bagian ceramah yang bertentangan dengan dasar negara."}], "correct_answer": null, "scores": {"A": 5, "B": 2, "C": 4, "D": 1, "E": 3}, "explanation": "Soal ini menguji aspek anti radikalisme, khususnya kesetiaan pada NKRI dan sikap kritis terhadap ajakan makar. Opsi A paling ideal karena pegawai memutus penyebaran, meluruskan pemahaman lingkungan, dan menempuh jalur resmi, sedangkan opsi D paling rendah karena pegawai ikut menyebarkan ajakan yang bertentangan dengan dasar negara. Urutan skor: A (5), C (4), E (3), B (2), D (1).", "category": "Anti Radikalisme", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "D", "summary": "Jawaban terbaik adalah opsi D (skor 5). Pegawai membantu mengisi formulir sesuai keterangan pemohon dan memberikan layanan prioritas sesuai ketentuan, sehingga penyandang disabilitas memperoleh haknya atas layanan yang mudah dan diprioritaskan.", "concept": "Soal ini menguji aspek pelayanan publik, khususnya pelayanan inklusif bagi kelompok rentan. ASN yang ideal memberikan bantuan langsung dan menerapkan hak layanan prioritas bagi penyandang disabilitas sesuai ketentuan.", "steps": ["Bantuan langsung: membantu pemohon yang kesulitan tanpa melimpahkannya kepada orang lain.", "Pemenuhan hak: kelompok rentan berhak memperoleh perlakuan khusus berupa layanan prioritas.", "Menghormati pemohon: formulir diisi sesuai keterangan yang bersangkutan."], "options": {"A": "Skor 4: Membantu mengisi formulir sudah tepat, tetapi tidak menerapkan hak layanan prioritas bagi penyandang disabilitas.", "B": "Skor 1: Meminta membawa pulang formulir membebani warga rentan dan tidak memberikan layanan yang layak.", "C": "Skor 2: Memberikan contoh formulir kurang membantu karena pemohon tetap kesulitan mengisinya sendiri.", "D": "Skor 5: Membantu mengisi formulir dan memberikan layanan prioritas sesuai ketentuan memenuhi hak penyandang disabilitas secara utuh.", "E": "Skor 3: Meminta petugas lain membantu tetap memastikan bantuan, tetapi melimpahkan tanggung jawab yang dapat dikerjakan sendiri."}, "tips": "Pada soal kelompok rentan, skor 5 biasanya memberikan bantuan langsung sekaligus hak layanan prioritas, sedangkan skor 4 hanya membantu.", "reference": "Nilai dasar ASN BerAKHLAK: Berorientasi Pelayanan", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 104, "question_text": "Anda petugas layanan di kantor kecamatan. Seorang penyandang disabilitas datang sendirian dan tampak kesulitan mengisi formulir permohonan. Sikap Anda ...", "options": [{"key": "A", "text": "Saya membantu mengisikan formulir tersebut, lalu memprosesnya sesuai urutan antrean yang berlaku seperti pemohon lain."}, {"key": "B", "text": "Saya memintanya membawa pulang formulir tersebut dan kembali setelah formulir terisi lengkap."}, {"key": "C", "text": "Saya memberikan contoh formulir yang sudah terisi agar ia dapat mengisinya sendiri."}, {"key": "D", "text": "Saya membantu mengisi formulir sesuai keterangannya dan memberikan layanan prioritas sesuai ketentuan yang berlaku."}, {"key": "E", "text": "Saya meminta petugas lain yang sedang senggang untuk membantunya mengisi formulir tersebut."}], "correct_answer": null, "scores": {"A": 4, "B": 1, "C": 2, "D": 5, "E": 3}, "explanation": "Soal ini menguji aspek pelayanan publik, khususnya pelayanan inklusif bagi kelompok rentan. Opsi D paling ideal karena pegawai membantu secara langsung dan menerapkan hak layanan prioritas bagi penyandang disabilitas, sedangkan opsi B paling rendah karena pegawai membebani warga rentan dan tidak memberikan layanan yang layak. Urutan skor: D (5), A (4), E (3), C (2), B (1).", "category": "Pelayanan Publik", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "C", "summary": "Jawaban terbaik adalah opsi C (skor 5). Pegawai mengajak rekannya berdiskusi membandingkan kelebihan tiap metode dan menyepakati cara yang paling efektif, sehingga perbedaan pendapat menjadi bahan untuk mencapai hasil terbaik bersama.", "concept": "Soal ini menguji aspek jejaring kerja, khususnya pengelolaan perbedaan pendapat dalam tim. ASN yang ideal mengedepankan dialog yang objektif dan kesepakatan bersama, bukan memaksakan kehendak atau menghindari konflik.", "steps": ["Dialog terbuka: bahas perbedaan secara langsung dengan rekan.", "Objektivitas: bandingkan kelebihan tiap metode berdasarkan efektivitasnya.", "Kesepakatan bersama: tetapkan metode yang disetujui kedua pihak agar kerja tim solid."], "options": {"A": "Skor 3: Meminta ketua tim memutuskan menjaga pekerjaan tetap berjalan, tetapi melewatkan kesempatan menyelesaikan perbedaan secara langsung.", "B": "Skor 2: Mengikuti metode rekan demi menghindari konflik mengorbankan pendapat sendiri tanpa diskusi yang objektif.", "C": "Skor 5: Berdiskusi membandingkan kelebihan tiap metode dan menyepakati cara terbaik adalah penyelesaian perbedaan yang paling konstruktif.", "D": "Skor 1: Bekerja dengan metode sendiri tanpa koordinasi membuat kerja tim terpecah.", "E": "Skor 4: Mendengarkan dengan terbuka dan bersedia mencoba metode rekan sudah baik, tetapi belum mengajak menimbang kedua metode secara bersama."}, "tips": "Skor 5 aktif mengajak dialog dua arah menuju kesepakatan, sedangkan skor 4 sekadar terbuka menerima pendapat pihak lain.", "reference": "Nilai dasar ASN BerAKHLAK: Kolaboratif", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 105, "question_text": "Anda dan rekan satu tim memiliki pendapat yang sangat berbeda tentang metode penyelesaian sebuah tugas, padahal tugas tersebut harus diselesaikan bersama. Sikap Anda ...", "options": [{"key": "A", "text": "Saya meminta ketua tim memutuskan metode yang akan digunakan agar pekerjaan tidak tertunda."}, {"key": "B", "text": "Saya mengikuti metode rekan tersebut agar tidak terjadi konflik meskipun saya kurang setuju."}, {"key": "C", "text": "Saya mengajak rekan berdiskusi membandingkan kelebihan tiap metode dan menyepakati cara yang paling efektif."}, {"key": "D", "text": "Saya mengerjakan bagian saya dengan metode sendiri tanpa perlu berkoordinasi dengannya."}, {"key": "E", "text": "Saya mendengarkan alasan rekan tersebut dengan terbuka dan bersedia mencoba metodenya apabila memang terbukti lebih baik."}], "correct_answer": null, "scores": {"A": 3, "B": 2, "C": 5, "D": 1, "E": 4}, "explanation": "Soal ini menguji aspek jejaring kerja, khususnya pengelolaan perbedaan pendapat dalam tim. Opsi C paling ideal karena pegawai mengedepankan dialog dan kesepakatan bersama demi hasil terbaik, sedangkan opsi D paling rendah karena pegawai mengabaikan koordinasi sehingga kerja tim terpecah. Urutan skor: C (5), E (4), A (3), B (2), D (1).", "category": "Jejaring Kerja", "difficulty": "medium"}, {"explanation_detail": {"v": 1, "answer": "B", "summary": "Jawaban terbaik adalah opsi B (skor 5). Pegawai mendiskusikan kesempatan pelatihan dengan atasan dan menyiapkan serah terima pekerjaan sebelum berangkat bila disetujui, sehingga pengembangan diri tercapai tanpa mengorbankan pekerjaan tim.", "concept": "Soal ini menguji aspek profesionalisme, khususnya keseimbangan antara pengembangan diri dan tanggung jawab tim. ASN yang ideal memanfaatkan kesempatan meningkatkan kompetensi dengan tetap berkoordinasi dan memastikan pekerjaan tertangani.", "steps": ["Koordinasi dengan atasan: keputusan diambil bersama, bukan sepihak.", "Tanggung jawab tim: pekerjaan diserahterimakan agar tetap berjalan selama pelatihan.", "Pengembangan kompetensi: kesempatan belajar dimanfaatkan secara bertanggung jawab."], "options": {"A": "Skor 3: Mengikuti pelatihan sambil mengerjakan tugas tim membuat fokus terbagi sehingga keduanya berisiko tidak optimal.", "B": "Skor 5: Berdiskusi dengan atasan dan menyiapkan serah terima pekerjaan menyeimbangkan pengembangan diri dan tanggung jawab tim.", "C": "Skor 4: Meminta penjadwalan ulang ke angkatan berikutnya sudah berkoordinasi dan menjaga pekerjaan tim, tetapi menunda kesempatan pengembangan diri.", "D": "Skor 2: Melepaskan kesempatan pelatihan menunjukkan kepedulian pada tim, tetapi mengabaikan pentingnya pengembangan kompetensi.", "E": "Skor 1: Langsung mendaftar tanpa koordinasi adalah keputusan sepihak demi kepentingan pribadi."}, "tips": "Skor 5 tetap meraih kesempatan pengembangan diri melalui koordinasi dan serah terima, sedangkan skor 4 memilih menunda kesempatan itu.", "reference": "Nilai dasar ASN BerAKHLAK: Kompeten", "generated_at": "2026-11-08T15:43:30Z"}, "explanation_detail_at": "2026-11-08T15:43:30Z", "subtest": "tkp", "question_number": 106, "question_text": "Anda mendapat kesempatan mengikuti pelatihan yang bermanfaat bagi pengembangan karier, tetapi jadwalnya bersamaan dengan periode kerja tim yang sedang padat. Sikap Anda ...", "options": [{"key": "A", "text": "Saya mengikuti pelatihan sambil tetap mengerjakan tugas tim secara daring di sela-sela sesi."}, {"key": "B", "text": "Saya mendiskusikannya dengan atasan dan menyiapkan serah terima pekerjaan sebelum mengikuti pelatihan bila disetujui."}, {"key": "C", "text": "Saya meminta atasan agar keikutsertaan saya dijadwalkan ulang pada angkatan pelatihan berikutnya yang lebih longgar."}, {"key": "D", "text": "Saya melepaskan kesempatan pelatihan tersebut karena pekerjaan tim saat ini lebih penting."}, {"key": "E", "text": "Saya langsung mendaftar pelatihan tersebut karena pengembangan diri merupakan hak yang dimiliki setiap pegawai."}], "correct_answer": null, "scores": {"A": 3, "B": 5, "C": 4, "D": 2, "E": 1}, "explanation": "Soal ini menguji aspek profesionalisme, khususnya keseimbangan pengembangan diri dan tanggung jawab tim. Opsi B paling ideal karena pegawai berkomunikasi dengan atasan dan memastikan pekerjaan tim tetap tertangani, sedangkan opsi E paling rendah karena pegawai mengambil keputusan sepihak demi kepentingan pribadi tanpa koordinasi. Urutan skor: B (5), C (4), A (3), D (2), E (1).", "category": "Profesionalisme", "difficulty": "hard"}]$skdset2$::jsonb) AS r(
    subtest text, question_number int, question_text text, options jsonb,
    correct_answer text, scores jsonb, explanation text, category text, difficulty text,
    explanation_detail jsonb, explanation_detail_at timestamptz
  );

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted <> 106 THEN
    RAISE EXCEPTION 'Jumlah soal masuk % (seharusnya 106)', v_inserted;
  END IF;
END
$do$;

COMMIT;

